INSERT INTO `lowcode_dbform_enhance_js` VALUES (1833057424873385985, '1', 1, '2024-09-09 16:18:41', 101, 1, '2024-09-10 10:07:07', 0, 1833055212327694337, 'js', '');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1833320023661780994, NULL, NULL, NULL, NULL, 1, '2024-09-14 09:13:06', 0, 1833320018125299714, 'js', '\n//初始化来访记录表\n\n//初始化控件\nuseFun.controlInit(\'TableView\', \'tableView_visitor\', {\n  tableId: \'1833326225296814081\', //表单开发id\n  fixedSearch: {}, //固定表格搜索值（不会被覆盖）\n  enhanceData: {}, //传递给表格js增强内部调用配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  enhanceData: {}, //传递给表格js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'测试控件\', //标题\n    width: \'60%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { tableView_visitor } = Vue.toRefs(rendControlData.value)\n\n\nreturn {\n  addVisitor(row) {\n    const controlData = tableView_visitor.value.params //TableView的配置\n    controlData.fixedSearch.user_id = row.id\n    tableView_visitor.value.show = true //显示TableView\n  }\n}\n\n\n');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1833326383283662850, '1', 1, '2024-09-10 10:07:26', 101, 1, '2024-12-03 11:42:45', 0, 1833055212327694337, 'js', '\nreturn {\n  initOption() { //表格显示前执行\n    //禁用年龄\n    useFun.setPropConfig(\'age\', { disabled: true, controls: false })\n    //选择出生日期后自动填写年龄\n    useFun.setPropConfig(\'birth_date\', {\n      change: ({ value, column }) => { //监听值变化\n        let age = null\n        if (value) {\n          const currDate = new Date()\n          const birthDate = new Date(value)\n          age = currDate.getFullYear() - birthDate.getFullYear();\n          if (currDate.getMonth() < birthDate.getMonth() ||\n            (currDate.getMonth() === birthDate.getMonth() && currDate.getDate() < birthDate.getDate())) {\n            age--;\n          }\n        }\n        tableForm.value.age = age\n      },\n    })\n  },\n  cellStyle({ row, column, rowIndex, columnIndex }) { //列样式\n    //设置姓名列字体颜色、鼠标样式\n    if (column.columnKey == \'name\') {\n      return {\n        color: \'#409EFF\',\n        cursor: \'pointer\',\n      }\n    }\n  },\n  cellClick(row, column, cell, event) { //单元格单击\n    //点击姓名打开详情\n    if (column.columnKey == \'name\') {\n      crudRef.value.rowEdit(row, row.$index)\n    }\n  },\n  selectable(row, index) { //控制行是否可勾选\n    //小于30岁的不能勾选\n    if (row.age < 30) return false\n    return true\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1833331785496858626, '1', 1, '2024-09-10 10:28:54', 101, NULL, NULL, 0, 1833326225296814081, 'js', 'return {\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if ([\'add\', \'edit\'].includes(type)) apiData.user_id = props.fixedSearch.user_id\n      resolve(apiData)\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1833347204588834817, '1', 1, '2024-09-10 11:30:10', 101, 1, '2024-10-30 09:42:59', 0, 1833323260582391810, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.hideHeader == \'disabled\') {\n      tableOption.value.header = false\n      tableOption.value.border = false\n      tableOption.value.selection = false\n      buttonObj.value.menu[\'delBtn\'].display = false\n      buttonObj.value.menu[\'editBtn\'].display = false\n      buttonObj.value.menu[\'viewBtn\'].label = \'详情\'\n    }\n\n    useFun.setPropConfig(\'client_status\', {\n      render: (optins) => {\n        let { row, column } = optins    //row是当行数据  column是字典数据\n        let statusTitle = \'\'\n        let status = row.client_status\n        if (status && column.dicData[status - 1]) {\n          statusTitle = column.dicData[status - 1].label\n          let bgColor = \'#52C1F5\'\n          const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: bgColor, marginRight: \'5px\' } }, \'\')\n          return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, statusTitle])\n        }\n        return \'\'\n\n      }\n    })\n  },\n}\n');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1834136631567851522, NULL, NULL, NULL, NULL, 1, '2024-09-13 18:03:42', 0, 1834136609367400450, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.hideHeader == \'disabled\') {\n      tableOption.value.selection = false\n    }\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      if (data.length > 0) {\n        data.forEach(ele => {\n          ele.tabs_card_percentage_complete = ele.tabs_card_percentage_complete + \'%\'\n          ele.tabs_card_target_money = \'￥\' + this.changeTwoDecimal_f(ele.tabs_card_target_money)\n          ele.tabs_card_accomplish_money = \'￥\' + this.changeTwoDecimal_f(ele.tabs_card_accomplish_money)\n          ele.tabs_card_average_price = \'￥\' + this.changeTwoDecimal_f(ele.tabs_card_average_price)\n        })\n      }\n      resolve(data)\n    })\n  },\n  changeTwoDecimal_f(x) {\n    var f_x = parseFloat(x);\n    if (isNaN(f_x)) {\n      return false;\n    }\n    var f_x = Math.round(x * 100) / 100;\n    var s_x = f_x.toString();\n    var pos_decimal = s_x.indexOf(\'.\');\n    if (pos_decimal < 0) {\n      pos_decimal = s_x.length;\n      s_x += \'.\';\n    }\n    while (s_x.length <= pos_decimal + 2) {\n      s_x += \'0\';\n    }\n    return s_x;\n  },\n  sjcToDate(date) {\n    var newDate = new Date(date);\n    let nian = newDate.getFullYear();\n    let yue = (newDate.getMonth() + 1 < 10 ? \'0\' + (newDate.getMonth() + 1) : newDate.getMonth() + 1);\n    return nian + \'年\' + yue + \'月\'\n  },\n  summaryTopFormatting(data) { //表格头部统计格式化\n    if (data[0] && data[0].chartOption) {\n\n      let echartData = data[0].chartOption\n      echartData.xAxis.data = echartData.xAxis.data.map(item => {\n        return this.sjcToDate(parseInt(item))\n      })\n      let legendDataList = []\n\n      let seriesToLegend = echartData.series[0].data;\n      if (seriesToLegend.length > 0) {\n        legendDataList = seriesToLegend[0].split(\' \')\n      }\n      echartData.legend = {\n        data: legendDataList,\n      }\n\n      echartData.series = []\n\n      let targetList = []\n      let accomplishList = []\n\n      if (data[0].rawData) {\n        data[0].rawData.forEach(rawEle => {\n          targetList.push(rawEle.target)\n          accomplishList.push(rawEle.accomplish)\n        })\n      }\n\n      legendDataList.forEach(ele => {\n        let sData = {\n          name: ele,\n          type: \'bar\',\n          data: []\n        }\n        echartData.series.push(sData)\n      })\n\n      echartData.series[0].data = targetList\n      echartData.series[0].color = \'#26A8FF\'\n      echartData.series[1].data = accomplishList\n      echartData.series[1].color = \'#FF8E9D\'\n\n      data[0].chartStyle.height = \'380px\'\n    }\n    return data\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1834409013264142338, '1', 1, '2024-09-13 09:49:25', 101, NULL, NULL, 0, 1834136609367400450, 'scss', '// 表格样式\n.low-table__1834136609367400450 {\n\n  .summary-top-content {\n    .content-item {\n      .item-title {\n        display: none;\n      }\n    }\n  }\n  \n}\n\n// 表单弹窗样式\n.low-table__dialog__1834136609367400450 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1836304148777742338, '1', 1, '2024-09-18 15:20:01', 101, 1, '2024-09-19 14:33:01', 0, 1836298963389067265, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.hideHeader == \'disabled\') {\n      tableOption.value.selection = false\n    }\n  },\n  summaryBottomFormatting(sums, columns, tableData) { //表格底部统计格式化\n    let newSums = sums.map(item => {\n      if (item == \'-\') {\n        return \'\'\n      } else {\n\n        let je = item.children[0].children[1].children\n        if (isNaN(parseFloat(je))) return false\n        let newJe = Math.round(je * 100) / 100\n        let newJeString = newJe.toString()\n        let newJeLength = newJeString.indexOf(\'.\')\n        if (newJeLength < 0) {\n          newJeLength = newJeString.length;\n          newJeString += \'.\'\n        }\n        while (newJeString.length <= newJeLength + 2) {\n          newJeString += \'0\'\n        }\n        item.children[0].children[1].children = \'￥\' + newJeString\n        return item\n      }\n    })\n    console.log(newSums, tableData, \'ahgahgi\')\n\n    return newSums\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1836318545076105218, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1836318516001189890, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.hideHeader == \'disabled\') {\n      tableOption.value.selection = false\n    }\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1836649648873832449, '1', 1, '2024-09-19 14:12:54', 101, 1, '2024-11-11 15:18:27', 0, 1836298963389067265, 'scss', '// 表格样式\n.low-table__1836298963389067265 {\n  padding: 0 20px;\n\n  .el-form {\n    border: 1px solid #f2f2f2;\n\n    .el-table__inner-wrapper {\n      &::before {\n        height: 0;\n      }\n\n      .el-table__footer-wrapper {\n        .el-table__footer {\n          height: 55px;\n          background-color: rgba(245, 245, 245, 1);\n\n          td {\n            border-right: none;\n          }\n\n          td:last-child {\n            span {\n              font-size: 16px;\n\n              &:last-child {\n                color: red;\n                font-weight: bold;\n              }\n            }\n          }\n        }\n      }\n\n      .el-table__row {\n        height: 80px;\n      }\n    }\n  }\n\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1836298963389067265 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1837028238614335490, '1', 1, '2024-09-20 15:17:17', 101, 1, '2024-11-11 15:20:58', 0, 1836318516001189890, 'scss', '// 表格样式\n.low-table__1836318516001189890 {\n    padding: 0 20px;\n\n    .el-form {\n        border: 1px solid #f2f2f2;\n\n        .el-table__inner-wrapper {\n            &::before {\n                height: 0;\n            }\n\n            .el-table__row {\n                height: 55px;\n            }\n        }\n    }\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1836318516001189890 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838397485169008642, '1', 1, '2024-09-24 09:58:11', 101, 1, '2024-10-23 10:58:18', 0, 1838392378859741185, 'js', '//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_61357\', {\n  controlName: \'stepverticalform\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowexample/form/step/StepVerticalForm.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'新增客户\', //标题\n    width: \'\', //弹窗宽度\n    fullscreen: true, //是否全屏\n    footerBtn: [ //底部按钮配置\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\nlet Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\nreturn {\n\n  initOption() { //表格显示前执行\n    useFun.setPropConfig(\'customer_status\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let status = \'\'\n        let customer_status = row.customer_status\n        column.dicData.some(item => {\n          if (item.value == customer_status) {\n            status = item.label\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: \'#52C1F5\', marginRight: \'5px\' } }, \'\')\n        return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, status])\n      }\n    })\n  },\n\n  add_customer() {\n    //控件调用\n    const { controlView_61357 } = Vue.toRefs(rendControlData.value)\n    controlView_61357.value.show = true //显示ControlView\n    const controlData = controlView_61357.value.params //ControlView的配置\n    controlData.controlParams = {\n      addFun: (formData) => {\n        useFun.requestApi(\'post\', \'/jeelowcode/dbform-data/save/1838392378859741185\', {\n          data: formData\n        }).then(res => {\n          message.success(\'保存成功\')\n          controlView_61357.value.show = false\n          useFun.refreshChange()\n        })\n      }\n    }\n  },\n  qrBtn() {\n    message.success(\'已确认\')\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise(async (resolve, reject) => {\n      if (type == \'edit\') {\n        await useFun.dynamicImport(\'store/modules/user\').then(module => {\n          if (module) {\n            const userStore = module.useUserStoreWithOut()\n            apiData.update_user = userStore.user.id\n          }\n        })\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}\n\n');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838494758125236225, NULL, NULL, NULL, NULL, 1, '2024-10-24 15:45:16', 0, 1838494733815050242, 'js', 'return {\n  initOption() { //表格显示前执行\n    buttonObj.value.header.addBtn.label = \'新建\'\n    buttonObj.value.menu.delBtn.params.size = \"small\"\n    buttonObj.value.menu.editBtn.params.size = \"small\"\n\n    useFun.setPropConfig(\'xs\', {\n      cell: true,\n      dicData: [\n        { label: \'关\', value: 0 },\n        { label: \'开\', value: 1 }\n      ]\n    })\n\n    useFun.setPropConfig(\'zt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let status = \'\'\n        let zt = row.zt\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == zt) {\n            status = item.label\n            zt == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (status) return h(\'span\', { style: { display: \'flex\', color: \'#999999\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, status])\n      }\n    })\n\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      data.map(item => {\n        item.$cellEdit = true\n      })\n      resolve(data)\n    })\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.xs = \'1\'\n        apiData.zt = \'1\'\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838510799928754177, '1', 1, '2024-09-24 17:28:27', 101, 1, '2024-10-23 14:19:11', 0, 1838505719016001538, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\nreturn {\n  initOption() { //表格显示前执行\n    buttonObj.value.header.addBtn.label = \'新建\'\n    buttonObj.value.menu.delBtn.params.size = \"small\"\n    buttonObj.value.menu.editBtn.params.size = \"small\"\n    useFun.setPropConfig(\'bh\', { fixed: true })\n    useFun.setPropConfig(\'company_name\', { fixed: true })\n\n    useFun.setPropConfig(\'customer_star\', {\n      render: ({ row }) => {\n        if (Icon) {\n          const starList = []\n          for (let index = 0; index < 5; index++) {\n            starList.push(h(Icon, { size: 14, color: row.customer_star > index ? \'#F56C6C\' : \'#999\', icon: row.customer_star > index ? \'streamline:star-1-solid\' : \'streamline:star-1\', style: { marginLeft: \'1px\' } }))\n          }\n          return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, starList)\n        }\n        return \'\'\n      }\n    })\n\n    useFun.setPropConfig(\'customer_status\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let status = \'\'\n        let customer_status = row.customer_status\n        column.dicData.some(item => {\n          if (item.value == customer_status) {\n            status = item.label\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: \'#52C1F5\', marginRight: \'5px\' } }, \'\')\n        return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, status])\n      }\n    })\n\n  },\n  ktBtn() {\n    message.success(\'已开通\')\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise(async (resolve, reject) => {\n      if (type == \'add\') {\n        apiData.bh = \'202410001\'\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838749951945408514, '1', 1, '2024-09-25 09:18:46', 101, 1, '2024-10-23 14:16:50', 0, 1838748849153835009, 'js', 'return {\n  initOption() { //表格显示前执行\n    buttonObj.value.menu.delBtn.params.size = \"small\"\n    buttonObj.value.menu.editBtn.params.size = \"small\"\n    //多级表头处理\n    const children = []\n    const props = [\'khzt\', \'hylx\', \'khly\']\n    for (const prop in tableOption.value.column) {\n      if (props.includes(prop)) {\n        const column = tableOption.value.column[prop]\n        column.hide = false\n        children.push(column)\n        delete tableOption.value.column[prop]\n      }\n    }\n    useFun.setPropConfig(\'djbt\', { children })\n\n    //自定义渲染\n    useFun.setPropConfig(\'khzt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let status = \'\'\n        let khzt = row.khzt\n        column.dicData.some(item => {\n          if (item.value == khzt) {\n            status = item.label\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: \'#52C1F5\', marginRight: \'5px\' } }, \'\')\n        return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, status])\n      }\n    })\n    console.log(tableOption.value)\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.bh = \'202010001\'\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838756731131854849, '1', 1, '2024-09-25 09:45:42', 101, 1, '2024-10-24 09:39:35', 0, 1838754174162501633, 'js', 'return {\n  initOption() { //表格显示前执行\n   tableOption.value.defaultExpandAll = true\n    tableOption.value.menuWidth = 250\n    buttonObj.value.menu.addChild.label = \'添加\'\n    buttonObj.value.header.addBtn.label = \'新建\'\n    useFun.setPropConfig(\'status\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.status\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\' } }, [radius, reStatus])\n      }\n    })\n  },\n\n\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise(async (resolve, reject) => {\n      if (type == \'add\') {\n        apiData.classification_number = \'202410001\'\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838824839188107265, NULL, NULL, NULL, NULL, 1, '2024-10-25 13:47:41', 0, 1838824808796180481, 'js', 'return {\n  initOption() { //表格显示前执行\n    buttonObj.value.menu.qrBtn.type = \'success\'\n    buttonObj.value.header.addBtn.label = \'新建客户\'\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838827089096658945, '1', 1, '2024-09-25 14:25:16', 101, 1, '2024-10-30 17:16:42', 0, 1838141821641318402, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\nreturn {\n  initOption() { //表格显示前执行\n    buttonObj.value.menu.viewBtn.label = \"详情\"\n    buttonObj.value.header.addBtn.label = \'新建专题\'\n    //点赞等图标的点击事件\n    const clickFun = (row, type) => {\n      tableData.value[row.$index][type] = (row[type] || 0) + 1\n    }\n\n    tableOption.value.column.num_list = {\n      label: \'\',\n      display:false,\n      render: ({ row }) => {\n        if (Icon) {\n          const opData = [\n            { key: \'dz_num\', icon: \'uiw:like-o\' },\n            { key: \'sc_num\', icon: \'solar:star-outline\' },\n            { key: \'pl_num\', icon: \'fluent:comment-16-regular\' },\n          ]\n          const hList = opData.map(item => {\n            return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', cursor: \'pointer\' }, onClick: () => clickFun(row, item.key) },\n              [\n                h(Icon, { icon: item.icon, size: 12 }),\n                h(\'span\', { style: { marginLeft: \'2px\' } }, row[item.key] || 0),\n              ])\n          })\n\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', columnGap: \'15px\', fontSize: \'12px\', color: \'#999\' },\n          }, hList)\n        }\n        return \'\'\n      }\n    }\n    tableOption.value.column.time_test = {\n      display:false,\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\' },\n          }, [\n            h(Icon, { icon: \'mingcute:time-line\', size: 14 }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, useFun.formatPast(row.create_time, \'YYYY-MM-DD\')),\n          ])\n        }\n        return \'\'\n      }\n    }\n    useFun.setPropConfig(\'zt_title\', {\n      searchLabel: \'\',\n      searchLabelWidth: 1,\n      searchSpan: 5,\n      searchPlaceholder: \'输入搜索关键字\',\n    })\n    useFun.setPropConfig(\'zt_type\', {\n      searchLabel: \'\',\n      searchLabelWidth: 10,\n      searchSpan: 5,\n      searchPlaceholder: \'分类名称\',\n      dicData: [\n        { label: \'设计方案\', value: \'1\' },\n        { label: \'模板示例\', value: \'2\' },\n      ]\n    })\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838830826053750785, '1', 1, '2024-09-25 14:40:07', 101, 1, '2024-10-23 15:09:23', 0, 1838141821641318402, 'scss', '// 表格样式\n.low-table__1838141821641318402 {\n  .avue-crud__grid__content {\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n\n      &.zt_img {\n        width: 100%;\n        aspect-ratio: 1 / 0.56; //保持元素纵横比\n      }\n\n      .low-field__zt_img {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 100%;\n\n        .avue-crud__img {\n          width: 100%;\n\n          img {\n            width: 100%;\n            height: 56%;\n            margin-right: 0 !important;\n            object-fit: cover\n          }\n        }\n      }\n\n      &.zt_title {\n        margin-top: 10px;\n        font-size: 14px;\n        color: #333;\n      }\n\n      &.zt_type {\n        font-size: 14px;\n        color: #999;\n      }\n\n      &.time_test {\n        position: absolute;\n        left: 16px;\n        bottom: 5px;\n        width: 94px;\n      }\n\n      &.menu {\n        margin-top: 4px;\n        .el-button {\n          color: #999999;\n\n          &:hover {\n            color: #666666;\n            background-color: rgba(255, 255, 255, 0);\n          }\n        }\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838141821641318402 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1838857897740099586, '1', 1, '2024-09-25 16:27:42', 101, 1, '2024-10-23 15:23:06', 0, 1838855934516420610, 'scss', '// 表格样式\n.low-table__1838855934516420610 {\n  .avue-crud__grid__content {\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n      font-family: \'微软雅黑\';\n\n      &.crad_img {\n        position: absolute;\n        left: 16px;\n        top: 16px;\n        width: calc(100% - 16px);\n\n        img {\n          width: 60px;\n          height: 60px;\n        }\n      }\n\n      &.crad_title,\n      &.card_describe {\n        padding-left: 80px;\n      }\n\n      &.crad_title {\n        .avue-crud__grid__value {\n          font-size: 16px;\n          font-weight: bold;\n          color: #666;\n        }\n      }\n\n      &.card_describe {\n        margin-top: 5px;\n        color: #999;\n\n        .avue-crud__grid__value {\n          display: -webkit-box;\n          -webkit-box-orient: vertical;\n          -webkit-line-clamp: 3;\n          overflow: hidden;\n          text-overflow: ellipsis;\n          white-space: normal;\n        }\n      }\n\n      &.menu {\n        padding: 0;\n\n        .avue-crud__grid__value {\n          width: 100%;\n\n          .avue-crud__menu {\n            width: 100%;\n\n            .table-button {\n\n              .menu-button {\n                height: 40px;\n                justify-content: space-around;\n\n                .el-button {\n                  font-size: 12px;\n                  color: #999999;\n\n                  &:hover {\n                    color: #666666;\n                    background-color: rgba(255, 255, 255, 0);\n                  }\n                }\n              }\n\n\n            }\n\n\n          }\n        }\n\n\n\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838855934516420610 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1839483468484493314, '1', 1, '2024-09-27 09:53:29', 101, NULL, '2024-11-14 14:32:08', 0, 1838392378859741185, 'scss', '// 表格样式\n.low-table__1838392378859741185 {\n\n  .avue-crud__search {\n    .avue-form__group {\n      .no-print {\n        margin-top: 0px;\n      }\n    }\n  }\n\n  .el-card__body {\n    .avue-crud__header {\n      .avue-crud__right {\n        .avue-crud__searchBtn {\n          display: none;\n        }\n      }\n    }\n\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .el-form {\n      .el-table__header {\n        .el-table__cell {\n          height: 55px;\n          background-color: #F2F2F2;\n\n          span {\n            color: #666666;\n          }\n        }\n\n      }\n\n      .el-table__body-wrapper {\n        .el-table__cell {\n          height: 55px;\n        }\n\n        .cell>span {\n          color: #666666;\n        }\n      }\n    }\n  }\n\n  .avue-crud__pagination {\n    span {\n      color: #999999;\n    }\n  }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838392378859741185 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1839486029383909377, '1', 1, '2024-09-27 10:03:40', 101, 1, '2024-10-24 15:43:38', 0, 1838494733815050242, 'scss', '// 表格样式\n.low-table__1838494733815050242 {\n\n  .el-card__body {\n\n    .avue-crud__tip,\n    .avue-crud__header .avue-crud__right {\n      display: none;\n    }\n\n    .el-table--fit {\n      border: 1px solid #ebeef5;\n    }\n\n    .el-form {\n      .el-table__header {\n        .el-table__cell {\n          height: 55px;\n          background-color: #F9F9F9;\n\n          span {\n            color: #666666;\n          }\n        }\n\n      }\n\n      .el-table__body-wrapper {\n        .el-table__row--striped {\n          .el-table__cell {\n            background-color: #F5F5F5;\n          }\n        }\n\n        .el-table__row {\n          .el-table__cell {\n            height: 70px;\n            padding: 0;\n\n            .cell {\n              .table-cell-upload {\n                .avue-crud__img {\n                  width: 55px;\n                  height: 55px;\n                  border-radius: 50%;\n                }\n              }\n\n              .el-button--primary {\n                border: 1px solid #409EFF;\n                background-color: #40a0ff1f;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #409EFF;\n                  color: #fff;\n                }\n              }\n\n              .el-button--success {\n                border: 1px solid #67C23A;\n                background-color: #67c23a1d;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #67C23A;\n                  color: #fff;\n                }\n              }\n\n              .el-button--danger {\n                border: 1px solid #F67E7E;\n                background-color: #f67e7e15;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #F67E7E;\n                  color: #fff;\n                }\n              }\n            }\n\n          }\n        }\n\n        .cell>span {\n          color: #666666;\n        }\n      }\n    }\n  }\n\n  .avue-crud__pagination {\n    span {\n      color: #999999;\n    }\n  }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838494733815050242 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1839543591135473665, '1', 1, '2024-09-27 13:52:24', 101, 1, '2024-10-23 14:41:01', 0, 1838505719016001538, 'scss', '// 表格样式\n.low-table__1838505719016001538 {\n  .el-card__body {\n\n    .avue-crud__tip,\n    .avue-crud__header .avue-crud__right .avue-crud__searchBtn {\n      display: none;\n    }\n\n    .el-form {\n\n      .el-table__header {\n        .el-table__cell {\n          height: 55px;\n          background-color: #F9F9F9;\n\n          span {\n            color: #666666;\n          }\n        }\n\n      }\n\n\n      .el-table__body-wrapper {\n\n        .el-table__row--striped {\n          .el-table__cell {\n            background-color: #F5F5F5;\n          }\n        }\n\n        .el-table__row {\n          .el-table__cell {\n            height: 55px;\n            padding: 0;\n\n            .cell {\n              .el-button--primary {\n                border: 1px solid #409EFF;\n                background-color: #40a0ff1f;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #409EFF;\n                  color: #fff;\n                }\n              }\n\n              .el-button--success {\n                border: 1px solid #67C23A;\n                background-color: #67c23a1d;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #67C23A;\n                  color: #fff;\n                }\n              }\n\n              .el-button--danger {\n                border: 1px solid #F67E7E;\n                background-color: #f67e7e15;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #F67E7E;\n                  color: #fff;\n                }\n              }\n            }\n\n            .cell>span {\n              color: #666666;\n            }\n          }\n        }\n      }\n    }\n  }\n\n\n\n\n  .avue-crud__pagination {\n    span {\n      color: #999999;\n    }\n  }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838505719016001538 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1839544988077780993, '1', 1, '2024-09-27 13:57:57', 101, 1, '2024-10-23 14:15:13', 0, 1838748849153835009, 'scss', '// 表格样式\n.low-table__1838748849153835009 {\n  .el-card__body {\n    .avue-crud__tip,\n    .avue-crud__header .avue-crud__right .avue-crud__searchBtn {\n      display: none;\n    }\n\n    .el-form {\n      .el-table__header {\n        .el-table__cell {\n          span {\n            color: #666666;\n          }\n        }\n\n      }\n\n\n      .el-table__body-wrapper {\n        .el-table__row--striped {\n          .el-table__cell {\n            background-color: #F5F5F5;\n          }\n        }\n\n        .el-table__row {\n          .el-table__cell {\n            .cell {\n              .el-button--primary {\n                border: 1px solid #409EFF;\n                background-color: #40a0ff1f;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #409EFF;\n                  color: #fff;\n                }\n              }\n\n              .el-button--success {\n                border: 1px solid #67C23A;\n                background-color: #67c23a1d;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #67C23A;\n                  color: #fff;\n                }\n              }\n\n              .el-button--danger {\n                border: 1px solid #F67E7E;\n                background-color: #f67e7e15;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #F67E7E;\n                  color: #fff;\n                }\n              }\n            }\n\n            .cell>span {\n              color: #666666;\n            }\n          }\n        }\n      }\n    }\n  }\n\n  .avue-crud__pagination {\n    span {\n      color: #999999;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838748849153835009 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1839558426837397505, '1', 1, '2024-09-27 14:51:21', 101, 1, '2024-10-23 14:49:38', 0, 1838754174162501633, 'scss', '// 表格样式\n.low-table__1838754174162501633 {\n\n  .avue-crud__tip,\n  .avue-crud__header .avue-crud__right .avue-crud__searchBtn {\n    display: none;\n  }\n\n  .el-table--fit {\n    border: 1px solid #ebeef5;\n  }\n\n  .avue-crud .el-button.is-text {\n    height: 25px;\n    border: 1px solid;\n    font-size: 12px;\n    padding: 0px 8px;\n    background: #f0f7ff;\n  }\n\n  .avue-crud .el-button.is-text:frist-child {\n    margin-left: 0;\n  }\n\n  .avue-crud .el-button.is-text:hover {\n    background: #409eff;\n    color: #fff;\n  }\n\n  .avue-crud .el-button.is-text:last-child {\n    background: #fef3f3;\n  }\n\n  .avue-crud .el-button.is-text:last-child:hover {\n    background: #f56c6c;\n    color: #fff;\n  }\n\n  .justify-center {\n    gap: 5px;\n    justify-content: flex-start;\n  }\n\n  th {\n    height: 55px;\n    background: #f2f2f2;\n    font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n    font-weight: 700;\n    font-size: 14px;\n    background: #ccc;\n\n    .cell {\n      text-align: left;\n    }\n  }\n\n  .avue-crud .el-table th.el-table__cell {\n    color: #666;\n  }\n\n  td {\n    height: 55px;\n    font-family: \'MicrosoftYaHei\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n    font-weight: 400;\n    font-style: normal;\n    // text-align: left;\n    color: #666;\n    font-size: 14px;\n\n    .cell {\n      text-align: left;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1838754174162501633 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1840271788504260610, '1', 1, '2024-09-29 14:06:00', 101, 1, '2024-10-19 09:32:25', 0, 1840268794366795777, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.buttonType == \'hidden\') {\n      tableOption.value.header = false\n      buttonObj.value.menu.delBtn.display = false\n      buttonObj.value.menu.editBtn.display = false\n      buttonObj.value.menu.viewBtn.label = \'详情\'\n    }\n    useFun.setPropConfig(\'approval_status\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.approval_status\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1840274927278104578, '1', 1, '2024-09-29 14:18:28', 101, 1, '2024-10-30 10:29:35', 0, 1840268794366795777, 'scss', '// 表格样式\n.low-table__1840268794366795777 {\n  .el-table--fit {\n    border: 1px solid #ebeef5;\n  }\n\n  .el-table__inner-wrapper {\n    .el-table__header {\n      height: 55px;\n\n      .el-table__cell {\n        background: #f2f2f2;\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n      }\n    }\n\n    .el-table__body-wrapper {\n      .el-table__row {\n        height: 55px;\n\n        &.el-table__row--striped {\n\n          .el-table__cell {\n            font-family: \'微软雅黑\', sans-serif;\n            font-weight: 400;\n            background: #f2f2f2;\n          }\n        }\n\n        .justify-center {\n          gap: 5px;\n        }\n\n      }\n\n    }\n\n    .cell>span {\n      color: #666;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1840268794366795777 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1840578167198744577, '1', 1, '2024-09-30 10:23:26', 101, 1, '2024-10-30 11:48:02', 0, 1840577516125323266, 'scss', '// 表格样式\n.low-table__1840577516125323266 {\n\n  .el-checkbox-group>.el-row>.el-col {\n    padding-bottom: 0;\n  }\n\n  .avue-crud__grid__content {\n    height: 38px;\n    padding: 25px;\n    flex-wrap: nowrap;\n    border-radius: 0;\n\n    &::before {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      margin-bottom: 0;\n\n      .avue-crud__grid__label {\n        display: none;\n      }\n\n      .avue-crud__img {\n        border-radius: 50%;\n        border: 2px solid rgba(240, 242, 245, 1);\n        height: 50px;\n        width: 50px;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n\n        img {\n          height: 31px;\n\n        }\n      }\n    }\n\n    span {\n      font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n    }\n\n    .login_tp {\n      width: 75px;\n      padding-right: 25px;\n      display: flex;\n      align-items: center;\n    }\n\n    .login_address {\n      position: absolute;\n      left: 100px;\n      top: 46px;\n\n      span {\n        font-weight: 400;\n        font-size: 14px;\n        color: #999999;\n      }\n    }\n\n    .login_system {\n      position: relative;\n      top: -5px;\n\n      span {\n        font-size: 18px;\n        font-weight: 700;\n      }\n\n    }\n\n\n    .login_ip {\n      position: absolute;\n      top: 46px;\n      left: 190px;\n\n      span {\n        font-weight: 400;\n        font-size: 14px;\n        color: #999999;\n      }\n    }\n\n    .create_time {\n      display: flex;\n      justify-content: right;\n      position: absolute;\n      top: 50%;\n      right: 15px;\n      transform: translate(0, -50%);\n\n      span {\n        font-weight: 400;\n        font-size: 14px;\n        color: #999999;\n      }\n    }\n\n  }\n\n  .avue-crud__pagination {\n    padding-right: 6px;\n\n    .el-pagination__total,\n    .el-pagination__sizes,\n    .el-pagination__jump {\n      display: none;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1840577516125323266 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1840583515909423105, '1', 1, '2024-09-30 10:44:41', 101, 1, '2024-10-30 11:19:55', 0, 1840577516125323266, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\nreturn {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.type == \'view\') {\n      tableOption.value.header = false\n      buttonObj.value.menu.delBtn.display = false\n      buttonObj.value.menu.editBtn.display = false\n      buttonObj.value.menu.viewBtn.display = false\n      tableOption.value.selection = false\n    }\n    useFun.setPropConfig(\'create_time\', {\n      render: ({ row }) => {\n        if (Icon) {\n          let jssjTitle = useFun.formatPast(row.create_time, \'YYYY-MM-DD HH:mm\')\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'11px\' },\n          }, [\n            h(Icon, { icon: \'icon-park-outline:time\', size: 14, color: \'#999999\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, jssjTitle),\n          ])\n        }\n        return \'\'\n      }\n    })\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1840643697989468161, '1', 1, '2024-09-30 14:43:50', 101, 1, '2024-09-30 17:13:31', 0, 1840642756645044226, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.type == \'view\') {\n      tableOption.value.header = false\n      tableOption.value.menu = false\n      buttonObj.value.menu.delBtn.display = false\n      buttonObj.value.menu.editBtn.display = false\n      buttonObj.value.menu.viewBtn.display = false\n      tableOption.value.selection = false\n    }\n    useFun.setPropConfig(\'status\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.status\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n\n  },\n  rowClick(row, column, event) { //行单击\n    props.enhanceData.rowClick(row)\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1840644083169181697, '1', 1, '2024-09-30 14:45:22', 101, 1, '2024-10-30 11:49:24', 0, 1840642756645044226, 'scss', '// 表格样式\n.low-table__1840642756645044226 {\n  .el-table--fit {\n    border: 1px solid #ebeef5;\n  }\n\n  .el-table__inner-wrapper {\n    .el-table__header-wrapper {\n      .el-table__header {\n        .el-table__cell {\n          height: 56px;\n          color: #666666;\n          font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n          background-color: #F2F2F2;\n        }\n      }\n\n    }\n\n    .el-table__body-wrapper {\n      .el-table__cell {\n        height: 55px;\n        color: #666666;\n      }\n    }\n\n    &::before {\n      height: 0;\n    }\n  }\n\n  .avue-crud__pagination {\n    padding-right: 0;\n\n    .el-pagination__total,\n    .el-pagination__sizes,\n    .el-pagination__jump {\n      display: none;\n    }\n\n    .btn-next {\n      margin-right: 0;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1840642756645044226 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1843476655385350146, '1', 1, '2024-10-08 10:20:59', 101, 1, '2024-10-30 13:47:52', 0, 1843476389638443010, 'scss', '// 表格样式\n.low-table__1843476389638443010 {\n\n\n  .el-checkbox-group>.el-row>.el-col {\n    padding-bottom: 0;\n  }\n\n  .avue-crud__grid__content {\n    height: 38px;\n    padding: 25px;\n    flex-wrap: nowrap;\n    border: none;\n    border-bottom: 1px solid #e4e7ed;\n    border-radius: inherit;\n\n    &::before {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      margin-bottom: 0;\n\n      .avue-crud__grid__label {\n        display: none;\n      }\n\n      .avue-crud__img {\n        border-radius: 50%;\n        border: 2px solid rgba(240, 242, 245, 1);\n        height: 48px;\n        width: 48px;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n\n        img {\n          height: 22px;\n          margin-right: 0px !important;\n        }\n      }\n    }\n\n\n    .selection,\n    .menu {\n      display: none;\n    }\n\n    .title {\n      position: absolute;\n      left: 85px;\n      top: 20px;\n\n      .avue-crud__grid__value {\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-size: 14px;\n        color: #666666;\n        font-weight: 700;\n      }\n    }\n\n    .introduce {\n      position: absolute;\n      left: 85px;\n      top: 45px;\n\n      .avue-crud__grid__value {\n        font-family: \'微软雅黑\', sans-serif;\n        font-weight: 400;\n        color: #999999;\n        font-size: 14px;\n      }\n\n    }\n\n    .switch {\n      position: absolute;\n      right: 0px;\n      top: 50%;\n      transform: translate(0, -50%);\n      flex-direction: row-reverse;\n\n      .el-form-item {\n        margin-bottom: 0;\n\n        .el-switch {\n          height: revert-layer;\n\n          .el-switch__core {\n            width: 46px !important;\n            height: 23px;\n            border-radius: 23px;\n\n            //         display: flex;\n            // align-items: center;\n            // justify-content: space-around;\n\n            .el-switch__inner {\n              justify-content: left;\n            }\n          }\n        }\n      }\n    }\n  }\n}\n\n\n// 表单弹窗样式\n.low-table__dialog__1843476389638443010 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1843476895865769986, '1', 1, '2024-10-08 10:21:57', 101, 1, '2024-10-08 11:36:05', 0, 1843476389638443010, 'js', 'return {\n  initOption() { //表格显示前执行\n    useFun.setPropConfig(\'switch\', {\n      cell: true,\n      dicData: [\n        { label: \'关\', value: 0 },\n        { label: \'开\', value: 1 }\n      ]\n    })\n\n    if (props.enhanceData && props.enhanceData.type == \'view\') {\n      tableOption.value.header = false\n      tableOption.value.selection = false\n    }\n\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      data.map(item => {\n        item.$cellEdit = true\n      })\n      resolve(data)\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1844279292464775170, '1', 1, '2024-10-10 15:30:23', 101, NULL, '2024-11-13 15:25:39', 0, 1844275960258019330, 'js', '\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_77755\', {\n  controlName: \'OrderFormView\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowexample/form/OrderFormView.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'订单详情\', //标题\n    width: \'90%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],//底部按钮配置\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_84087\', {\n  formId: \'1844612970545950722\', //表单设计id\n  formType: \'edit\', //表单类型 add | edit | view\n  handleType: \'returnData\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1844275960258019330\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'测试表单\', //标题\n    width: \'40%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],//底部按钮配置\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n\n//控件调用\nconst { controlView_77755, formView_84087 } = Vue.toRefs(rendControlData.value)\n\n// componentRef.value.controlView_77755 ControlView的Ref控件引用\n\nreturn {\n  initOption() {\n    buttonObj.value.header.exportBtn.label = \'导出数据\'\n    tableOption.value.searchShowBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.menuWidth = 250\n    useFun.setPropConfig(\'ddje\', {\n      formatter: (val, value, label) => {\n        return \'￥\' + value\n      }\n    })\n    useFun.setPropConfig(\'ddzt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.ddzt\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'#ff9900\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n    // useFun.setPropConfig(\'ddje\', {\n    //   search: true\n    // })\n\n\n    if (props.enhanceData && props.enhanceData.type && props.enhanceData.type == \'view\') {\n      buttonObj.value.menu.bzBtn.display = false\n      buttonObj.value.menu.gbBtn.display = false\n      tableOption.value.header = false\n      tableOption.value.searchBtn = false\n      tableOption.value.menuWidth = 100\n      tableOption.value.emptyBtn = false\n      tableOption.value.column.ddbh.search = false\n      tableOption.value.column.ddzt.search = false\n      tableOption.value.column.ddlx.search = false\n      tableOption.value.column.ddly.search = false\n      tableOption.value.column.tjsj.search = false\n\n    }\n\n  },\n  xqBtn() {\n    controlView_77755.value.show = true //显示ControlView\n    const controlData = controlView_77755.value.params //ControlView的配置\n  },\n  bzBtn(row) {\n    const controlData = formView_84087.value.params //FormView的配置\n    controlData.defaultData.type = \'bz\'\n    controlData.popOption.title = \'备注订单\'\n    formView_84087.value.show = true //显示FormView\n  },\n  gbBtn(row) {\n    const controlData = formView_84087.value.params //FormView的配置\n    controlData.defaultData.type = \'gbyy\'\n    controlData.popOption.title = \'关闭订单\'\n    formView_84087.value.show = true //显示FormView\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1844645372781670401, '1', 1, '2024-10-11 15:45:03', 101, NULL, '2024-11-12 15:32:12', 0, 1844620967619866625, 'js', '\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_84087\', {\n  formId: \'1844646887256764417\', //表单设计id\n  formType: \'edit\', //表单类型 add | edit | view\n  handleType: \'returnData\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1844620967619866625\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'测试表单\', //标题\n    width: \'40%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],//底部按钮配置\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_77755\', {\n  controlName: \'WorkOrderForm\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowexample/form/WorkOrderForm.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'工单详情\', //标题\n    width: \'90%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],//底部按钮配置\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { formView_84087, controlView_77755 } = Vue.toRefs(rendControlData.value)\n\nreturn {\n  initOption() {\n    tableOption.value.menuWidth = 250\n    buttonObj.value.menu.editBtn.params = {\n      plain: true,\n      text: false,\n      size: \"small\"\n    }\n    buttonObj.value.menu.delBtn.params = {\n      plain: true,\n      text: false,\n      size: \"small\"\n    }\n    buttonObj.value.header.addBtn.label = \'新建工单\'\n    tableOption.value.searchShowBtn = false\n    tableOption.value.columnBtn = false\n    useFun.setPropConfig(\'tjsj\', {\n      width: 180\n    })\n    useFun.setPropConfig(\'gdzt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.gdzt\n        let color = \'#cccccc\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status = status == \'1\' ? color = \'#ff9900\' : status == \'2\' ? color = \'#19be6b\' : status == \'3\' ? color = \'#f56c6c\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n  },\n  xqBtn(row) {\n    if (row.gdzt == 1) {\n      const controlData = formView_84087.value.params //FormView的配置\n      controlData.popOption.title = \'人员处理\'\n      controlData.formId = \'1844666969680785410\'\n      controlData.defaultData = {\n        ...row,\n      }\n      formView_84087.value.show = true //显示FormView\n    } else {\n      controlView_77755.value.show = true //显示ControlView\n      const controlData = controlView_77755.value.params //ControlView的配置\n      controlData.controlParams = {\n        obj: row,\n        type: row.gdzt == 1 ? \'dcl\' : row.gdzt == 2 ? \'ywj\' : row.gdzt == 3 ? \'yth\' : row.gdzt == 4 ? \'ycx\' : \'\',\n      }\n    }\n\n\n  },\n  fpgdBtn() {\n    const controlData = formView_84087.value.params //FormView的配置\n    controlData.popOption.title = \'分配工单\'\n    formView_84087.value.show = true //显示FormView\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1845016912551550977, '1', 1, '2024-10-12 16:21:25', 101, 1, '2024-11-12 09:50:22', 0, 1845012516400803842, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData && props.enhanceData.hideHeader == \'disabled\') {\n      tableOption.value.selection = false\n      for (let key in buttonObj.value.menu) {\n        buttonObj.value.menu[key].params = {\n          plain: true,\n          text: false,\n          size: \"small\"\n        }\n      }\n    }\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1845028903412375553, '1', 1, '2024-10-12 17:09:04', 101, NULL, '2024-11-13 18:01:56', 0, 1845019389086736386, 'js', '//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_user_xq\', {\n  controlName: \'userManagement\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/userManagement/index.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {\n\n  }, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'用户管理\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {\n\n    }, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\nreturn {\n\n  initOption() { //表格显示前执行\n    tableOption.value.menuWidth = 250\n\n    let arr = [\'bjBtn\', \'delBtn\', \'xqBtn\']\n    arr.map(item => {\n      buttonObj.value.menu[item].params = {\n        plain: true,\n        text: false,\n        size: \"small\"\n      }\n    })\n\n    buttonObj.value.header.exportBtn.params = {\n      plain: true,\n      text: false,\n    }\n    buttonObj.value.header.exportBtn.label = \'导出数据\'\n    buttonObj.value.header.exportBtn.type = \'\'\n\n    buttonObj.value.menu.bjBtn.type = \'primary\'\n    useFun.setPropConfig(\'user_type\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.user_type\n        let color = \'#cccccc\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status = status == \'1\' ? color = \'#16A95F\' : color == \'red\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n\n    useFun.setPropConfig(\'order_record\', {\n      render: (optins) => {\n        let { row } = optins\n        let str = row.order_record\n        return h(\'span\', { style: { color: \'#409EFF\' } }, str)\n      }\n    })\n\n    useFun.setPropConfig(\'consumption_amount\', {\n      render: (optins) => {\n        let { row } = optins\n        let str = \'￥\' + row.consumption_amount\n        return str\n      }\n    })\n\n\n  },\n  tjbqBtn() {\n    //初始化控件\n    useFun.controlInit(\'FormView\', \'formView_tjbq\', {\n      formId: \'1845041920745218050\', //表单设计id\n      formType: \'add\', //表单类型 add | edit | view\n      handleType: \'\', //处理类型 default | returnData\n      showType: \'dialog\', //弹窗类型 dialog | drawer\n      showButton: false, //是否显示底部默认操作按钮\n      dataOption: { //数据配置 \n        tableId: \'\', //表单开发id\n        dataId: \'\' //数据id\n      },\n      defaultData: {}, //默认表单数据\n      enhanceData: {}, //传递给表单js增强内部调用配置\n      popOption: { //弹窗配置\n        title: \'标签设置\', //标题\n        width: \'35%\', //弹窗宽度\n        fullscreen: false, //是否全屏\n        footerBtn: [ //底部按钮配置\n          {\n            params: {\n            }, //el-button 其他参数\n            name: \'取消\', //按钮名称\n            display: true, //是否显示\n            loading: true, //点击时是否有loading\n            icon: \'\', //图标\n            clickFun: (loading) => {\n              //点击事件\n              formView_tjbq.value.show = false\n              if (loading) loading() //关闭loading\n            }\n          },\n          {\n            params: {\n              type: \'primary\'\n            }, //el-button 其他参数\n            name: \'确定\', //按钮名称\n            display: true, //是否显示\n            loading: true, //点击时是否有loading\n            icon: \'\', //图标\n            clickFun: (loading) => {\n              //点击事件\n              formView_tjbq.value.show = false\n              message.success(\'添加成功\')\n              if (loading) loading() //关闭loading\n            }\n          }\n        ],\n        headerBtn: [], //顶部按钮配置（配置同上）\n        dialogParams: {} //弹窗其他配置\n      },\n      beforeClose: (type, done, formData, loading) => {\n        // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n        // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n        console.log(\'表单数据\', type, formData)\n        // if (type == \'submit\') {\n        //   console.log(\'表单数据\', formData)\n        // }\n        done()\n      }\n    })\n\n    //控件调用\n    const { formView_tjbq } = Vue.toRefs(rendControlData.value)\n    formView_tjbq.value.show = true //显示FormView\n  },\n  bjBtn(row) {\n    //初始化控件\n    useFun.controlInit(\'FormView\', \'formView_xgzl\', {\n      formId: \'1845639851059728386\', //表单设计id\n      formType: \'edit\', //表单类型 add | edit | view\n      handleType: \'\', //处理类型 default | returnData\n      showType: \'dialog\', //弹窗类型 dialog | drawer\n      showButton: true, //是否显示底部默认操作按钮\n      dataOption: { //数据配置 \n        tableId: \'\', //表单开发id\n        dataId: \'\' //数据id\n      },\n      defaultData: row, //默认表单数据\n      enhanceData: {}, //传递给表单js增强内部调用配置\n      popOption: { //弹窗配置\n        title: \'标签设置\', //标题\n        width: \'580px\', //弹窗宽度\n        fullscreen: false, //是否全屏\n        footerBtn: [ //底部按钮配置\n\n        ],\n        headerBtn: [], //顶部按钮配置（配置同上）\n        dialogParams: {} //弹窗其他配置\n      },\n      beforeClose: (type, done, formData, loading) => {\n        // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n        // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n        console.log(\'表单数据\', type, formData)\n        if (type == \'submit\') {\n          useFun.refreshChange()\n        }\n        done()\n      }\n    })\n\n    //控件调用\n    const { formView_xgzl } = Vue.toRefs(rendControlData.value)\n    formView_xgzl.value.show = true //显示FormView\n\n  },\n\n  xqBtn(row) {\n    //控件调用\n    const { controlView_user_xq } = Vue.toRefs(rendControlData.value)\n    controlView_user_xq.value.show = true //显示ControlView\n    const controlData = controlView_user_xq.value.params //ControlView的配置\n    controlData.controlParams = { data: row }\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1845033165957701634, '1', 1, '2024-10-12 17:26:00', 101, NULL, '2024-11-13 14:26:18', 0, 1845019389086736386, 'scss', '// 表格样式\n.low-table__1845019389086736386 {\n\n  .avue-crud {\n\n    .avue-crud__body {\n      .el-card__body {\n        .avue-crud__header {\n          .avue-crud__left {\n            .el-button {\n              // background-color: rgba(255, 255, 255, 0);\n              // color: #999999;\n              // border: 1px solid #E4E4E4;\n              // font-size: 14px;\n\n              &:hover {\n                background-color: #40a0ff2e;\n                color: #409EFF;\n                border: 1px solid #409EFF;\n              }\n            }\n          }\n\n          .avue-crud__right {\n            .avue-crud__searchBtn {\n              display: none;\n            }\n          }\n        }\n\n        .avue-crud__tip {\n          display: none;\n        }\n\n        .el-form {\n          border-left: 1px solid #E9E9E9;\n          border-right: 1px solid #E9E9E9;\n        }\n      }\n    }\n\n    .el-table__cell {\n      border-right: none;\n    }\n  }\n\n  .el-table__inner-wrapper {\n    .el-table__header {\n      height: 55px;\n\n      .el-table__cell {\n        background: #f2f2f2;\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n      }\n    }\n\n    .el-table__body-wrapper {\n      .el-table__row {\n        height: 55px;\n\n        .el-table__cell {\n          font-family: \'微软雅黑\', sans-serif;\n          font-weight: 400;\n        }\n      }\n    }\n\n    .cell>span {\n      color: #666;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1845019389086736386 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846015584845914114, '1', 1, '2024-10-15 10:29:47', 101, NULL, '2024-11-12 14:17:05', 0, 1846009550756601857, 'js', '\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_72662\', {\n  formId: \'1846027395603243010\', //表单设计id\n  formType: \'edit\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1846009550756601857\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {\n    zt: 1\n  }, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'设置状态\', //标题\n    width: \'40%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n//控件调用\nconst { formView_72662 } = Vue.toRefs(rendControlData.value)\n\n// componentRef.value.formView_72662 FormView的Ref控件引用\n\n\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.defaultExpandAll = true\n    tableOption.value.menuWidth = 350\n    buttonObj.value.header.addBtn.label = \'新建部门\'\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.searchShowBtn = false\n    let arr = [\'addChild\', \'delBtn\', \'editBtn\', \'szztBtn\']\n    arr.map(item => {\n      buttonObj.value.menu[item].params = {\n        plain: true,\n        text: false,\n        size: \"small\"\n      }\n    })\n\n    useFun.setPropConfig(\'time\', {\n      width: 180,\n    })\n    useFun.setPropConfig(\'zt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.zt\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.zt = 1\n        apiData.cysl = 100\n        apiData.time = useFun.formatDate(new Date, \'YYYY-MM-DD HH:mm:ss\')\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n  cellStyle({ row, column, rowIndex, columnIndex }) { //列样式\n    if (columnIndex == 3) {\n      return {\n        color: \'#409eff\'\n      }\n    }\n  },\n  szztBtn(row) {\n    formView_72662.value.show = true //显示FormView\n    const controlData = formView_72662.value.params //FormView的配置\n  },\n  qbzkBtn() {\n    tableOption.value.defaultExpandAll = true\n    crudRef.value.refreshTable()\n  },\n  qbzdBtn() {\n    tableOption.value.defaultExpandAll = false\n    crudRef.value.refreshTable()\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846074006584827906, NULL, NULL, NULL, NULL, NULL, '2024-11-13 16:22:42', 0, 1846073998846337026, 'scss', '// 表格样式\n.low-table__1846073998846337026 {\n\n  .el-form {\n    border: 1px solid #E9E9E9;\n    border-bottom: none;\n    margin-bottom: 15px;\n\n    .el-table__inner-wrapper {\n\n      .el-table__header {\n        .el-table__cell {\n          height: 55px;\n\n          .cell {\n            span {\n              color: #666666;\n              font-size: 14px;\n              font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            }\n          }\n        }\n\n      }\n\n      .el-table__body-wrapper {\n        .el-table__row {\n          height: 55px;\n\n          .el-table__cell {\n            span {\n              color: #666666;\n              font-size: 14px;\n              font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            }\n          }\n        }\n\n      }\n    }\n  }\n\n}\n\n\n// 表单弹窗样式\n.low-table__dialog__1846073998846337026 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846074006593216513, NULL, NULL, NULL, NULL, 1, '2024-10-15 14:47:55', 0, 1846073998846337026, 'js', 'return {\n  initOption() { //表格显示前执行\n    useFun.setPropConfig(\'default_address\', {\n      cell: true,\n      dicData: [\n        { label: \'关\', value: 0 },\n        { label: \'开\', value: 1 }\n      ]\n    })\n\n    if (props.enhanceData && props.enhanceData.type == \'view\') {\n      tableOption.value.header = false\n      tableOption.value.selection = false\n    }\n\n    useFun.setPropConfig(\'default_address\', {\n      change: ({ row, value, column }) => {\n        if (row.default_address == \'1\') {\n          tableData.value.forEach(ele => {\n            if (ele.id !== row.id) {\n              ele.default_address = \'0\'\n            }\n          })\n        }\n      }\n    })\n\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      data.map(item => {\n        item.$cellEdit = true\n      })\n      resolve(data)\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846086136306475010, '1', 1, '2024-10-15 15:10:08', 101, 1, '2024-11-06 09:59:06', 0, 1846083503466356737, 'js', '\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_8174\', {\n  formId: \'1846092785716961282\', //表单设计id\n  formType: \'add\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1846083503466356737\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'测试表单\', //标题\n    width: \'40%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_94665\', {\n  controlName: \'postForm\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/post/postForm.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'职务详情\', //标题\n    width: \'90%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'保存\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { formView_8174, controlView_94665 } = Vue.toRefs(rendControlData.value)\n// componentRef.value.formView_8174 FormView的Ref控件引用\n\n\nreturn {\n  initOption() { //表格显示前执行\n  console.log(\'6666\',buttonObj.value)\n    let arr = [\'fzBtn\', \'delBtn\', \'editBtn\', \'szqxBtn\', \'szztBtn\', \'userBtn\']\n    arr.map(item => {\n      buttonObj.value.menu[item].params = {\n        plain: true,\n        text: false,\n        size: \"small\"\n      }\n    })\n    tableOption.value.menuWidth = 580\n    tableOption.value.refreshBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.columnBtn = false\n    buttonObj.value.header.addBtn.label = \'新建职务\'\n    buttonObj.value.menu.editBtn.label = \'编辑职务\'\n    useFun.setPropConfig(\'time\', {\n      width: 180,\n    })\n    useFun.setPropConfig(\'zt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.zt\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.zt = 1\n        apiData.cysl = 100\n        apiData.bmms = \'暂无相关描述\'\n        apiData.time = useFun.formatDate(new Date, \'YYYY-MM-DD HH:mm:ss\')\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n  cellStyle({ row, column, rowIndex, columnIndex }) { //列样式\n    if (columnIndex == 3) {\n      return {\n        color: \'#409eff\'\n      }\n    }\n  },\n  szqxBtn(row) {\n    controlView_94665.value.show = true //显示FormView\n    const controlData = controlView_94665.value.params //FormView的配置\n  },\n  userBtn(row) {\n    formView_8174.value.show = true //显示FormView\n    const controlData = formView_8174.value.params //FormView的配置\n    controlData.defaultData.type = \'tjry\'\n    controlData.defaultData.zwmc = row.zwmc\n    controlData.popOption.title = \'添加人员\'\n  },\n  szztBtn(row) {\n    formView_8174.value.show = true //显示FormView\n    const controlData = formView_8174.value.params //FormView的配置\n    controlData.defaultData.type = \'szzt\'\n    controlData.popOption.title = \'设置状态\'\n  },\n  fzBtn(row) {\n    formView_8174.value.show = true //显示FormView\n    const controlData = formView_8174.value.params //FormView的配置\n    controlData.defaultData.type = \'fz\'\n    controlData.popOption.title = \'复制职务\'\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846092931460636674, '1', 1, '2024-10-15 15:37:08', 101, NULL, '2024-11-13 15:08:16', 0, 1844275960258019330, 'scss', '// 表格样式\n.low-table__1844275960258019330 {\n  padding: 13px 10px;\n\n  .avue-crud__tip {\n    display: none;\n  }\n\n  .avue-crud__header {\n    .el-button--primary {\n      background: #ffffff;\n      color: #999;\n      border-color: #e4e4e4;\n\n      &:hover {\n        border-color: #7bbbff;\n        color: #7bbbff;\n        background: #f0f7ff;\n      }\n    }\n  }\n\n\n  .el-form {\n    border-left: 1px solid #E9E9E9;\n    border-right: 1px solid #E9E9E9;\n\n    .el-table__inner-wrapper {\n\n      .el-table__header {\n        height: 55px;\n\n        .el-table__cell {\n          background: #f2f2f2;\n          font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n          font-weight: 700;\n        }\n      }\n\n      .el-table__body-wrapper {\n        .el-table__row {\n          height: 55px;\n\n          .el-table__cell {\n            font-family: \'微软雅黑\', sans-serif;\n            font-weight: 400;\n          }\n\n\n          &.el-table__row--striped {\n\n            .el-table__cell {\n              background: #f2f2f2;\n            }\n          }\n\n        }\n\n      }\n\n      .cell>span {\n        color: #666;\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1844275960258019330 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846095089572651010, NULL, NULL, NULL, NULL, 1, '2024-10-24 14:07:26', 0, 1846095079682482177, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.selection = false\n\n    useFun.setPropConfig(\'points_change\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let color = \'red\'\n        row.points_change.indexOf(\'-\') == \'-1\' ? color = \'#19BE6B\' : color = \'red\'\n        return h(\'span\', { style: { color: color } }, row.points_change)\n      }\n    })\n  },\n}\n\n');
