INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846122054275018754, '1', 1, '2024-10-15 17:32:52', 101, NULL, '2024-11-13 17:58:58', 0, 1846121741006647298, 'scss', '// 表格样式\n.low-table__1846121741006647298 {\n  .avue-crud__body {\n    .avue-crud__header {\n      .avue-crud__left {\n        .el-button {\n          font-size: 14px;\n          color: #999999;\n\n          &.el-button--primary {\n            color: white;\n          }\n        }\n\n\n      }\n\n      .avue-crud__right {\n        .el-button {\n          border: none;\n          color: #999999;\n\n          &.avue-crud__searchBtn {\n            display: none;\n          }\n        }\n      }\n    }\n\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .el-form {\n      border-right: 1px solid #ebeef5;\n\n      .el-table__inner-wrapper {\n\n        .el-table__header {\n          border-top: 1px solid #ebeef5;\n          border-left: 1px solid #ebeef5;\n\n          .el-table__cell {\n            height: 55px;\n\n            .cell {\n              span {\n                color: #666666;\n                font-size: 14px;\n                font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n              }\n            }\n          }\n\n        }\n\n        .el-table__body-wrapper {\n          .el-table__body {\n            border-left: 1px solid #ebeef5;\n\n            .el-table__row {\n              height: 55px;\n\n              .el-table__cell {\n\n                .cell>span {\n                  font-size: 14px;\n                }\n              }\n            }\n\n          }\n\n        }\n      }\n    }\n  }\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1846121741006647298 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846359234339647489, '1', 1, '2024-10-16 09:15:20', 101, NULL, '2024-11-14 09:53:42', 0, 1846121741006647298, 'js', '//初始化控件  新增员工\nuseFun.controlInit(\'FormView\', \'formView_xzyg\', {\n  formId: \'1846388549542457346\', //表单设计id\n  formType: \'add\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: false, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'\', //标题\n    width: \'840px\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n      formView_xzyg.value.show = false\n    }\n    done()\n  }\n})\n\n\n//初始化控件  设置重置修改\nuseFun.controlInit(\'FormView\', \'formView_general\', {\n  formId: \'1846435324265476097\', //表单设计id\n  formType: \'add\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'\', //标题\n    width: \'40%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n    }\n    done()\n  }\n})\n\n\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_staff_view\', {\n  controlName: \'\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/staffManagement/staffView.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'员工详情\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\nconst { formView_xzyg, formView_general, controlView_staff_view } = Vue.toRefs(rendControlData.value)\n\n\nreturn {\n  initOption() { //表格显示前执行\n    buttonObj.value.menu.delBtn.params = {\n      plain: true,\n      text: false,\n      size: \"small\"\n    }\n    buttonObj.value.header.importBtn.label = \'导入数据\'\n    buttonObj.value.header.importBtn.type = \'\'\n    buttonObj.value.header.importBtn.icon = \'material-symbols:download\'\n    useFun.setPropConfig(\'zhzt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.zhzt\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n\n    useFun.setPropConfig(\'zxzt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.zxzt\n        let color = \'#4BD863\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status == \'2\' ? color = \'red\' : \'\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n  },\n  xzygBtn() {\n    //控件调用\n    formView_xzyg.value.show = true //显示FormView\n    const controlData = formView_xzyg.value.params //FormView的配置\n    // componentRef.value.formView_xzyg FormView的Ref控件引用\n    controlData.enhanceData = formView_xzyg.value\n    controlData.popOption.title = \'新增员工\'\n  },\n  xgbmBtn() {\n    formView_general.value.show = true //显示FormView\n    const controlData = formView_general.value.params //FormView的配置\n    controlData.enhanceData.type = \'xgbm\'\n    controlData.popOption.title = \'修改部门\'\n  },\n  xgzwBtn() {\n    formView_general.value.show = true //显示FormView\n    const controlData = formView_general.value.params //FormView的配置\n    controlData.enhanceData.type = \'xgzw\'\n    controlData.popOption.title = \'修改职务\'\n  },\n  szztBtn() {\n    formView_general.value.show = true //显示FormView\n    const controlData = formView_general.value.params //FormView的配置\n    controlData.enhanceData.type = \'szzt\'\n    controlData.popOption.title = \'设置状态\'\n  },\n  czmmBtn() {\n    formView_general.value.show = true //显示FormView\n    const controlData = formView_general.value.params //FormView的配置\n    controlData.enhanceData.type = \'czmm\'\n    controlData.popOption.title = \'重置密码\'\n  },\n  xqBtn(row) {\n    controlView_staff_view.value.show = true //显示ControlView\n    const controlData = controlView_staff_view.value.params //ControlView的配置\n    controlData.controlParams.data = row\n    controlData.controlParams.controlView = controlView_staff_view.value\n\n\n  },\n  bjBtn(row) {\n    formView_xzyg.value.show = true //显示FormView\n    const controlData = formView_xzyg.value.params //FormView的配置\n    controlData.defaultData = row\n    controlData.enhanceData = formView_xzyg.value\n    controlData.popOption.title = \'编辑\'\n  },\n  szBtn() {\n    formView_general.value.show = true //显示FormView\n    const controlData = formView_general.value.params //FormView的配置\n    controlData.enhanceData.type = \'szzt\'\n    controlData.popOption.title = \'设置\'\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846479386355912706, '1', 1, '2024-10-16 17:12:46', 101, NULL, '2024-11-12 14:55:23', 0, 1846009550756601857, 'scss', '// 表格样式\n.low-table__1846009550756601857 {\n  .avue-crud__body {\n    .avue-crud__tip {\n      display: none;\n    }\n\n\n    .el-form {\n      border-left: 1px solid #E9E9E9;\n      border-right: 1px solid #E9E9E9;\n\n      .el-table__inner-wrapper {\n\n\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n            color: #666;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n            &.el-table__row--striped {\n\n              .el-table__cell {\n                font-family: \'微软雅黑\', sans-serif;\n                font-weight: 400;\n                background: #f2f2f2;\n              }\n            }\n\n            .el-table__cell {\n              color: #666;\n            }\n          }\n\n        }\n\n        // .cell>span {\n        //   color: #666;\n        // }\n      }\n    }\n  }\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1846009550756601857 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846482253745704962, '1', 1, '2024-10-16 17:24:10', 101, NULL, '2024-11-12 15:05:45', 0, 1846083503466356737, 'scss', '// 表格样式\n.low-table__1846083503466356737 {\n\n  .avue-crud__body {\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .el-form {\n      border-left: 1px solid #F0F7FF;\n      border-right: 1px solid #F0F7FF;\n\n      .el-table__inner-wrapper {\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n            color: #666;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n            &.el-table__row--striped {\n\n              .el-table__cell {\n                font-family: \'微软雅黑\', sans-serif;\n                font-weight: 400;\n                background: #f2f2f2;\n              }\n            }\n\n            .el-table__cell {\n              color: #666;\n            }\n\n          }\n\n        }\n\n        // .cell>span {\n        //   color: #666;\n        // }\n      }\n    }\n  }\n\n\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1846083503466356737 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846483087401373698, '1', 1, '2024-10-16 17:27:29', 101, 1, '2024-11-11 15:56:47', 0, 1844620967619866625, 'scss', '// 表格样式\n.low-table__1844620967619866625 {\n\n  .avue-crud__body {\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .el-form {\n      border: 1px solid #f2f2f2;\n\n      .el-table__inner-wrapper {\n        &::before {\n          height: 0;\n        }\n\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n              .el-table__cell {\n                font-family: \'微软雅黑\', sans-serif;\n              }\n\n            &.el-table__row--striped {\n\n              .el-table__cell {\n                font-family: \'微软雅黑\', sans-serif;\n                font-weight: 400;\n                background: #f2f2f2;\n              }\n            }\n\n          }\n\n        }\n\n        .cell>span {\n          color: #666;\n        }\n      }\n    }\n\n  }\n\n\n\n\n\n\n  .header-button {\n    .el-button--small {\n      padding: 15px 15px;\n      color: #999;\n      font-family: 微软雅黑, sans-serif;\n      font-weight: 400;\n      font-size: 14px;\n    }\n\n    .el-button--small:hover {\n      color: #409eff;\n    }\n  }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1844620967619866625 {}');
