INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846734672610152450, NULL, NULL, NULL, NULL, NULL, '2024-11-14 11:54:29', 0, 1846734665412726786, 'scss', '// 表格样式\n.low-table__1846734665412726786 {\n  padding: 12px 10px;\n\n  .el-form {\n    border: 1px solid #E9E9E9;\n\n    .el-table__inner-wrapper {\n      .el-table__header {\n        .el-table__cell {\n          height: 50px;\n\n          .cell {\n            span {\n              color: #666666;\n              font-size: 14px;\n              font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            }\n          }\n        }\n\n      }\n\n      .el-table__body-wrapper {\n        .el-table__cell {\n          span {\n            font-size: 14px;\n          }\n        }\n      }\n    }\n  }\n\n  .avue-crud__header {\n    .el-button--primary {\n      background: #ffffff;\n      color: #999;\n      border-color: #e4e4e4;\n\n      &:hover {\n        border-color: #7bbbff;\n        color: #7bbbff;\n        background: #f0f7ff;\n      }\n    }\n  }\n\n  .el-table__inner-wrapper {\n    // border: 1px solid #E9E9E9;\n\n    .el-table__header {\n      height: 55px;\n\n      .el-table__cell {\n        background: #f2f2f2;\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n      }\n    }\n\n    .el-table__body-wrapper {\n      .el-table__row {\n        height: 55px;\n\n        .el-table__cell {\n          font-family: \'微软雅黑\', sans-serif;\n          font-weight: 400;\n        }\n\n\n        &.el-table__row--striped {\n\n          .el-table__cell {\n            background: #f2f2f2;\n          }\n        }\n\n      }\n\n    }\n\n    .cell>span {\n      color: #666;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1846100518918823938 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846734672610152451, NULL, NULL, NULL, NULL, 1, '2024-10-17 10:52:18', 0, 1846734665412726786, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.selection = false\n    if (props.enhanceData?.type && props.enhanceData?.type == \'view\') {\n      tableOption.value.header = false\n      tableOption.value.menu = false\n    }\n  },\n}\n');
