INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846747373516292098, NULL, NULL, NULL, NULL, NULL, '2024-11-14 11:54:54', 0, 1846747363458351106, 'scss', '// 表格样式\n.low-table__1846747363458351106 {\n  padding: 12px 10px;\n\n  .el-form {\n    border: 1px solid #E9E9E9;\n\n    .el-table__inner-wrapper {\n      .el-table__header {\n        .el-table__cell {\n          height: 50px;\n\n          .cell {\n            span {\n              color: #666666;\n              font-size: 14px;\n              font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            }\n          }\n        }\n\n      }\n\n      .el-table__body-wrapper {\n        .el-table__cell {\n          span {\n            font-size: 14px;\n          }\n        }\n      }\n    }\n  }\n\n  .avue-crud__header {\n    .el-button--primary {\n      background: #ffffff;\n      color: #999;\n      border-color: #e4e4e4;\n\n      &:hover {\n        border-color: #7bbbff;\n        color: #7bbbff;\n        background: #f0f7ff;\n      }\n    }\n  }\n\n  .el-table__inner-wrapper {\n    // border: 1px solid #E9E9E9;\n\n    .el-table__header {\n      height: 55px;\n\n      .el-table__cell {\n        background: #f2f2f2;\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n      }\n    }\n\n    .el-table__body-wrapper {\n      .el-table__row {\n        height: 55px;\n\n        .el-table__cell {\n          font-family: \'微软雅黑\', sans-serif;\n          font-weight: 400;\n        }\n\n\n        &.el-table__row--striped {\n\n          .el-table__cell {\n            background: #f2f2f2;\n          }\n        }\n\n      }\n\n    }\n\n    .cell>span {\n      color: #666;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1846100518918823938 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1846747373516292099, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1846747363458351106, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.selection = false\n    if (props.enhanceData?.type && props.enhanceData?.type == \'view\') {\n      tableOption.value.header = false\n      tableOption.value.menu = false\n    }\n  },\n}\n');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1847096134377639938, '1', 1, '2024-10-18 10:03:30', 101, NULL, '2024-11-15 15:49:23', 0, 1847094468974710786, 'js', '\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_71572\', {\n  controlName: \'projectForm\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/project/projectForm.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'项目详情\', //标题\n    width: \'90%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { controlView_71572 } = Vue.toRefs(rendControlData.value)\n\n// componentRef.value.controlView_71572 ControlView的Ref控件引用\n\n\nreturn {\n  summaryTopFormatting(data) { //表格头部统计格式化\n    console.log(\'======增强====\', data)\n    return data\n  },\n  initOption() {\n    let arr = [\'xqBtn\', \'delBtn\', \'editBtn\']\n    arr.map(item => {\n      buttonObj.value.menu[item].params = {\n        plain: true,\n        text: false,\n        size: \"small\"\n      }\n    })\n\n    buttonObj.value.header.addBtn.label = \'创建项目\'\n    useFun.setPropConfig(\'zt\', {\n      render: ({ row }) => {\n        let text = row.zt == 1 ? \'正常\' : \'异常\'\n        return h(\'div\', { style: { width: \'50px\', height: \'20px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', color: \'#fff\', background: \'#51d351\', borderRadius: \'5px\', fontFamily: \'MicrosoftYaHei, 微软雅黑, sans-serif\', fontSize: \'12px\' } }, text)\n      }\n    })\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      tableOption.value.menuWidth = 250\n      tableOption.value.refreshBtn = false\n      tableOption.value.columnBtn = false\n      tableOption.value.headerAlign = \'left\'\n      tableOption.value.menuHeaderAlign = \'left\'\n      tableOption.value.align = \'center\'\n\n      useFun.setPropConfig(\'zhgx\', {\n        // width: 180\n      })\n      useFun.setPropConfig(\'xmcy\', {\n        // width: 150\n      })\n      const arr = [\'jbxx\', \'zt\', \'xmjd\']\n      arr.forEach(key => {\n        useFun.setPropConfig(key, {\n          html: true,\n          // width: key == \'jbxx\' ? 350 : key == \'zt\' ? 100 : key == \'xmjd\' ? 300 : \'\',\n        })\n      })\n      if (data) {\n        data.map(item => {\n          item.jbxx = `\n            <div style=\"display:flex;\">\n              <div style=\"display: flex;\n                margin-right:20px;\n                width: 60px;\n                height: 60px;\n                line-height: 50px;\n                justify-content: center;\n                text-align: center;\n                background: #52c1f5;\n                border-radius: 50%;\n                align-items: center;\">\n                // <img src=\"../../../../../public/img/xmgl.jpg\" style=\"width: 28px;height: 28px\" />\n                <img src=\"/img/xmgl.jpg\" style=\"width: 28px;height: 28px\" />\n              </div>\n              <div style=\"\">\n                <p style=\"padding:0;margin:0;text-align:left;margin-top:5px;font-size:18px;color:#666;\n                font-family: \'微软雅黑 Bold\', \'微软雅黑\', sans-serif !important;font-weight: 700 !important;\n                \">${item.title || \'\'}</p>\n                <p style=\"padding:0;margin:0;color:#999999;\">${item.content || \'\'}</p>\n              </div>\n            </div>\n            `\n          // item.zt = `<b style=\"\n          //   color:#fff;\n          //   background: #51d351;\n          //   padding:2px 10px;\n          //   border-radius:5px;\n          //   font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n          //   font-size:12px\"\n          //   >${item.zt == 1 ? \'正常\' : \'异常\'}</b>`\n          item.xmjd = item.xmjd ? `\n          <div style=\"display:flex;align-items: center;\">\n            <div style=\"width:250px;height:8px;background: #e9e9e9;border-radius: 10px;padding:0;\">\n              <div style=\"width:${item.xmjd}%;height:8px;background: #409eff;border-radius: 10px;\"></div>\n            </div>\n            <p style=\"padding:0;margin:0;margin-left:10px;font-size:10px;font-family: \'ArialMT\', \'Arial\', sans-serif;\">${item.xmjd}%</p>\n          </div>\n          `: \'\'\n          return item\n        })\n      }\n\n      resolve(data)\n    })\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.zt = 1\n        apiData.xmjd = 50\n        apiData.zhgx = useFun.formatDate(new Date, \'YYYY-MM-DD HH:mm:ss\')\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n  xqBtn(row) {\n    controlView_71572.value.show = true //显示ControlView\n    const controlData = controlView_71572.value.params //ControlView的配置\n    controlData.controlParams = { data: row }\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1847109679396827138, '1', 1, '2024-10-18 10:57:20', 101, 1, '2024-10-29 09:46:12', 0, 1847103675560071169, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'rwxq\', {\n  formId: \'1850013430948507650\', //表单设计id\n  formType: \'edit\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: false, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'详情\', //标题\n    width: \'60%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\nlet clickIdList = []\n\nreturn {\n  initOption() { //表格显示前执行\n\n    if (props.enhanceData && props.enhanceData.type && props.enhanceData.type == \'view\') {\n      tableOption.value.menu = false\n      tableOption.value.header = false\n\n    }\n\n    useFun.setPropConfig(\'title\', {\n      render: (data) => {\n        return h(\'div\', { style: { fontFamily: \'MicrosoftYaHei, 微软雅黑, sans-serif\', fontSize: \'14px\', color: \'#666666\', } }, `${data.row.title},点击查看详情`)\n      }\n    })\n\n\n    useFun.setPropConfig(\'jzsj\', {\n      render: ({ row }) => {\n        if (Icon) {\n          let jssjTitle = \'\'\n          if (row.jzsj) {\n            jssjTitle = useFun.formatPast(row.jzsj, \'YYYY-MM-DD\') + \' 截止\'\n          } else {\n            jssjTitle = \' 截止\'\n          }\n\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'11px\' },\n          }, [\n            h(Icon, { icon: \'icon-park-outline:alarm-clock\', size: 14, color: \'#CCCCCC\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, jssjTitle),\n          ])\n        }\n        return \'\'\n      }\n    })\n    useFun.setPropConfig(\'status\', {\n      render: (optins) => {\n        let { row, column } = optins    //row是当行数据  column是字典数据\n        let statusTitle = \'\'\n        let status = row.status\n        let bgColorList = [\'#409EFF\', \'#19BE6B\', \'#F56C6C\']\n        if (status && column.dicData[status - 1]) {\n          statusTitle = column.dicData[status - 1].label\n          let bgColor = bgColorList[status - 1]\n          const radius = h(\'div\', { style: { width: \'5px\', height: \'5px\', borderRadius: \'50%\', backgroundColor: bgColor, marginRight: \'5px\' } }, \'\')\n          return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\', fontSize: \'11px\' } }, [radius, statusTitle])\n        }\n        return \'\'\n\n      }\n    })\n\n\n\n    useFun.setPropConfig(\'urgent_relief\', {\n      render: (optins) => {\n        let { row, column } = optins    //row是当行数据  column是字典数据\n        let statusTitle = \'\'\n        let urgent_relief = row.urgent_relief\n        if (urgent_relief && column.dicData[urgent_relief - 1]) {\n          statusTitle = column.dicData[urgent_relief - 1].label\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n          }, [\n            h(Icon, { icon: \'subway:mark-2\', size: 14, color: \'#CCCCCC\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, statusTitle),\n          ])\n        }\n        return \'\'\n      }\n    })\n\n    useFun.setPropConfig(\'xmmc\', {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n          }, [\n            h(Icon, { icon: \'mage:box-3d\', size: 14, color: \'#CCCCCC\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, row.xmmc),\n          ])\n        }\n        return \'\'\n      }\n    })\n\n    useFun.setPropConfig(\'fj\', {\n      render: ({ row }) => {\n        let num = 0\n        if (row.fj) {\n          if (row.fj.indexOf(\',\') == -1) {\n            num = 1\n          } else {\n            num = row.fj.split(\',\').length\n          }\n        }\n        return h(\'div\', {\n          style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n        }, [\n          h(Icon, { icon: \'line-md:link\', size: 14, color: \'#CCCCCC\' }),\n          h(\'span\', { style: { marginLeft: \'2px\' } }, num)\n        ])\n      }\n    })\n\n    useFun.setPropConfig(\'lys\', {\n      render: ({ row }) => {\n        let num = 0\n        row.lys ? num = row.lys : num = 0\n\n        return h(\'div\', {\n          style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n        }, [\n          h(Icon, { icon: \'mage:message\', size: 14, color: \'#CCCCCC\' }),\n          h(\'span\', { style: { marginLeft: \'2px\' } }, num)\n        ])\n      }\n    })\n\n  },\n\n  cellClick(row, column, cell, event) { //单元格单击\n    if (column.type == \'selection\') {\n      let index = clickIdList.indexOf(row.id);\n      if (index === -1) {\n        clickIdList.push(row.id);\n      } else {\n        clickIdList.splice(index, 1);\n      }\n\n      if (clickIdList) {\n        useFun.setPropConfig(\'title\', {\n          render: (data) => {\n            if (clickIdList.indexOf(data.row.id) !== -1) {\n              return h(\'div\', { style: { textDecoration: \'line-through\', fontFamily: \'MicrosoftYaHei, 微软雅黑, sans-serif\', fontSize: \'14px\', color: \'#666666\', } }, `${data.row.title},点击查看详情`)\n            } else {\n              return h(\'div\', { style: { fontFamily: \'MicrosoftYaHei, 微软雅黑, sans-serif\', fontSize: \'14px\', color: \'#666666\', } }, `${data.row.title},点击查看详情`)\n            }\n          }\n        })\n      }\n    }\n\n\n    if (column.prop == \'title\') {\n      const { rwxq } = Vue.toRefs(rendControlData.value)\n      rwxq.value.show = true //显示FormView\n      const controlData = rwxq.value.params //FormView的配置\n      // componentRef.value.rwxq FormView的Ref控件引用\n      controlData.enhanceData.icon = Icon\n      controlData.defaultData = row\n\n    }\n  },\n  cellStyle({ row, column, rowIndex, columnIndex }) { //列样式\n    if (column.prop == \'color\') {\n      let bgColor = row[column.prop]\n      return { background: bgColor }\n    }\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1847169474640420866, '1', 1, '2024-10-18 14:54:56', 101, 1, '2024-10-29 17:38:47', 0, 1847103675560071169, 'scss', '// 表格样式\n.low-table__1847103675560071169 {\n\n  .avue-crud__tip {\n    display: none;\n  }\n\n  .el-form {\n    .el-checkbox-group>.el-row {\n      .avue-crud__grid__content {\n        position: relative;\n        height: 69px;\n        padding: 0;\n\n        .selection {\n          position: absolute;\n          top: 50%;\n          left: 20px;\n          transform: translateY(-50%);\n        }\n\n        .index {\n          display: none;\n        }\n\n        .avue-crud__grid__item {\n          .avue-crud__grid__label {\n            display: none;\n          }\n\n          .control-input {\n            font-size: 12px;\n          }\n        }\n\n        .title,\n        .status,\n        .jzsj,\n        .urgent_relief,\n        .xmmc,\n        .lys,\n        .fj {\n          span {\n            font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n            font-size: 12px !important;\n            color: #666666;\n            font-weight: 400;\n          }\n        }\n\n        .title {\n          width: 225px;\n          position: absolute;\n          top: 50%;\n          left: 50px;\n          transform: translateY(-50%);\n          cursor: pointer;\n\n          span {\n            font-size: 14px !important;\n          }\n        }\n\n        .status {\n          width: 115px;\n          position: absolute;\n          top: 50%;\n          left: 40%;\n          transform: translateY(-50%);\n\n\n        }\n\n        .jzsj {\n          width: 170px;\n          position: absolute;\n          top: 50%;\n          left: 48%;\n          transform: translateY(-50%);\n        }\n\n        .urgent_relief {\n          width: 115px;\n          position: absolute;\n          top: 50%;\n          left: 62%;\n          transform: translateY(-50%);\n        }\n\n        .xmmc {\n          width: 115px;\n          position: absolute;\n          top: 50%;\n          left: 70%;\n          transform: translateY(-50%);\n        }\n\n        .lys {\n          width: 40px;\n          position: absolute;\n          top: 50%;\n          left: 81%;\n          transform: translateY(-50%);\n\n          span {\n            color: #999999;\n          }\n        }\n\n        .fj {\n          width: 55px;\n          position: absolute;\n          top: 50%;\n          left: 85%;\n          transform: translateY(-50%);\n\n          span {\n            color: #999999;\n          }\n        }\n\n        .tx {\n          width: 40px;\n          position: absolute;\n          top: 50%;\n          left: 93%;\n          transform: translateY(-50%);\n\n          .avue-crud__img {\n            width: 35px;\n            height: 35px;\n\n            img {\n              width: 100%;\n              height: 100%;\n              border-radius: 50%;\n            }\n          }\n        }\n\n        .color {\n          width: 5px;\n          height: 100%;\n          position: absolute;\n          top: 50%;\n          transform: translateY(-50%);\n          left: 0;\n\n          .avue-crud__grid__label {\n            display: none;\n          }\n        }\n\n        &::before {\n          height: 0;\n        }\n      }\n\n\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1847103675560071169 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1847170514759585793, '1', 1, '2024-10-18 14:59:04', 101, NULL, '2024-11-15 15:45:06', 0, 1847094468974710786, 'scss', '// 表格样式\n.low-table__1847094468974710786 {\n  .avue-crud__header {\n    justify-content: end;\n\n  }\n\n  .el-table__inner-wrapper {\n    .el-table__header {\n      height: 55px;\n\n      .el-table__cell {\n        background: white;\n        // background: #f2f2f2;\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n      }\n    }\n\n    .el-table__body-wrapper {\n      .el-table__row {\n        height: 100px;\n\n\n        .control-image {\n          .cell {\n            // padding: 0;\n\n            .avue-crud__img {\n              margin-left: -17px;\n            }\n          }\n        }\n\n        &.el-table__row--striped {\n\n          .el-table__cell {\n            font-family: \'微软雅黑\', sans-serif;\n            font-weight: 400;\n            background: #f2f2f2;\n          }\n        }\n\n      }\n\n    }\n\n    .cell>span {\n      color: #666;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1847094468974710786 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1847472453682593793, NULL, NULL, NULL, NULL, 1, '2024-10-26 17:35:01', 0, 1847472439438737409, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    if (props.enhanceData && props.enhanceData.type && props.enhanceData.type == \'view\') {\n      tableOption.value.menu = false\n      tableOption.value.header = false\n\n    }\n    useFun.setPropConfig(\'title\', {\n      html: true,\n      formatter: (val) => {\n        // return `<span>${val.title},点击查看详情</span>`;\n        return val.title;\n      },\n    })\n\n    useFun.setPropConfig(\'jzsj\', {\n      render: ({ row }) => {\n        if (Icon) {\n          let jssjTitle = \'\'\n          if (row.jzsj) {\n            jssjTitle = useFun.formatDate(row.jzsj, \'YYYY年MM月DD日\') + \' 截止\'\n          } else {\n            jssjTitle = \' 截止\'\n          }\n\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'11px\' },\n          }, [\n            h(Icon, { icon: \'icon-park-outline:alarm-clock\', size: 14, color: \'#CCCCCC\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, jssjTitle),\n          ])\n        }\n        return \'\'\n      }\n    })\n    useFun.setPropConfig(\'status\', {\n      render: (optins) => {\n        let { row, column } = optins    //row是当行数据  column是字典数据\n        let statusTitle = \'\'\n        let status = row.status\n        let bgColorList = [\'#409EFF\', \'#19BE6B\', \'#F56C6C\']\n        if (status && column.dicData[status - 1]) {\n          statusTitle = column.dicData[status - 1].label\n          let bgColor = bgColorList[status - 1]\n          const radius = h(\'div\', { style: { width: \'5px\', height: \'5px\', borderRadius: \'50%\', backgroundColor: bgColor, marginRight: \'5px\' } }, \'\')\n          return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\', fontSize: \'11px\' } }, [radius, statusTitle])\n        }\n        return \'\'\n\n      }\n    })\n\n\n\n    useFun.setPropConfig(\'urgent_relief\', {\n      render: (optins) => {\n        let { row, column } = optins    //row是当行数据  column是字典数据\n        let statusTitle = \'\'\n        let urgent_relief = row.urgent_relief\n        if (urgent_relief && column.dicData[urgent_relief - 1]) {\n          statusTitle = column.dicData[urgent_relief - 1].label\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n          }, [\n            h(Icon, { icon: \'subway:mark-2\', size: 14, color: \'#CCCCCC\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, statusTitle),\n          ])\n        }\n        return \'\'\n      }\n    })\n\n    useFun.setPropConfig(\'xmmc\', {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n          }, [\n            h(Icon, { icon: \'mage:box-3d\', size: 14, color: \'#CCCCCC\' }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, row.xmmc),\n          ])\n        }\n        return \'\'\n      }\n    })\n\n    useFun.setPropConfig(\'fj\', {\n      render: ({ row }) => {\n        let num = 0\n        if (row.fj) {\n          if (row.fj.indexOf(\',\') == -1) {\n            num = 1\n          } else {\n            num = row.fj.split(\',\').length\n          }\n        }\n        return h(\'div\', {\n          style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n        }, [\n          h(Icon, { icon: \'line-md:link\', size: 14, color: \'#CCCCCC\' }),\n          h(\'span\', { style: { marginLeft: \'2px\' } }, num)\n        ])\n      }\n    })\n\n    useFun.setPropConfig(\'lys\', {\n      render: ({ row }) => {\n        let num = 0\n        row.lys ? num = row.lys : num = 0\n\n        return h(\'div\', {\n          style: { display: \'flex\', alignItems: \'center\', fontSize: \'12px\' },\n        }, [\n          h(Icon, { icon: \'mage:message\', size: 14, color: \'#CCCCCC\' }),\n          h(\'span\', { style: { marginLeft: \'2px\' } }, num)\n        ])\n      }\n    })\n\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n\n      if (data) {\n        data.map(item => {\n          item.zw = `<div style=\"background:#409eff !important;height:82px;width:3px;\">6666</div>`\n          return item\n        })\n      }\n      resolve(data)\n    })\n  },\n\n  cellStyle({ row, column, rowIndex, columnIndex }) { //列样式\n    if (column.prop == \'color\') {\n      let bgColor = row[column.prop]\n      return { background: bgColor }\n    }\n\n  },\n\n  cellClick(row, column, cell, event) { //单元格单击row, , cell, event,\n    let arr = []\n    setTimeout(() => {\n      tableSelect.value.map(key => {\n        arr.push(key.id)\n      })\n      tableData.value.map(item => {\n          if(arr.join().includes(item.id)){\n            item.title = `<span style=\"text-decoration: line-through;\">${item.title_copy}</span>`\n          } else {\n            item.title = `<span style=\"text-decoration: none;\">${item.title_copy}</span>`\n          }\n      })\n    }, 600)\n\n  },\n\n\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1847472453690982402, NULL, NULL, NULL, NULL, NULL, '2024-11-15 17:24:10', 0, 1847472439438737409, 'scss', '// 表格样式\n.low-table__1847472439438737409 {\n  padding: 5px 8px;\n    \n  .avue-crud__tip {\n    display: none;\n  }\n\n  .el-form {\n    .el-checkbox-group>.el-row {\n      .avue-crud__grid__content {\n        position: relative;\n        height: 69px;\n        padding: 0;\n\n        .selection {\n          position: absolute;\n          top: 50%;\n          left: 20px;\n          transform: translateY(-50%);\n        }\n\n        .index {\n          display: none;\n        }\n\n        .avue-crud__grid__item {\n          .avue-crud__grid__label {\n            display: none;\n          }\n\n          .control-input {\n            font-size: 12px;\n          }\n        }\n\n        .title,\n        .status,\n        .jzsj,\n        .urgent_relief,\n        .xmmc,\n        .lys,\n        .fj {\n          span {\n            font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n            font-size: 12px !important;\n            color: #666666;\n            font-weight: 400;\n          }\n        }\n\n        .title {\n          width: 225px;\n          position: absolute;\n          top: 50%;\n          left: 50px;\n          transform: translateY(-50%);\n\n          span {\n            font-size: 14px !important;\n          }\n        }\n\n        .status {\n          width: 115px;\n          position: absolute;\n          top: 50%;\n          left: 40%;\n          transform: translateY(-50%);\n\n\n        }\n\n        .jzsj {\n          width: 170px;\n          position: absolute;\n          top: 50%;\n          left: 48%;\n          transform: translateY(-50%);\n        }\n\n        .urgent_relief {\n          width: 115px;\n          position: absolute;\n          top: 50%;\n          left: 62%;\n          transform: translateY(-50%);\n        }\n\n        .xmmc {\n          width: 115px;\n          position: absolute;\n          top: 50%;\n          left: 70%;\n          transform: translateY(-50%);\n        }\n\n        .lys {\n          width: 40px;\n          position: absolute;\n          top: 50%;\n          left: 81%;\n          transform: translateY(-50%);\n\n          span {\n            color: #999999;\n          }\n        }\n\n        .fj {\n          width: 55px;\n          position: absolute;\n          top: 50%;\n          left: 85%;\n          transform: translateY(-50%);\n\n          span {\n            color: #999999;\n          }\n        }\n\n        .tx {\n          width: 40px;\n          position: absolute;\n          top: 50%;\n          left: 93%;\n          transform: translateY(-50%);\n\n          .avue-crud__img {\n            width: 35px;\n            height: 35px;\n\n            img {\n              width: 100%;\n              height: 100%;\n              border-radius: 50%;\n            }\n          }\n        }\n\n        .color {\n          width: 5px;\n          height: 100%;\n          position: absolute;\n          top: 50%;\n          transform: translateY(-50%);\n          left: 0;\n\n          .avue-crud__grid__label {\n            display: none;\n          }\n        }\n\n        &::before {\n          height: 0;\n        }\n      }\n    }\n  }\n\n  .text>span {\n    text-decoration: none !important;\n  }\n\n  .texts>span {\n    text-decoration: line-through;\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1847472439438737409 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848607411398680578, '1', 1, '2024-10-22 14:08:47', 101, NULL, '2024-11-15 17:39:37', 0, 1848301752228683777, 'scss', '// 表格样式\n.low-table__1848301752228683777 {\n  padding: 5px 8px;\n\n  .avue-crud__body {\n    .el-form {\n      border-left: 1px solid #E9E9E9;\n      border-right: 1px solid #E9E9E9;\n\n      .el-table__inner-wrapper {\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n            .el-table__cell {\n              font-family: \'微软雅黑\', sans-serif;\n              font-weight: 400;\n            }\n\n            // &.el-table__row--striped {\n\n            //   .el-table__cell {\n            //     font-family: \'微软雅黑\', sans-serif;\n            //     font-weight: 400;\n            //     background: #f2f2f2;\n            //   }\n            // }\n\n            .justify-center {\n              gap: 5px;\n\n              // .el-button--primary {\n              //   height: 25px;\n              //   border: 1px solid;\n              //   padding: 0px 8px;\n              //   font-size: 12px;\n              //   font-family: 微软雅黑, sans-serif;\n              //   font-weight: 400;\n              //   line-height: 25px;\n              //   border-radius: 5px;\n              //   background: #f0f7ff;\n\n              //   &:hover {\n              //     color: #fff;\n              //     background: #409eff;\n              //   }\n              // }\n\n              // .el-button--warning {\n              //   height: 25px;\n              //   border: 1px solid;\n              //   padding: 0px 8px;\n              //   font-size: 12px;\n              //   font-family: 微软雅黑, sans-serif;\n              //   font-weight: 400;\n              //   line-height: 25px;\n              //   border-radius: 5px;\n              //   background: #fff7eb;\n\n              //   &:hover {\n              //     color: #fff;\n              //     background: #ff9900;\n              //   }\n              // }\n\n              // .el-button--danger {\n              //   height: 25px;\n              //   border: 1px solid;\n              //   padding: 0px 8px;\n              //   font-size: 12px;\n              //   font-family: 微软雅黑, sans-serif;\n              //   font-weight: 400;\n              //   line-height: 25px;\n              //   border-radius: 5px;\n              //   background: #fef3f3;\n\n              //   &:hover {\n              //     color: #fff;\n              //     background: #f56c6c;\n              //   }\n              // }\n            }\n\n          }\n\n        }\n\n        .cell>span {\n          color: #666;\n        }\n      }\n    }\n  }\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1848301752228683777 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848631609567387649, NULL, NULL, NULL, NULL, 1, '2024-10-22 15:56:18', 0, 1848631600935510017, 'scss', '// 表格样式\n.low-table__1848631600935510017 {\n  .avue-crud__grid__content {\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n      font-family: \'微软雅黑\';\n\n      &.crad_img {\n        position: absolute;\n        left: 16px;\n        top: 16px;\n        width: calc(100% - 16px);\n\n        img {\n          width: 60px;\n          height: 60px;\n        }\n      }\n\n      &.crad_title,\n      &.card_describe {\n        padding-left: 80px;\n      }\n\n      &.crad_title {\n        .avue-crud__grid__value {\n          font-size: 16px;\n          font-weight: bold;\n          color: #666;\n        }\n      }\n\n      &.card_describe {\n        margin-top: 5px;\n        color: #999;\n\n        .avue-crud__grid__value {\n          display: -webkit-box;\n          -webkit-box-orient: vertical;\n          -webkit-line-clamp: 3;\n          overflow: hidden;\n          text-overflow: ellipsis;\n          white-space: normal;\n        }\n      }\n    }\n  }\n\n  .avue-crud__grid .avue-crud__grid__content::before {\n    background: none;\n  }\n  .avue-crud__grid .avue-crud__grid__content{\n    padding: 16px;\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1848631600935510017 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848637153338368002, NULL, NULL, NULL, NULL, 1, '2024-11-04 11:31:38', 0, 1848637143087489025, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\nreturn {\n  initOption() { //表格显示前执行\n    buttonObj.value.menu.viewBtn.icon = \'icon-park-solid:right-c\'\n\n    //点赞等图标的点击事件\n    // const clickFun = (row, type) => {\n    //   tableData.value[row.$index][type] = (row[type] || 0) + 1\n    // }\n\n    // tableOption.value.column.num_list = {\n    //   label: \'\',\n    //   render: ({ row }) => {\n    //     if (Icon) {\n    //       const opData = [\n    //         { key: \'dz_num\', icon: \'uiw:like-o\' },\n    //         { key: \'sc_num\', icon: \'solar:star-outline\' },\n    //         { key: \'pl_num\', icon: \'fluent:comment-16-regular\' },\n    //       ]\n    //       const hList = opData.map(item => {\n    //         return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', cursor: \'pointer\' }, onClick: () => clickFun(row, item.key) },\n    //           [\n    //             h(Icon, { icon: item.icon, size: 12 }),\n    //             h(\'span\', { style: { marginLeft: \'2px\' } }, row[item.key] || 0),\n    //           ])\n    //       })\n\n    //       return h(\'div\', {\n    //         style: { display: \'flex\', alignItems: \'center\', columnGap: \'15px\', fontSize: \'12px\', color: \'#999\' },\n    //       }, hList)\n    //     }\n    //     return \'\'\n    //   }\n    // }\n    tableOption.value.column.time_test = {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\' },\n          }, [\n            h(Icon, { icon: \'mingcute:time-line\', size: 14 }),\n            h(\'span\', { style: { marginLeft: \'2px\' } }, useFun.formatPast(row.create_time, \'YYYY-MM-DD\')),\n          ])\n        }\n        return \'\'\n      }\n    }\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848637153338368003, NULL, NULL, NULL, NULL, 1, '2024-10-23 10:17:26', 0, 1848637143087489025, 'scss', '// 表格样式\n.low-table__1848637143087489025 {\n  .avue-crud__grid__content {\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n\n      &.zt_img {\n        width: 100%;\n        aspect-ratio: 1 / 0.56; //保持元素纵横比\n      }\n\n      .low-field__zt_img {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 100%;\n\n        .avue-crud__img {\n          width: 100%;\n\n          img {\n            width: 100%;\n            height: 56%;\n            margin-right: 0 !important;\n            object-fit: cover\n          }\n        }\n      }\n\n      &.zt_title {\n        margin-top: 10px;\n        font-size: 14px;\n        color: #333;\n      }\n\n      &.zt_type {\n        font-size: 14px;\n        color: #999;\n      }\n\n      &.time_test {\n        position: absolute;\n        left: 16px;\n        bottom: 5px;\n        width: 94px;\n      }\n\n      &.menu {\n        margin-top: 4px;\n      }\n    }\n  }\n\n  .avue-crud__grid__value {\n    white-space: normal;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content::before {\n    background: none;\n  }\n\n  // .el-button:last-child {\n  //   // position: absolute;\n  //   // right: 20px;\n  //   // border: none;\n\n  //   >span {\n  //     flex-direction: row-reverse;\n  //   }\n  // }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1848637143087489025 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848649279071232001, NULL, NULL, NULL, NULL, 1, '2024-10-23 14:36:04', 0, 1848649270435160066, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\nreturn {\n  initOption() { //表格显示前执行\n\n    buttonObj.value.menu.viewBtn.label = \'查看详情\'\n    buttonObj.value.menu.viewBtn.icon = \'formkit:right\'\n\n    tableOption.value.column.content = {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { width: \'100%\', display: \'flex\', justifyContent: \'space-between\', marginTop: \'10px\' },\n          }, [\n            h(\'div\', {\n              style: { width: \'80%\', fontFamily: `\'MicrosoftYaHei\', \'微软雅黑\', sans-serif`, color: \'#999999 !important\', fontSize: \'14px\', textAlign: \'left\', },\n            }, row.content),\n            h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\', marginTop: \'-26px\' },\n            }, [\n              h(Icon, { icon: \'mingcute:time-line\', size: 14 }),\n              h(\'span\', { style: { marginLeft: \'2px\' } }, row.time),\n            ])\n          ])\n        }\n        return \'\'\n      }\n    }\n\n\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.time = useFun.formatDate(new Date, \'YYYY-MM-DD HH:mm\')\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848649279075426306, NULL, NULL, NULL, NULL, 1, '2024-10-23 10:16:11', 0, 1848649270435160066, 'scss', '// 表格样式\n.low-table__1848649270435160066 {\n  .avue-crud__grid__content {\n    width: 400%;\n\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n\n      &.zt_img {\n        width: 100%;\n        aspect-ratio: 1 / 0.56; //保持元素纵横比\n      }\n\n      .low-field__zt_img {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 100%;\n\n        .avue-crud__img {\n          width: 100%;\n\n          img {\n            width: 100%;\n            height: 56%;\n            margin-right: 0 !important;\n            object-fit: cover\n          }\n        }\n      }\n\n      &.zt_title {\n        margin-top: 10px;\n        font-size: 14px;\n        color: #333;\n      }\n\n      &.zt_type {\n        font-size: 14px;\n        color: #999;\n      }\n\n      &.time_test {\n        position: absolute;\n        left: 16px;\n        bottom: 5px;\n        width: 94px;\n      }\n\n      &.menu {\n        margin-top: 4px;\n      }\n    }\n  }\n\n  .avue-crud__grid__value {\n    white-space: normal;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content {\n    padding: 16px;\n    border: none;\n    border-bottom: 1px solid #f2f2f2;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content::before {\n    background: none;\n  }\n\n  .el-row {\n    display: flex;\n    flex-direction: column;\n  }\n\n  .avue-crud__grid .title .avue-crud__grid__value {\n    font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n    font-weight: 700;\n    font-style: normal;\n    font-size: 16px;\n    text-align: left;\n    color: #666666;\n  }\n\n\n  .avue-crud__grid .menu {\n    justify-content: start;\n\n    .el-button {\n      border: 1px solid #e4e4e4;\n    }\n\n    .el-button:last-child {\n      position: absolute;\n      right: 20px;\n      border: none;\n\n      >span {\n        flex-direction: row-reverse;\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1848649270435160066 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848934692071579649, '1', 1, '2024-10-23 11:49:17', 101, 1, '2024-10-23 14:28:57', 0, 1840646327436394498, 'scss', '// 表格样式\n.low-table__1840646327436394498 {\n  .el-card__body {\n\n    .avue-crud__tip,\n    .avue-crud__header .avue-crud__right .avue-crud__searchBtn {\n      display: none;\n    }\n\n    .el-form {\n      .el-table__header {\n        .el-table__cell {\n          height: 55px;\n          background-color: #F9F9F9;\n\n          span {\n            color: #666666;\n          }\n        }\n\n      }\n\n\n      .el-table__body-wrapper {\n        .el-table__row {\n          .el-table__cell {\n            height: 55px;\n            padding: 0;\n\n            .cell {\n              .el-button--primary {\n                border: 1px solid #409EFF;\n                background-color: #40a0ff1f;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #409EFF;\n                  color: #fff;\n                }\n              }\n\n              .el-button--success {\n                border: 1px solid #67C23A;\n                background-color: #67c23a1d;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #67C23A;\n                  color: #fff;\n                }\n              }\n\n              .el-button--danger {\n                border: 1px solid #F67E7E;\n                background-color: #f67e7e15;\n                border-radius: 6px;\n                padding: 5px 9px;\n\n                &:hover {\n                  background: #F67E7E;\n                  color: #fff;\n                }\n              }\n            }\n\n            .cell>span {\n              color: #666666;\n            }\n          }\n        }\n\n        .expand-table-box {\n          .el-form-item__label,\n          .el-form-item__content {\n            color: #999999;\n          }\n        }\n      }\n    }\n  }\n\n  .avue-crud__pagination {\n    span {\n      color: #999999;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1840646327436394498 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848936255477424130, '1', 1, '2024-10-23 11:55:30', 101, 1, '2024-10-24 10:11:19', 0, 1840646327436394498, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.defaultExpandAll = true\n    buttonObj.value.header.addBtn.label = \'新建\'\n    buttonObj.value.menu.delBtn.params.size = \"small\"\n    buttonObj.value.menu.editBtn.params.size = \"small\"\n    useFun.setPropConfig(\'stature\', {\n      width: 120\n    })\n  },\n  qrBtn() {\n    message.success(\'已确认\')\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1848985908415733761, '1', 1, '2024-10-23 15:12:48', 101, NULL, NULL, 0, 1838855934516420610, 'js', 'return {\n  initOption() { //表格显示前执行\n    buttonObj.value.menu.viewBtn.params.size = \"small\"\n    buttonObj.value.menu.editBtn.params.size = \"small\"\n    buttonObj.value.menu.delBtn.params.size = \"small\"\n  },\n}');
