INSERT INTO `lowcode_dbform_enhance_js` VALUES (1851137650784915457, '1', 1, '2024-10-29 13:43:03', 101, 1, '2024-10-29 14:07:19', 0, 1850724499567386625, 'js', 'return {\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1851524923179270145, '1', 1, '2024-10-30 15:21:56', 101, 1, '2024-11-02 14:58:56', 0, 1851205230887346177, 'js', '//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_xq\', {\n  controlName: \'\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/teamDetails/index.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'详情\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { controlView_xq } = Vue.toRefs(rendControlData.value)\nconst controlData = controlView_xq.value.params //ControlView的配置\n\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.selection = false\n    tableOption.value.dialogWidth = \'45%\'\n    buttonObj.value.header.addBtn.label = \'创建团队\'\n    buttonObj.value.menu.viewBtn.display = false\n    useFun.setPropConfig(\'cy\', {\n      render: ({ row }) => {\n        let val = 0\n        if (row.cy) {\n          val = row.cy.split(\',\').length\n        }\n        return val\n      }\n    })\n\n  },\n  xq_btn(row) {\n    controlData.controlParams = {\n      data: row\n    }\n    controlView_xq.value.show = true //显示ControlView\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1851525945729613826, '1', 1, '2024-10-30 15:26:00', 101, 1, '2024-11-02 15:50:44', 0, 1851205230887346177, 'scss', '// 表格样式\n.low-table__1851205230887346177 {\n\n  .avue-crud__header {\n    .avue-crud__right {\n      display: none;\n    }\n  }\n\n  .el-form>.avue-crud__grid {\n    .avue-crud__grid__content {\n      height: 263px;\n\n      &::before {\n        height: 0;\n      }\n\n      .avue-crud__grid__item {\n        width: auto;\n      }\n\n      .tx,\n      .name,\n      .tdjs,\n      .cytx {\n        .avue-crud__grid__label {\n          display: none;\n        }\n      }\n\n      .tx {\n        .avue-crud__img {\n          width: 60px;\n          height: 60px;\n          display: flex;\n          align-items: center;\n          justify-content: center;\n\n          img {\n            height: 100%;\n            margin: 0 !important;\n            border-radius: 50%;\n\n          }\n        }\n      }\n\n      .name {\n        position: absolute;\n        top: 10px;\n        left: 90px;\n        font-weight: 700;\n\n        .control-input {\n          color: #666666;\n          font-size: 16px;\n          font-family: \'微软雅黑 Bold\', \'微软雅黑\', sans-serif;\n        }\n      }\n\n      .tdjs {\n        position: absolute;\n        top: 40px;\n        left: 90px;\n\n        .control-input {\n          color: #999999;\n          font-size: 14px;\n          overflow: hidden;\n          text-overflow: ellipsis;\n          white-space: initial;\n          display: -webkit-box;\n          -webkit-line-clamp: 2;\n          -webkit-box-orient: vertical;\n        }\n      }\n\n\n      .cytx {\n        position: absolute;\n        top: 100px;\n        left: 90px;\n\n        .avue-crud__img {\n          margin-left: -5px;\n\n          &:first-child {\n            margin-left: 0;\n          }\n\n          img {\n            height: 28px;\n            width: 28px;\n            border-radius: 50%;\n            margin-right: 0 !important;\n          }\n        }\n\n        .el-tag {\n          margin-left: 5px;\n        }\n      }\n\n\n\n      .cy,\n      .xm,\n      .rw {\n        position: absolute;\n        top: 155px;\n        display: block;\n        width: 33.3%;\n        padding-right: 0;\n\n\n\n        .avue-crud__grid__label,\n        .avue-crud__grid__value {\n          height: 28px;\n          line-height: 28px;\n          text-align: center;\n        }\n\n        .avue-crud__grid__label {\n          display: block;\n          font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n          font-weight: 400;\n          color: #999999;\n          margin: 0 auto;\n\n          &::after {\n            content: \'\';\n          }\n        }\n\n        .avue-crud__grid__value {\n          width: 100%;\n          font-size: 20px;\n          font-family: \'微软雅黑 Bold\', \'微软雅黑\', sans-serif;\n          font-weight: 700;\n          color: #666666;\n        }\n      }\n\n      .cy {\n        left: 0;\n      }\n\n      .xm {\n        left: 33.3%;\n      }\n\n      .rw {\n        left: 66.6%;\n      }\n\n      .menu {\n        position: absolute;\n        top: 210px;\n        left: 0;\n        width: 100%;\n\n        .avue-crud__grid__value {\n          width: 100%;\n\n          .el-button {\n            width: 33.3%;\n            height: 25px;\n            font-size: 12px;\n            color: #999999;\n            border-left: 1px solid rgba(233, 233, 233, 1);\n            border-radius: 0;\n            margin-left: 0;\n            padding: 0;\n\n            &:hover {\n              background-color: white;\n            }\n\n            &:first {\n              border-left: none;\n            }\n          }\n        }\n      }\n\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1851205230887346177 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1851796251979472897, NULL, NULL, NULL, NULL, 1, '2024-11-04 10:50:20', 0, 1851796249232203778, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_80779\', {\n  formId: \'1851890190622343169\', //表单设计id\n  formType: \'add\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1851796249232203778\', //表单开发id\n    dataId: \'\',//数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'创建相册\', //标题\n    width: \'35%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_53120\', {\n  controlName: \'albumForm\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/album/albumForm.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'相册详情\', //标题\n    width: \'90%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n\n\n//控件调用\nconst { formView_80779, controlView_53120 } = Vue.toRefs(rendControlData.value)\n// componentRef.value.formView_80779 FormView的Ref控件引用\n\n\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.columnBtn = false\n    buttonObj.value.header.addBtn.label = \'新建相册\'\n    buttonObj.value.header.addBtn.type = \'\'\n    buttonObj.value.header.addBtn.params = {\n      plain: true,\n      text: false,\n    }\n\n    tableOption.value.column.zt_img = {\n      render: ({ row }) => {\n        return h(\'img\', {\n          style: {\n            width: \'100%\',\n            height: \'100%\',\n          },\n          src: row.zt_img,\n          onMouseenter: () => mouseEnter(row.id, \'block\'),\n        }, [])\n      }\n    }\n    tableOption.value.column.zt_box = {\n      render: ({ row }) => {\n        return row.zt_box\n      }\n    }\n\n    //遮罩层\n    const mouseEnter = (id, type) => {\n      let widthStr = window.screen.width > 1536 ? 68.8 : \'62.8\'\n      if (type == \'block\') {\n        tableData.value.map(item => {\n          if (id == item.id) {\n            item.zt_box =\n              h(\'div\', {\n                style: { width: \'100%\', height: `${widthStr}%`, background: \'red\', position: \'absolute\', top: 0 }\n              }, [\n                h(\'img\', {\n                  style: {\n                    width: \'100%\',\n                    height: \'100%\',\n                    position: \'absolute\', top: 0\n                  },\n                  src: item.zt_img,\n                },),\n                h(\'div\', {\n                  style: {\n                    width: \'100%\',\n                    height: \'100%\',\n                    position: \'absolute\',\n                    top: 0,\n                    zIndex: \'99\',\n                    background: \'rgba(0, 0, 0, 0.5)\',\n                  },\n                  onMouseleave: () => mouseEnter(id, \'none\')\n                }, [\n                  h(\'div\', {\n                    style: { height: \'30px\', display: \'flex\', justifyContent: \'end\', padding: \'10px 20px 0px 20px\' },\n                  }, [\n                    h(Icon, { icon: \'bytesize:edit\', size: 20, color: \'#fff\', style: { cursor: \'pointer\' }, onClick: () => clickFun() }),\n                    h(Icon, { icon: \'bitcoin-icons:copy-outline\', size: 20, color: \'#fff\', style: { padding: \'0px 20px\', cursor: \'pointer\' }, onClick: () => clickFun() }),\n                    h(Icon, { icon: \'ic:outline-delete\', size: 20, color: \'#fff\', style: { cursor: \'pointer\' }, onClick: () => clickFun(\'del\') }),\n                  ]),\n                  h(\'div\', {\n                    style: {\n                      width: \'100%\',\n                      height: \'82%\',\n                      display: \'flex\', justifyContent: \'center\', alignItems: \'center\',\n                    },\n                  }, [\n                    h(\'div\', { class: \'btn\', style: { cursor: \'pointer\' }, onClick: () => viewFun() }, \'查看相册\'),\n                  ])\n                ])\n              ])\n          }\n\n          return item\n        })\n      } else {\n        tableData.value.map(item => {\n          if (id == item.id) {\n            item.zt_box = \'\'\n          }\n        })\n      }\n\n    }\n\n    //创建相册点击事件\n    const clickFun = (date) => {\n      if (date) {\n        message.confirm(\'是否确定删除数据？\', \'操作确认\', { type: \'warning\' })\n        return false\n      }\n      formView_80779.value.show = true //显示FormView\n      const controlData = formView_80779.value.params //FormView的配置\n    }\n\n    //查看相册\n    const viewFun = () => {\n      controlView_53120.value.show = true //显示ControlView\n      const controlData = controlView_53120.value.params //ControlView的配置\n    }\n\n    tableOption.value.column.time_test = {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { display: \'flex\', justifyContent: \'space-between\', width: \'100%\', height: \'40px\', fontFamily: `\'MicrosoftYaHei\', \'微软雅黑\', sans-serif`, fontWeight: 400 }\n          }, [\n            h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\', },\n            }, [\n              h(Icon, { icon: \'ic:baseline-photo-library\', size: 14 }),\n              h(\'span\', { style: { marginLeft: \'2px\' } }, row.num),\n            ]),\n            h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\' },\n            }, [\n              h(Icon, { icon: \'mingcute:time-line\', size: 14 }),\n              h(\'span\', { style: { marginLeft: \'2px\' } }, useFun.formatPast(row.create_time, \'YYYY-MM-DD\')),\n            ]),\n          ])\n        }\n        return \'\'\n      }\n    }\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      // tableData.value.map()\n      resolve(data)\n    })\n  },\n  sctpBtn() {\n    formView_80779.value.show = true //显示FormView\n    const controlData = formView_80779.value.params //FormView的配置\n    controlData.formId = \'1852253282782900226\'\n    controlData.formType = \'edit\'\n    controlData.popOption.title = \'上传到相册\'\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1851796251979472898, NULL, NULL, NULL, NULL, NULL, '2024-11-20 16:23:04', 0, 1851796249232203778, 'scss', '// 表格样式\n.low-table__1851796249232203778 {\n  .avue-crud__grid__content {\n    padding: 0;\n\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n      padding: 0;\n\n      &.zt_img {\n        width: 100%;\n        height: 56%;\n        aspect-ratio: 1 / 0.56; //保持元素纵横比\n      }\n\n      .low-field__zt_img {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 100%;\n\n        .avue-crud__img {\n          width: 100%;\n\n          img {\n            width: 100%;\n            height: 56%;\n            margin-right: 0 !important;\n            object-fit: cover\n          }\n        }\n      }\n\n      &.zt_title {\n        margin:10px 12px 0px 17px;\n        font-size: 14px;\n        color: #666;\n        font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n        font-weight: 400;\n      }\n\n      &.zt_type {\n        font-size: 14px;\n        color: #999;\n      }\n\n      &.time_test {\n        width: 100%;\n        padding: 0px 17px;\n        margin-top: 15px;\n      }\n\n      &.menu {\n        margin-top: 4px;\n      }\n    }\n  }\n\n  .avue-crud__grid__value {\n    width: 100%;\n    white-space: normal;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content::before {\n    background: none;\n  }\n\n  .btn {\n    color: #fff;\n    font-family: \'微软雅黑\', sans-serif;\n    font-weight: 500;\n    font-size: 12px;\n    padding: 5px 20px;\n    border: 1px solid #fff;\n    border-radius: 5px;\n    margin-top: -50px;\n  }\n\n  .btn:hover {\n    color: #666;\n    background: #fff;\n  }\n\n  .avue-crud__grid__item.zt_img {\n    // height: 210px;\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1851796249232203778 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1852237382402928641, '1', 1, '2024-11-01 14:33:00', 101, NULL, '2024-11-14 15:28:40', 0, 1852234473116233730, 'js', 'return {\n  initOption() { //表格显示前执行\n    if (props.enhanceData.type && props.enhanceData.type == \'view\') {\n      tableOption.value.header = false\n      tableOption.value.selection = false\n      tableOption.value.menu = false\n      tableOption.value.border = false\n    }\n\n\n    useFun.setPropConfig(\'cyxm_name\', {\n      render: ({ row }) => {\n\n        let text = row.cyxm_name\n        let imgH = h(\'img\', { style: { borderRadius: \'50%\', width: \'23px\', height: \'23px\', marginRight: \'5px\' }, src: \'http://oss.yckxt.com/chatgpt/upload/1/2024-10-31/1/f0ee8a3c7c9638a54940382568c9dpng_2.png\', })\n\n        return h(\'div\', { class: [\'h-100%\', \'flex\', \'items-center\', \'justify-center\'] }, [imgH, h(\'span\', { style: { fontSize: \'12px\' } }, text)])\n      }\n    })\n\n\n\n    useFun.setPropConfig(\'yql\', {\n      render: ({ row }) => {\n        let val = \'\'\n        let val1 = row.yyq | 0\n        let val2 = row.rwzs | 0\n        val = val2 == 0 ? \'0%\' : (val1 / val2) * 100 + \'%\'\n        return val\n      }\n    })\n\n    useFun.setPropConfig(\'wcl\', {\n      render: ({ row }) => {\n        let val = \'\'\n        let val1 = row.ywc | 0\n        let val2 = row.rwzs | 0\n        val = val2 == 0 ? \'0%\' : (val1 / val2) * 100 + \'%\'\n\n        // let greenH = h(\'div\', { class: [\'bg-#51D351\', `w-${val}`, \'h-100%\', \'rounded-2xl\'] }, \'\')\n        // let huiH = h(\'div\', { class: [\'bg-#E9E9E9\', \'w-100px\', \'h-8px\', \'rounded-2xl\', \'mr-10px\'] }, greenH)\n\n        let greenH = h(\'div\', { style: { backgroundColor: \'#51D351\', width: val, height: \'100%\', borderRadius: \'5px\' } }, \'\')\n        let huiH = h(\'div\', { style: { backgroundColor: \'#E9E9E9\', width: \'100px\', height: \'8px\', borderRadius: \'5px\', marginRight: \'10px\' } }, greenH)\n\n        return h(\'div\', { style: { display: \'flex\', alignItems: \'center\' } }, [huiH, val])\n      }\n    })\n\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1852241982870745089, NULL, NULL, NULL, NULL, NULL, '2024-11-15 15:44:25', 0, 1852241979997646849, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_80779\', {\n  formId: \'1851890190622343169\', //表单设计id\n  formType: \'add\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1851796249232203778\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'创建相册\', //标题\n    width: \'35%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_53120\', {\n  controlName: \'albumForm\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/album/albumForm.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'相册详情\', //标题\n    width: \'60%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n\n\n//控件调用\nconst { formView_80779, controlView_53120 } = Vue.toRefs(rendControlData.value)\n// componentRef.value.formView_80779 FormView的Ref控件引用\n\n\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.columnBtn = false\n\n    tableOption.value.column.zt_img = {\n      render: ({ row }) => {\n        return h(\'img\', {\n          style: { width: \'100%\', height: \'50%\' },\n          src: row.zt_img\n        }, [])\n      }\n    }\n\n    tableOption.value.column.time_test = {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: {\n              display: \'flex\',\n              justifyContent: \'space-between\',\n              fontFamily: `\'MicrosoftYaHei\', \'微软雅黑\', sans-serif`,\n              fontWeight: 400,\n              width: \'100%\',\n              height: \'40px\',\n            }\n          }, [\n            h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#666\', marginLeft: \'17px\', },\n            }, [\n              h(\'span\', { style: { marginLeft: \'2px\', fontFamily: `\'MicrosoftYaHei\', \'微软雅黑\', sans-serif`, fontWeight: 400, } }, row.name),\n            ]),\n            h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\', marginRight: \'17px\' },\n            }, [\n              h(Icon, { icon: \'mingcute:time-line\', size: 14 }),\n              h(\'span\', { style: { marginLeft: \'2px\' } }, useFun.formatPast(row.create_time, \'YYYY-MM-DD\')),\n            ]),\n          ])\n        }\n        return \'\'\n      }\n    }\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      // tableData.value.map()\n      resolve(data)\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1852241982870745090, NULL, NULL, NULL, NULL, 1, '2024-11-02 11:34:59', 0, 1852241979997646849, 'scss', '// 表格样式\n.low-table__1852241979997646849 {\n  .avue-crud__tip {\n    display: none;\n  }\n\n  .avue-crud__grid__content {\n    \n    padding: 0;\n\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n      padding: 0;\n\n      &.zt_img {\n        width: 100%;\n        aspect-ratio: 1 / 0.56; //保持元素纵横比\n      }\n\n      .low-field__zt_img {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 100%;\n\n        .avue-crud__img {\n          width: 100%;\n\n          img {\n            width: 100%;\n            height: 56%;\n            margin-right: 0 !important;\n            object-fit: cover\n          }\n        }\n      }\n\n      &.zt_title {\n        // margin-top: 10px;\n        margin-left: 17px;\n        font-size: 14px;\n        color: #666;\n        font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n        font-weight: 400;\n      }\n\n      &.zt_type {\n        font-size: 14px;\n        color: #999;\n      }\n\n      &.time_test {\n        // width: 100%;\n        // padding: 5px 17px;\n        // margin-top: 5px;\n      }\n\n      &.menu {\n        margin-top: 4px;\n      }\n    }\n  }\n\n  .avue-crud__grid__value {\n    width: 100%;\n    white-space: normal;\n    // padding: 0 17px;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content::before {\n    background: none;\n  }\n\n  .btn {\n    color: #fff;\n    font-family: \'微软雅黑\', sans-serif;\n    font-weight: 500;\n    font-size: 12px;\n    padding: 5px 20px;\n    border: 1px solid #fff;\n    border-radius: 5px;\n    margin-top: -55px;\n  }\n\n  .btn:hover {\n    color: #666;\n    background: #fff;\n  }\n\n  .avue-crud__grid__item.zt_img {\n    // height: 210px;\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1852241979997646849 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1852269629856247809, '1', 1, '2024-11-01 16:41:08', 101, NULL, '2024-11-14 15:39:35', 0, 1852234473116233730, 'scss', '// 表格样式\n.low-table__1852234473116233730 {\n\n  .el-table__cell {\n    font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n    color: #666666 !important;\n    height: 55px;\n  }\n\n  .el-table__inner-wrapper {\n    .el-table__header-wrapper {\n      .el-table__cell {\n        background-color: white;\n      }\n    }\n\n    &::before {\n      height: 0;\n    }\n  }\n\n  .avue-crud__pagination {\n\n    .btn-prev,\n    .btn-next {\n      margin: 0;\n      padding: 0;\n    }\n\n    .btn-prev,\n    .btn-next,\n    .number {\n      width: 35px;\n      height: 35px;\n    }\n\n\n    .el-pagination__total,\n    .el-pagination__sizes,\n    .el-pagination__jump {\n      display: none;\n    }\n  }\n\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1852234473116233730 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1852630516890824705, '1', 1, '2024-11-02 16:35:10', 101, 1, '2024-11-04 15:48:42', 0, 1852624838914699265, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\n\nreturn {\n  initOption() { //表格显示前执行\n    buttonObj.value.header.exportBtn.label = \'导出数据\'\n    buttonObj.value.header.exportBtn.params = {\n      text: false,\n      type: \'default\'\n    }\n\n    tableOption.value.selection = false\n    buttonObj.value.header.addBtn.label = \'添加联系人\'\n    useFun.setPropConfig(\'color\', {\n      render: ({ row }) => {\n        let color = row.color\n        return h(\'div\', { style: { widht: \'inherit\', height: \'60px\', backgroundColor: color } }, \'\')\n      }\n    })\n\n    let arr = [\n      { key: \'sj\', icon: \'lineicons:phone\' },\n      { key: \'yx\', icon: \'mingcute:mail-line\' },\n      { key: \'dh\', icon: \'iconamoon:phone-light\' },\n      { key: \'dz\', icon: \'mdi:address-marker-outline\' },\n    ]\n    arr.forEach(ele => {\n      useFun.setPropConfig(ele.key, {\n        render: ({ row }) => {\n          let text = row[ele.key]\n          if (Icon) {\n            return h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', },\n            }, [\n              h(Icon, { icon: ele.icon, size: 18, style: { color: \'#CCCCCC\', marginRight: \'5px\' } }),\n              h(\'div\', text)\n            ])\n          }\n          return text\n        }\n      })\n    })\n  },\n\n  beforeSearch(search) { //搜索前执行\n    return new Promise(resolve => {\n      if (search.lx == \'1\') {\n        resolve({\n          \'pageNo\': 1,\n          \'pageSize\': 12\n        })\n      }\n      resolve(search)\n    })\n  },\n  beforeData(data) { //表格赋值前执行\n    return new Promise(resolve => {\n      data.forEach(ele => {\n        if (!ele.tx) ele.tx = \'http://oss.yckxt.com/chatgpt/upload/1/2024-11-02/1/f0ee8a3c7c9638a54940382568c9dpng_2.png\'\n      })\n      resolve(data)\n    })\n  },\n  yj_btn(row) {\n    // 定义邮件收件人、主题和正文内容\n    const recipients = [\'recipient1@example.com\', \'recipient2@example.com\'];\n    const subject = \'这是邮件的主题\';\n    const body = \'这是邮件的正文内容\';\n\n    // 拼接 `mailto` 链接\n    const to = recipients.join(\',\');\n    const mailtoLink = `mailto:${to}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;\n\n    // 打开系统默认的邮件客户端，并预填写相应信息\n    window.open(mailtoLink);\n  },\n  bj_btn(row) {\n    let data = {}\n    for (let key in row) {\n      if (key.indexOf(\'$\') == -1) data[key] = row[key]\n    }\n    data.lx = 2\n    useFun.requestApi(\'put\', \'/jeelowcode/dbform-data/edit/1852624838914699265\', {\n      data\n    }).then(res => {\n      useFun.refreshChange()\n    })\n\n  },\n  bj_two_btn(row) {\n\n    let data = {}\n    for (let key in row) {\n      if (key.indexOf(\'$\') == -1) data[key] = row[key]\n    }\n    data.lx = 1\n    useFun.requestApi(\'put\', \'/jeelowcode/dbform-data/edit/1852624838914699265\', {\n      data\n    }).then(res => {\n      useFun.refreshChange()\n    })\n\n\n\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1852637672214065153, '1', 1, '2024-11-02 17:03:36', 101, 1, '2024-11-04 17:09:00', 0, 1852624838914699265, 'scss', '// 表格样式\n.low-table__1852624838914699265 {\n\n  .el-card__body {\n    .avue-crud__header {\n      .avue-crud__right {\n        display: none;\n      }\n    }\n\n    .el-form {\n      .avue-crud__grid__content {\n        height: 250px;\n        display: block;\n\n        .avue-crud__grid__item {\n          .avue-crud__grid__label {\n            display: none;\n\n            &::after {\n              content: \'\';\n            }\n          }\n        }\n\n        .tx {\n          position: absolute;\n          top: 0px;\n          left: 20px;\n          z-index: 1;\n          height: 60px;\n          display: flex;\n          align-items: center;\n\n          img {\n            height: 35px;\n            border-radius: 50%;\n            margin: 0 !important;\n          }\n        }\n\n        .xm,\n        .zw {\n          position: absolute;\n          top: 0px;\n          z-index: 1;\n          height: 60px;\n          display: flex;\n          align-items: center;\n\n          .avue-crud__grid__value {\n            color: white;\n            font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n          }\n\n        }\n\n        .xm {\n          width: 65px;\n          left: 65px;\n\n        }\n\n        .zw {\n          width: 60px;\n          left: 125px;\n\n          .avue-crud__grid__value {\n            font-size: 12px;\n          }\n        }\n\n        .color {\n          position: absolute;\n          top: 0;\n          width: 100%;\n          left: 0;\n          padding-right: 0;\n\n          .avue-crud__grid__value {\n            width: inherit;\n          }\n\n        }\n\n        .gs,\n        .sj,\n        .yx,\n        .dh,\n        .dz {\n          width: 100%;\n          margin-left: 10px;\n          height: 32px;\n          line-height: 32px;\n          margin-bottom: 0;\n\n          .avue-crud__grid__value {\n            font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n\n          }\n\n        }\n\n        .sj,\n        .yx,\n        .dh,\n        .dz {\n          .avue-crud__grid__value {\n            font-size: 12px;\n          }\n        }\n\n        .gs {\n          margin-top: 64px;\n        }\n\n        .menu {\n          position: absolute;\n          top: 0px;\n          z-index: 1;\n          right: 10px;\n          height: 60px;\n          display: flex;\n          align-items: center;\n          margin-top: 0;\n\n          .avue-crud__grid__value {\n            .el-button {\n              color: white;\n              width: 35px;\n              height: 24px;\n              border-right: 1px solid #ffffff38;\n              padding: 0;\n              margin: 0;\n              border-radius: 0;\n\n              svg {\n                font-size: 18px;\n              }\n\n              &>span>span {\n                display: none;\n              }\n\n              &:last-child {\n                border-right: none;\n              }\n\n              &:hover {\n                background-color: initial;\n              }\n            }\n          }\n        }\n\n        &::before {\n          height: 0;\n        }\n      }\n    }\n  }\n\n  .avue-crud__pagination {\n\n    .btn-prev,\n    .btn-next {\n      margin: 0;\n      padding: 0;\n    }\n\n    .btn-prev,\n    .btn-next,\n    .number {\n      width: 35px;\n      height: 35px;\n    }\n\n    .btn-prev {\n      margin-left: 10px;\n    }\n\n\n    .el-pagination__total,\n    .el-pagination__jump {\n      display: none;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1852624838914699265 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1853271618111107073, '1', 1, '2024-11-04 11:02:41', 101, 1, '2024-11-05 14:07:39', 0, 1853269839533273090, 'scss', '// 表格样式\n.low-table__1853269839533273090 {\n  .avue-crud__grid {\n    .el-checkbox-group {\n      .el-row {\n\n        .avue-crud__grid__content::before {\n          height: 0;\n        }\n\n\n        &>.el-col:nth-child(2n) {\n          .avue-crud__grid__content {\n            background-color: #F5F5F5 !important;\n          }\n        }\n\n        .avue-crud__grid__content {\n          height: 72px;\n          padding: 13.5px;\n          padding-left: 30px;\n\n          .avue-crud__grid__item {\n            width: calc(100% / 7);\n            flex-direction: column;\n            font-family: \'微软雅黑\', sans-serif;\n            line-height: 36px;\n            text-align: left;\n            color: #666;\n\n            .avue-crud__grid__label {\n              color: #999;\n              font-size: 12px;\n\n              &::after {\n                content: \'\';\n              }\n            }\n\n            .avue-crud__grid__value {\n              height: 36px;\n              line-height: 36px;\n            }\n\n\n          }\n\n          .create_user {\n            .avue-crud__grid__value {\n              display: flex;\n              align-items: center;\n\n              img {\n                width: 20px;\n                height: 20px;\n                border-radius: 50%;\n              }\n            }\n          }\n\n          .menu {\n            margin: 0;\n            padding: 0;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n\n            .avue-crud__grid__value {\n              height: auto;\n\n              .el-button {\n                width: 25px;\n                height: 25px;\n                color: white;\n                border-radius: 50%;\n\n                &>span {\n                  width: 100%;\n                  height: 100%;\n                  position: relative;\n\n                  .el-icon {\n                    position: absolute;\n                    top: 50%;\n                    left: 50%;\n                    transform: translate(-50%, -50%);\n                  }\n\n                  &>span{\n                    display: none;\n                  }\n                }\n\n\n                svg {\n                  font-size: 16px;\n                }\n\n\n                &.el-button--primary {\n                  background-color: rgb(64, 158, 255);\n                  margin-right: 5px;\n                }\n\n                &.el-button--danger {\n                  background-color: rgb(245, 108, 108);\n                }\n              }\n            }\n\n            // height: 67px;\n          }\n        }\n      }\n    }\n  }\n\n  // .low-field__tjry>span::before{\n  //   width: 21px;\n  //   height: 21px;\n  //   background: #cccccc;\n  //   border-radius: 50%;\n  //   display: inline-block;\n  //   content: \'\';\n  //   background-image: url(../../../../../public/img/user.jpg);\n  //   background-repeat: no-repeat;\n  //   background-size: 100% 100%;\n  //   margin-right:3px;\n  // }\n\n  .low-field__pyzt>span::before {\n    width: 7px;\n    height: 7px;\n    border-radius: 50%;\n    background: #fec03d;\n    display: inline-block;\n    content: \'\';\n    margin-right: 5px;\n  }\n\n  // .low-field__tjry>span,.low-field__pyzt>span{\n  //   display: flex;\n  //   align-items: center;\n  // }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1853269839533273090 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1853283093823320066, '1', 1, '2024-11-04 11:48:17', 101, 1, '2024-11-07 09:30:15', 0, 1853269839533273090, 'js', 'let Icon = \'\'\nlet lowStore = null\nlet username = \'\'\n\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\nuseFun.dynamicImport(\'store/modules/low\').then(module => {\n  if (module) {\n    lowStore = module.useLowStoreWithOut()\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_gzbg\', {\n  formId: \'1853325190400012289\', //表单设计id\n  formType: \'add\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: false, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'新增报告\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      useFun.resetChange()\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_bgxq\', {\n  controlName: \'\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/workReport/components/index.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'报告详情\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { formView_gzbg, controlView_bgxq } = Vue.toRefs(rendControlData.value)\nconst controlData = formView_gzbg.value.params //FormView的配置\n\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.searchShowBtn = false\n\n    buttonObj.value.header.addBtn.display = false\n    buttonObj.value.menu.editBtn.display = false\n    buttonObj.value.menu.viewBtn.display = false\n    buttonObj.value.menu.delBtn.label = \'\'\n    buttonObj.value.menu.delBtn.icon = \'mingcute:delete-line\'\n\n    useFun.setPropConfig(\'create_user\', {\n      render: ({ row }) => {\n        let defaultImg = \'http://oss.yckxt.com/chatgpt/upload/1/2024-11-02/1/f0ee8a3c7c9638a54940382568c9dpng_2.png\'\n        username = lowStore.dicObj.userSelect?.[row.create_user] || row.create_user\n\n        return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' }, }, [\n          h(\'img\', { src: defaultImg, style: { marginRight: \'5px\' } }),\n          h(\'div\', username)\n        ])\n      }\n    })\n  },\n  xjbg_btn() {\n    controlData.formType = \'add\'\n    controlData.popOption.title = \'新增报告\'\n    controlData.defaultData = {}\n    formView_gzbg.value.show = true //显示FormView\n  },\n  bj_btn(row) {\n    controlData.formType = \'edit\'\n    controlData.popOption.title = \'编辑报告\'\n    controlData.defaultData = row\n    formView_gzbg.value.show = true //显示FormView\n  },\n  xq_btn(row) {\n    //控件调用\n    controlView_bgxq.value.show = true //显示ControlView\n    const bgxq = controlView_bgxq.value.params //ControlView的配置\n\n    bgxq.controlParams = {\n      data: {\n        ...row,\n        username: username\n      },\n      stepList: props.enhanceData.stepList,\n      form2Data: props.enhanceData.form2Data\n    }\n\n  }\n\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854096209561759746, '1', 1, '2024-11-06 17:39:18', 101, NULL, '2024-11-20 13:57:00', 0, 1854067250698612737, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.searchIndex = 5\n\n    buttonObj.value.header.exportBtn.label = \'导出数据\'\n    buttonObj.value.header.exportBtn.params = {\n      text: false,\n      type: \'default\'\n    }\n    buttonObj.value.menu.viewBtn.params = {\n      plain: true,\n      text: false,\n      size: \"small\"\n    }\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') apiData.czbh = useFun.formatDate(new Date(), \'YYYYMMDD\')\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854099929380925441, '1', 1, '2024-11-06 17:54:05', 101, NULL, '2024-11-20 11:18:57', 0, 1854067250698612737, 'scss', '// 表格样式\n.low-table__1854067250698612737 {\n  .avue-crud__body {\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .avue-crud__header {\n      .el-button--primary {\n        background: #ffffff;\n        color: #999;\n        border-color: #e4e4e4;\n\n        &:hover {\n          border-color: #7bbbff;\n          color: #7bbbff;\n          background: #f0f7ff;\n        }\n      }\n    }\n\n    .el-form {\n      border-left: 1px solid #ebeef5;\n      border-right: 1px solid #ebeef5;\n\n      .el-table__inner-wrapper {\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n            .el-table__cell {\n              font-family: \'微软雅黑\', sans-serif;\n              font-weight: 400;\n            }\n\n            &.el-table__row--striped {\n\n              .el-table__cell {\n                background: #f2f2f2;\n              }\n            }\n\n          }\n\n        }\n\n        .cell>span {\n          color: #666;\n        }\n      }\n    }\n\n\n  }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854067250698612737 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854331402176409602, NULL, NULL, NULL, NULL, NULL, '2024-11-20 14:03:10', 0, 1854331399533998082, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.searchIndex = 5\n\n    buttonObj.value.header.exportBtn.label = \'导出数据\'\n    buttonObj.value.header.exportBtn.params = {\n      text: false,\n      type: \'default\'\n    }\n    buttonObj.value.menu.viewBtn.params = {\n      plain: true,\n      text: false,\n      size: \"small\"\n    }\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.spbh = useFun.formatDate(new Date(), \'YYYYMMDD\')\n        apiData.ywbh = \'HT\' + useFun.formatDate(new Date(), \'YYYYMMDD\')\n        apiData.tjsj = useFun.formatDate(new Date(), \'YYYY-MM-DD HH:mm:ss\')\n      }\n\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854331402184798209, NULL, NULL, NULL, NULL, NULL, '2024-11-20 14:04:17', 0, 1854331399533998082, 'scss', '// 表格样式\n.low-table__1854331399533998082 {\n  .avue-crud__body {\n\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .avue-crud__header {\n      .el-button--primary {\n        background: #ffffff;\n        color: #999;\n        border-color: #e4e4e4;\n\n        &:hover {\n          border-color: #7bbbff;\n          color: #7bbbff;\n          background: #f0f7ff;\n        }\n      }\n    }\n\n    .el-form {\n      border-left: 1px solid #ebeef5;\n      border-right: 1px solid #ebeef5;\n\n      .el-table__inner-wrapper {\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n            .el-table__cell {\n              font-family: \'微软雅黑\', sans-serif;\n              font-weight: 400;\n            }\n\n            &.el-table__row--striped {\n\n              .el-table__cell {\n                background: #f2f2f2;\n              }\n            }\n\n          }\n\n        }\n\n        .cell>span {\n          color: #666;\n        }\n      }\n    }\n\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854331399533998082 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854341004418854914, NULL, NULL, NULL, NULL, 1, '2024-11-07 10:06:22', 0, 1854341001851940865, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.searchIndex = 5\n\n    buttonObj.value.header.exportBtn.label = \'导出数据\'\n    buttonObj.value.header.exportBtn.params = {\n      text: false,\n      type: \'default\'\n    }\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854341004418854915, NULL, NULL, NULL, NULL, NULL, '2024-11-20 14:08:24', 0, 1854341001851940865, 'scss', '// 表格样式\n.low-table__1854341001851940865 {\n\n  .avue-crud__body {\n\n\n    .avue-crud__tip {\n      display: none;\n    }\n\n    .avue-crud__header {\n      .el-button--primary {\n        background: #ffffff;\n        color: #999;\n        border-color: #e4e4e4;\n\n        &:hover {\n          border-color: #7bbbff;\n          color: #7bbbff;\n          background: #f0f7ff;\n        }\n      }\n    }\n\n    .el-form {\n      border-left: 1px solid #ebeef5;\n      border-right: 1px solid #ebeef5;\n\n      .el-table__inner-wrapper {\n        .el-table__header {\n          height: 55px;\n\n          .el-table__cell {\n            background: #f2f2f2;\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n          }\n        }\n\n        .el-table__body-wrapper {\n          .el-table__row {\n            height: 55px;\n\n            .el-table__cell {\n              font-family: \'微软雅黑\', sans-serif;\n              font-weight: 400;\n            }\n\n            &.el-table__row--striped {\n\n              .el-table__cell {\n                background: #f2f2f2;\n              }\n            }\n\n          }\n\n        }\n\n        .cell>span {\n          color: #666;\n        }\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854341001851940865 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854351931109257218, '1', 1, '2024-11-07 10:35:27', 101, 1, '2024-11-07 15:01:53', 0, 1854048263491252226, 'js', '\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_95659\', {\n  formId: \'1854399122108559362\', //表单设计id\n  formType: \'view\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'1854048263491252226\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'公告详情\', //标题\n    width: \'\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [ //底部按钮配置\n      // {\n      //   params: {}, //el-button 其他参数\n      //   name: \'测试按钮\', //按钮名称\n      //   display: true, //是否显示\n      //   loading: true, //点击时是否有loading\n      //   icon: \'\', //图标\n      //   clickFun: (loading) => {\n      //     //点击事件\n      //     if (loading) loading() //关闭loading\n      //   }\n      // }\n    ],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n//控件调用\nconst { formView_95659 } = Vue.toRefs(rendControlData.value)\n\n\nreturn {\n  initOption() { //表格显示前执行\n    tableOption.value.refreshBtn = false\n    tableOption.value.columnBtn = false\n    tableOption.value.searchShowBtn = false\n    tableOption.value.searchIndex = 5\n\n    useFun.setPropConfig(\'ggzt\', {\n      render: (optins) => {\n        let { row, column } = optins\n        let reStatus = \'\'\n        let status = row.ggzt\n        let color = \'#19be6b\'\n        column.dicData.some(item => {\n          if (item.value == status) {\n            reStatus = item.label\n            status = status == \'1\' ? color : \'red\'\n            return true\n          }\n        })\n        const radius = h(\'div\', { style: { width: \'6px\', height: \'6px\', borderRadius: \'50%\', backgroundColor: color, marginRight: \'5px\' } }, \'\')\n        if (reStatus) return h(\'span\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [radius, reStatus])\n      }\n    })\n\n    let arr = [\'xqBtn\', \'delBtn\']\n    arr.map(item => {\n      buttonObj.value.menu[item].params = {\n        plain: true,\n        text: false,\n        size: \"small\"\n      }\n    })\n    buttonObj.value.menu.xqBtn.icon = \'icon-park-outline:right-c\'\n  },\n  xqBtn(row) {\n    formView_95659.value.show = true //显示FormView\n    const controlData = formView_95659.value.params //FormView的配置\n    controlData.defaultData = row\n  }\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854359437000814594, '1', 1, '2024-11-07 11:05:17', 101, 1, '2024-11-07 13:38:15', 0, 1854048263491252226, 'scss', '// 表格样式\n.low-table__1854048263491252226 {\n  .avue-crud__tip {\n    display: none;\n  }\n\n  // .avue-crud__header {\n  //   .el-button--primary {\n  //     background: #ffffff;\n  //     color: #999;\n  //     border-color: #e4e4e4;\n\n  //     &:hover {\n  //       border-color: #7bbbff;\n  //       color: #7bbbff;\n  //       background: #f0f7ff;\n  //     }\n  //   }\n  // }\n\n  .el-table__inner-wrapper {\n    .el-table__header {\n      height: 55px;\n\n      .el-table__cell {\n        background: #f2f2f2;\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n      }\n    }\n\n    .el-table__body-wrapper {\n      .el-table__row {\n        height: 55px;\n\n        &.el-table__row--striped {\n\n          .el-table__cell {\n            font-family: \'微软雅黑\', sans-serif;\n            font-weight: 400;\n            background: #f2f2f2;\n          }\n        }\n\n      }\n\n    }\n\n    .cell>span {\n      color: #666;\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854048263491252226 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854409482811191298, '1', 1, '2024-11-07 14:24:09', 101, 1, '2024-11-08 15:11:46', 0, 1854408557228961794, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_htlb\', {\n  controlName: \'\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/riendshipForum/components/topicList.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'drawer\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'话题列表\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n//控件调用\nconst { controlView_htlb } = Vue.toRefs(rendControlData.value)\n\nreturn {\n  initOption() { //表格显示前执行\n    // 点击用抽屉 80%   ，后面用弹窗，编辑时先关闭弹窗\n    useFun.setPropConfig(\'htsl\', {\n      render: ({ row }) => {\n        const numH = h(\'div\', { style: { fontSize: \'18px\', color: \'#666666\', fontFamily: \'微软雅黑, sans-serif\' } }, row.htsl)\n        const iconTitH = h(\'div\', { style: { color: \'#999999\', fontSize: \'12px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [h(Icon, { icon: \'mynaui:message\', size: \'18\', style: { marginRight: \'3px\' } }), \'话题\'])\n        return h(\'div\', { style: { height: \'56px\', lineHeight: \'28px\' } }, [numH, iconTitH])\n      }\n    })\n\n    useFun.setPropConfig(\'hfsl\', {\n      render: ({ row }) => {\n        const numH = h(\'div\', { style: { fontSize: \'18px\', color: \'#666666\', fontFamily: \'微软雅黑, sans-serif\' } }, row.hfsl)\n        const iconTitH = h(\'div\', { style: { color: \'#999999\', fontSize: \'12px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [h(Icon, { icon: \'ri:wechat-pay-line\', size: \'18\', style: { marginRight: \'3px\' } }), \'回复\'])\n        return h(\'div\', { style: { height: \'56px\', lineHeight: \'28px\' } }, [numH, iconTitH])\n      }\n    })\n\n    if (props.enhanceData && props.enhanceData.type == \'view\') {\n      tableOption.value.menu = false\n      tableOption.value.selection = false\n      tableOption.value.header = false\n    }\n  },\n\n  cellClick(row, column, cell, event) { //单元格单击\n\n    if (column.prop == \'htbk\' || column.prop == \'bkjs\') {\n      controlView_htlb.value.show = true //显示ControlView\n      const controlData = controlView_htlb.value.params //ControlView的配置\n      // componentRef.value.controlView_htlb ControlView的Ref控件引用\n\n    }\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854417850556723202, '1', 1, '2024-11-07 14:57:24', 101, 1, '2024-11-08 15:03:32', 0, 1854408557228961794, 'scss', '// 表格样式\n.low-table__1854408557228961794 {\n  .el-checkbox-group {\n    &>.el-row>.el-col {\n      padding: 0;\n      padding-top: 10px;\n      border-bottom: 1px solid #e9e9e9;\n\n\n      .avue-crud__grid__content {\n        margin: 10px 30px;\n        padding: 0 16px;\n        height: 70px;\n        border: none;\n        border-radius: 0;\n        display: flex;\n        align-items: center;\n\n        &::before {\n\n          height: 0;\n        }\n\n        .avue-crud__grid__item {\n          width: auto;\n\n          .avue-crud__grid__label {\n            display: none;\n          }\n        }\n\n        .bktx {\n          .avue-crud__img {\n            width: 60px;\n            height: 60px;\n            border-radius: 50%;\n            background-color: rgba(204, 204, 204, 1);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n\n            img {\n              height: 28px;\n              margin-right: 0 !important;\n            }\n          }\n        }\n\n        .htbk {\n          position: absolute;\n          top: 6px;\n          left: 95px;\n\n          .avue-crud__grid__value {\n            font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n            font-weight: 700;\n            font-size: 18px;\n          }\n        }\n\n        .bkjs {\n          position: absolute;\n          top: 35px;\n          left: 95px;\n\n          .avue-crud__grid__value {\n            font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n            font-weight: 400;\n            color: #999999;\n          }\n\n        }\n\n        .htbk,\n        .bkjs {\n          cursor: pointer;\n        }\n\n        .create_user {\n          margin-left: 555px;\n          margin-right: 10px;\n\n          .avue-crud__grid__value {\n            font-family: \'微软雅黑\', sans-serif;\n            font-weight: 400;\n            font-size: 12px;\n            color: #999999;\n          }\n\n        }\n\n        .cytx {\n          .upload-show-box {\n            .avue-crud__img {\n              margin-right: -11px;\n\n              img {\n                height: 35px;\n                width: 35px;\n                border-radius: 50%;\n                margin-right: 0 !important;\n              }\n\n\n            }\n\n            .el-tag {\n              margin-left: 15px;\n            }\n          }\n        }\n\n        .htsl {\n          margin-left: auto;\n          width: 120px;\n          display: flex;\n          justify-content: center;\n        }\n\n        .hfsl {\n          width: 120px;\n          display: flex;\n          justify-content: center;\n        }\n\n\n      }\n    }\n  }\n\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854408557228961794 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854447544547127297, '1', 1, '2024-11-07 16:55:23', 101, 1, '2024-11-08 11:41:30', 0, 1854438272522235905, 'js', 'return {\n  initOption() { //表格显示前执行\n    tableOption.value.column.cp_title = {\n      render: ({ row }) => {\n        return h(\'div\', {\n          style: {\n            width: \'100%\',\n            cursor: \'pointer\'\n            // height: \'100%\',\n          },\n          onClick: () => clickFun()\n        }, row.cp_title)\n      }\n    }\n    tableOption.value.column.cp_text = {\n      render: ({ row }) => {\n        return h(\'div\', {\n          style: {\n            width: \'100%\',\n            cursor: \'pointer\'\n            // height: \'100%\',\n          },\n          onClick: () => clickFun()\n        }, row.cp_text)\n      }\n    }\n    tableOption.value.column.num = {\n      render: ({ row }) => {\n        return h(\'div\', {\n          style: {\n            width: \'100%\',\n            cursor: \'pointer\'\n            // height: \'100%\',\n          },\n          onClick: () => clickFun()\n        }, `${row.num}条知识`)\n      }\n    }\n\n    const clickFun = () => {\n      props.enhanceData.clickFun()\n    }\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if(type == \'add\'){\n        apiData.llcs = 0\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854448815274438657, '1', 1, '2024-11-07 17:00:26', 101, NULL, '2024-11-20 15:41:07', 0, 1854438272522235905, 'scss', '// 表格样式\n.low-table__1854438272522235905 {\n\n  .avue-crud__grid__content::before {\n    display: none;\n  }\n\n  .avue-crud__grid__content {\n    flex-direction: column;\n    padding: 30px 0;\n\n    .avue-crud__grid__item {\n      margin: auto;\n      justify-content: center;\n\n      .avue-crud__grid__label {\n        display: none;\n      }\n\n      &.img {\n        margin-bottom: 15px;\n\n        .avue-crud__img {\n          img {\n            height: 70px;\n            margin-right: 0 !important;\n          }\n        }\n      }\n\n      &.cp_title,\n      &.cp_text,\n      &.num {\n        height: 28px;\n        line-height: 28px;\n      }\n\n      &.cp_title {\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n        font-weight: 700;\n        color: #666;\n        height: 28px;\n        line-height: 28px;\n\n        .avue-crud__grid__value {\n          font-size: 16px;\n        }\n      }\n\n      &.cp_text {\n        font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n        font-weight: 400;\n        color: #999999;\n        font-size: 14px;\n\n      }\n\n      &.num {\n        .avue-crud__grid__value {\n          color: #409eff;\n        }\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854438272522235905 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854695848728047618, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1854695846278574082, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\nreturn {\n  initOption() { //表格显示前执行\n\n    buttonObj.value.menu.viewBtn.label = \'查看详情\'\n    buttonObj.value.menu.viewBtn.icon = \'formkit:right\'\n\n    tableOption.value.column.content = {\n      render: ({ row }) => {\n        if (Icon) {\n          return h(\'div\', {\n            style: { width: \'100%\', display: \'flex\', justifyContent: \'space-between\', marginTop: \'10px\' },\n          }, [\n            h(\'div\', {\n              style: { width: \'80%\', fontFamily: `\'MicrosoftYaHei\', \'微软雅黑\', sans-serif`, color: \'#999999 !important\', fontSize: \'14px\', textAlign: \'left\', },\n            }, row.content),\n            h(\'div\', {\n              style: { display: \'flex\', alignItems: \'center\', fontSize: \'14px\', color: \'#999\', marginTop: \'-26px\' },\n            }, [\n              h(Icon, { icon: \'mingcute:time-line\', size: 14 }),\n              h(\'span\', { style: { marginLeft: \'2px\' } }, row.time),\n            ])\n          ])\n        }\n        return \'\'\n      }\n    }\n\n\n  },\n  beforeRequest(type, apiData) { //新增、修改、删除请求接口前执行\n    return new Promise((resolve, reject) => {\n      if (type == \'add\') {\n        apiData.time = useFun.formatDate(new Date, \'YYYY-MM-DD HH:mm\')\n      }\n      resolve(apiData)\n      // reject() 可以停止当前请求台的操作\n    })\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854695848728047619, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1854695846278574082, 'scss', '// 表格样式\n.low-table__1848649270435160066 {\n  .avue-crud__grid__content {\n    width: 400%;\n\n    .avue-crud__grid__label {\n      display: none;\n    }\n\n    .avue-crud__grid__item {\n      width: 100%;\n\n      &.zt_img {\n        width: 100%;\n        aspect-ratio: 1 / 0.56; //保持元素纵横比\n      }\n\n      .low-field__zt_img {\n        position: absolute;\n        left: 0;\n        top: 0;\n        width: 100%;\n\n        .avue-crud__img {\n          width: 100%;\n\n          img {\n            width: 100%;\n            height: 56%;\n            margin-right: 0 !important;\n            object-fit: cover\n          }\n        }\n      }\n\n      &.zt_title {\n        margin-top: 10px;\n        font-size: 14px;\n        color: #333;\n      }\n\n      &.zt_type {\n        font-size: 14px;\n        color: #999;\n      }\n\n      &.time_test {\n        position: absolute;\n        left: 16px;\n        bottom: 5px;\n        width: 94px;\n      }\n\n      &.menu {\n        margin-top: 4px;\n      }\n    }\n  }\n\n  .avue-crud__grid__value {\n    white-space: normal;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content {\n    padding: 16px;\n    border: none;\n    border-bottom: 1px solid #f2f2f2;\n  }\n\n  .avue-crud__grid .avue-crud__grid__content::before {\n    background: none;\n  }\n\n  .el-row {\n    display: flex;\n    flex-direction: column;\n  }\n\n  .avue-crud__grid .title .avue-crud__grid__value {\n    font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\n    font-weight: 700;\n    font-style: normal;\n    font-size: 16px;\n    text-align: left;\n    color: #666666;\n  }\n\n\n  .avue-crud__grid .menu {\n    justify-content: start;\n\n    .el-button {\n      border: 1px solid #e4e4e4;\n    }\n\n    .el-button:last-child {\n      position: absolute;\n      right: 20px;\n      border: none;\n\n      >span {\n        flex-direction: row-reverse;\n      }\n    }\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1848649270435160066 {}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854720471423234050, '1', 1, '2024-11-08 10:59:54', 101, 1, '2024-11-09 09:27:46', 0, 1854716968965484545, 'js', 'let Icon = \'\'\nconst h = Vue.h\nuseFun.dynamicImport(\'components/Icon/src/Icon.vue\').then(module => {\n  if (module) {\n    Icon = module.default\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'ControlView\', \'controlView_article\', {\n  controlName: \'\', //控件名称（全局注册的控件使用，例：el-transfer ）\n  controlPath: \'views/lowTemplate/generalPage/riendshipForum/components/article.vue\', //控件相对路径（未全局注册的控件使用，例：components/IFrame/src/IFrame.vue）\n  controlParams: {}, //控件配置\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  popOption: { //弹窗配置\n    title: \'话题详情\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {}, //弹窗其他配置\n    handleClose: (done) => { //关闭弹窗前的回调\n      done()\n    }\n  }\n})\n\n\n//初始化控件\nuseFun.controlInit(\'FormView\', \'formView_htbj\', {\n  formId: \'1854442042421391362\', //表单设计id\n  formType: \'edit\', //表单类型 add | edit | view\n  handleType: \'\', //处理类型 default | returnData\n  showType: \'dialog\', //弹窗类型 dialog | drawer\n  showButton: true, //是否显示底部默认操作按钮\n  dataOption: { //数据配置 \n    tableId: \'\', //表单开发id\n    dataId: \'\' //数据id\n  },\n  defaultData: {}, //默认表单数据\n  enhanceData: {}, //传递给表单js增强内部调用配置\n  popOption: { //弹窗配置\n    title: \'话题编辑\', //标题\n    width: \'80%\', //弹窗宽度\n    fullscreen: false, //是否全屏\n    footerBtn: [],\n    headerBtn: [], //顶部按钮配置（配置同上）\n    dialogParams: {} //弹窗其他配置\n  },\n  beforeClose: (type, done, formData, loading) => {\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\n    if (type == \'submit\') {\n      useFun.refreshChange()\n      console.log(\'表单数据\', formData)\n    }\n    done()\n  }\n})\n\n\n//控件调用\nconst { controlView_article, formView_htbj } = Vue.toRefs(rendControlData.value)\n\n\nreturn {\n  initOption() { //表格显示前执行\n\n    useFun.setPropConfig(\'sd\', {\n      render: ({ row }) => {\n        if (row.sd && row.sd == \'1\') {\n          return h(Icon, { icon: \'solar:lock-linear\', size: \'17\', style: { color: \'#999999\', } })\n        }\n        return \'\'\n      }\n    })\n\n    useFun.setPropConfig(\'zdrm_tit\', {\n      render: ({ row }) => {\n        let h1 = \'\'\n        let h2 = \'\'\n        if (row.zd && row.zd == \'1\') {\n          h1 = h(\'div\', { style: { width: \'52px\', height: \'20px\', borderRadius: \'26px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', fontSize: \'12px\', backgroundColor: \'#0099FF\', color: \'white\', marginRight: \'8px\' } }, \'置顶\')\n        }\n        if (row.rm && row.rm == \'1\') {\n          h2 = h(\'div\', { style: { width: \'52px\', height: \'20px\', borderRadius: \'26px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', fontSize: \'12px\', backgroundColor: \'#FF7A8C\', color: \'white\' } }, \'热门\')\n        }\n\n        return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [h1, h2])\n      }\n    })\n\n    useFun.setPropConfig(\'create_time\', {\n      render: ({ row }) => {\n        const numH = h(\'span\', { style: { fontSize: \'14px\', color: \'#999999\', fontFamily: \'MicrosoftYaHei, 微软雅黑, sans-serif\', marginRight: \'5px\' } }, row.create_time)\n        const iconTitH = h(Icon, { icon: \'mingcute:time-line\', size: \'17\', style: { marginRight: \'3px\', color: \'#999999\', } })\n        return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\', height: \'28px\' } }, [iconTitH, numH])\n      }\n    })\n\n    useFun.setPropConfig(\'lll\', {\n      render: ({ row }) => {\n        const numH = h(\'span\', { style: { fontSize: \'12px\', color: \'#999999\', fontFamily: \'微软雅黑, sans-serif\', marginRight: \'5px\' } }, row.lll)\n        const iconTitH = h(\'span\', { style: { color: \'#999999\', fontSize: \'12px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [h(Icon, { icon: \'lsicon:view-outline\', size: \'20\', style: { marginRight: \'3px\' } }), \'浏览\'])\n        return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\', height: \'36.8px\' } }, [iconTitH, numH])\n      }\n    })\n\n    useFun.setPropConfig(\'hfl\', {\n      render: ({ row }) => {\n        const numH = h(\'span\', { style: { fontSize: \'12px\', color: \'#999999\', fontFamily: \'微软雅黑, sans-serif\', marginRight: \'5px\' } }, row.hfl)\n        const iconTitH = h(\'span\', { style: { color: \'#999999\', fontSize: \'12px\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\' } }, [h(Icon, { icon: \'ri:wechat-pay-line\', size: \'20\', style: { marginRight: \'3px\' } }), \'回复\'])\n        return h(\'div\', { style: { display: \'flex\', alignItems: \'center\', justifyContent: \'center\', height: \'36.8px\' } }, [iconTitH, numH])\n      }\n    })\n\n    if (props.enhanceData && props.enhanceData.type == \'view\') {\n      tableOption.value.menu = false\n      tableOption.value.selection = false\n      tableOption.value.header = false\n      tableOption.value.index = false\n\n    }\n\n  },\n\n\n  cellClick(row, column, cell, event) { //单元格单击\n    if (column.prop == \'htbt\') {\n      controlView_article.value.show = true //显示ControlView\n      const controlData = controlView_article.value.params //ControlView的配置\n      controlData.controlParams = {\n        data: row,\n        hideFun: () => {\n          controlView_article.value.show = false\n          //控件调用\n          formView_htbj.value.show = true //显示FormView\n          const controlData = formView_htbj.value.params //FormView的配置\n\n          controlData.defaultData = row\n          controlData.enhanceData = {\n            type:\'update\'\n          }\n        }\n      }\n    }\n  },\n}');
INSERT INTO `lowcode_dbform_enhance_js` VALUES (1854727383615254530, '1', 1, '2024-11-08 11:27:22', 101, 1, '2024-11-08 15:01:38', 0, 1854716968965484545, 'scss', '// 表格样式\n.low-table__1854716968965484545 {\n\n  .avue-crud__grid {\n    .el-checkbox-group {\n      .avue-crud__grid__content {\n        height: 90px;\n        padding: 0 16px;\n        align-items: center;\n        border: none;\n        border-radius: 0;\n        border-bottom: 1px solid #e4e7ed;\n\n        &::before {\n          height: 0;\n        }\n\n        .avue-crud__grid__item {\n          width: auto;\n\n          .avue-crud__grid__label {\n            display: none;\n          }\n        }\n\n        .cytx {\n          .avue-crud__img {\n            img {\n              width: 48px;\n              height: 48px;\n              border-radius: 50%;\n            }\n          }\n        }\n\n        .htbt {\n          position: absolute;\n          top: 15px;\n          left: 75px;\n          width: 350px;\n\n          .avue-crud__grid__value {\n            font-family: \"微软雅黑 Bold\", \"微软雅黑 Regular\", 微软雅黑, sans-serif;\n            font-weight: 700;\n            font-size: 16px;\n            color: rgb(102, 102, 102);\n            cursor: pointer;\n            height: 28px;\n            line-height: 28px;\n\n            &:hover {\n              color: rgb(64, 158, 255);\n            }\n          }\n\n        }\n\n        .sd,\n        .zdrm_tit {\n          position: absolute;\n          top: 15px;\n          margin-bottom: 0;\n\n          .avue-crud__grid__value {\n            height: 28px;\n            display: flex;\n            align-items: center;\n          }\n        }\n\n        .sd {\n          left: 435px;\n        }\n\n        .zdrm_tit {\n          left: 460px;\n        }\n\n        .create_user,\n        .create_time {\n          position: absolute;\n          top: 43px;\n\n\n          .avue-crud__grid__value {\n            font-family: \'MicrosoftYaHei\', \'微软雅黑\', sans-serif;\n            font-weight: 400;\n            color: #999999;\n          }\n        }\n\n        .create_user {\n          left: 75px;\n        }\n\n        .create_time {\n          left: 155px;\n        }\n\n        .lll {\n          margin-left: auto;\n        }\n\n        .hfl {\n          padding-right: 4px;\n        }\n      }\n\n    }\n  }\n\n  .avue-crud__pagination {\n    margin-bottom: 40px;\n  }\n}\n\n// 表单弹窗样式\n.low-table__dialog__1854716968965484545 {}');
