INSERT INTO `lowcode_dbform_enhance_sql` VALUES (1834497496137732097, '1', 1, '2024-09-13 15:41:01', 101, 1, '2024-09-13 15:41:10', 0, 1833031105253642242, 'page', 'SELECT\r\n	stu.*,\r\n	sco.score_test \r\nFROM\r\n	example_student stu\r\n	LEFT JOIN example_score sco ON stu.id = sco.student_id AND sco.is_deleted = 0 \r\nWHERE\r\n	#{jeelowcode_auto_where}', '1', '0', 1, 'N');
INSERT INTO `lowcode_dbform_enhance_sql` VALUES (1834511320169517057, '1', 1, '2024-09-13 16:35:57', 101, NULL, '2024-09-13 16:44:08', 1, 1833031105253642242, 'add', 'INSERT INTO example_score \r\n(\r\n  id,\r\n  student_id,\r\n  course_id,\r\n  tenant_id,\r\n  create_user,\r\n  create_time,\r\n  create_dept,\r\n  update_user,\r\n  update_time,\r\n  is_deleted,\r\n  score_test\r\n)\r\nVALUES\r\n(\r\n  #{jeelowcode_id},\r\n  #{jeelowcode_main_id},\r\n  1,\r\n  #{jeelowcode_tenant_id},\r\n  #{jeelowcode_user_id},\r\n  #{jeelowcode_date_time},\r\n  NULL,\r\n  NULL,\r\n  null,\r\n  0,\r\n  100\r\n)', '', '0', 1, 'Y');
INSERT INTO `lowcode_dbform_enhance_sql` VALUES (1834529741871390722, '1', 1, '2024-09-13 17:49:09', 101, NULL, '2024-09-14 16:24:34', 1, 1833031105253642242, 'detail', 'SELECT\r\n	stu.*,\r\n	sco.score_test \r\nFROM\r\n	example_student stu\r\n	LEFT JOIN example_score sco ON stu.id = sco.student_id AND sco.is_deleted = 0 \r\nWHERE\r\n	stu.is_deleted = 0\r\nLIMIT 1', '111', '0', 1, 'N');
