INSERT INTO `lowcode_dbform_summary` VALUES (1834524983552413698, '1', 1, '2024-09-13 17:30:15', 101, NULL, '2024-12-03 13:59:14', 0, 1834136609367400450, NULL, 'top', 'Y', 'SELECT\r\n	SUM( tabs_card_target_money ) AS target,\r\n	SUM( tabs_card_accomplish_money ) AS accomplish,\r\n	tabs_card_date AS e_date \r\nFROM\r\n	example_tabs_card \r\nWHERE\r\n	is_deleted = 0 \r\nGROUP BY\r\n	tabs_card_date \r\nORDER BY\r\n	tabs_card_date ASC \r\n	LIMIT 12', '', '{\"summarySql\":{\"sqlObj\":{\"top\":[],\"buttom\":[]},\"valueType\":\"custom\",\"custom\":\"SELECT\\r\\n\\tSUM( tabs_card_target_money ) AS target,\\r\\n\\tSUM( tabs_card_accomplish_money ) AS accomplish,\\r\\n\\ttabs_card_date AS e_date \\r\\nFROM\\r\\n\\texample_tabs_card \\r\\nWHERE\\r\\n\\tis_deleted = 0 \\r\\nGROUP BY\\r\\n\\ttabs_card_date \\r\\nORDER BY\\r\\n\\ttabs_card_date ASC \\r\\n\\tLIMIT 12\",\"group\":\"SELECT  FROM (#{jeelowcode_summary_table}) tbl \",\"formattingObj\":{\"text\":\"\",\"card_name\":\"\",\"card_value\":\"\",\"line_x\":\"\",\"line_y\":\"\",\"line_y_unit\":\"\",\"bar_x\":\"#{e_date}\",\"bar_y\":\"目标金额 成交金额\",\"bar_y_unit\":\"\",\"pie_value\":\"\",\"pie_name\":\"\",\"pie_unit\":\"\"},\"summaryControl\":\"bar\"},\"summaryControl\":\"bar\",\"summarySpan\":24}');
INSERT INTO `lowcode_dbform_summary` VALUES (1834524983812460545, '1', 1, '2024-09-13 17:30:15', 101, NULL, '2024-12-03 13:59:14', 0, 1834136609367400450, NULL, 'top', 'Y', 'SELECT\r\n	tabs_card_target_money AS target,\r\n	tabs_card_accomplish_money AS accomplish,\r\n	tabs_card_percentage_complete AS wcl \r\nFROM\r\n	example_tabs_card \r\nWHERE\r\n	is_deleted = 0 \r\nORDER BY\r\n	tabs_card_date DESC \r\n	LIMIT 1', '', '{\"summarySql\":{\"sqlObj\":{\"top\":[],\"buttom\":[]},\"valueType\":\"custom\",\"custom\":\"SELECT\\r\\n\\ttabs_card_target_money AS target,\\r\\n\\ttabs_card_accomplish_money AS accomplish,\\r\\n\\ttabs_card_percentage_complete AS wcl \\r\\nFROM\\r\\n\\texample_tabs_card \\r\\nWHERE\\r\\n\\tis_deleted = 0 \\r\\nORDER BY\\r\\n\\ttabs_card_date DESC \\r\\n\\tLIMIT 1\",\"group\":\"SELECT  FROM (#{jeelowcode_summary_table}) tbl \",\"formattingObj\":{\"text\":\"目标金额 ：￥#{target}，成交金额 ：￥#{accomplish}，完成率：#{wcl} %\",\"card_name\":\"\",\"card_value\":\"\",\"line_x\":\"\",\"line_y\":\"\",\"line_y_unit\":\"\",\"bar_x\":\"\",\"bar_y\":\"\",\"bar_y_unit\":\"\",\"pie_value\":\"\",\"pie_name\":\"\",\"pie_unit\":\"\"},\"summaryControl\":\"text\"},\"summaryControl\":\"text\",\"summarySpan\":12}');
