INSERT INTO `lowcode_desform` VALUES (1844550190467956737, '1', 1, '2024-10-11 09:26:50', 101, 1, '2024-12-27 11:19:10', 0, '管理模块-订单详情-头部', '{\"jsEnhance\":\"//初始化收货人表单\\nuseFun.controlInit(\'FormView\', \'formView_xgshr\', {\\n  formId: \'1834792963683192834\', //表单设计id\\n  formType: \'add\', //表单类型 add | edit | view\\n  handleType: \'default\', //处理类型 default | returnData\\n  showType: \'dialog\', //弹窗类型 dialog | drawer\\n  defaultData: {\\n  }, //默认表单数据\\n  enhanceData: {\\n  }, //传递给表单js增强内部调用配置\\n  showButton: false,\\n  popOption: { //弹窗配置\\n    title: \'收货人信息\', //标题\\n    width: \'35%\', //弹窗宽度\\n    fullscreen: false, //是否全屏\\n    footerBtn: [ //底部按钮配置\\n      {\\n        params: {}, //el-button 其他参数\\n        name: \'取消\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          //点击事件\\n          if (loading) loading() //关闭loading\\n          formView_xgshr.value.show = false\\n        }\\n      },\\n      {\\n        params: {\\n          type: \'primary\',\\n        }, //el-button 其他参数\\n        name: \'保存\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          message.success(\'保存成功\')\\n          //点击事件\\n          setTimeout(() => {\\n            if (loading) loading() //关闭loading\\n            formView_xgshr.value.show = false\\n          }, 500)\\n        }\\n      }\\n    ],\\n    headerBtn: [], //顶部按钮配置（配置同上）\\n    dialogParams: {\\n    } //弹窗其他配置\\n  },\\n  beforeClose: (type, done, formData, loading) => {\\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\\n    if (type == \'submit\') {\\n      if (obj.loading) obj.loading() //关闭loading方法\\n    }\\n    done()\\n  }\\n})\\n\\n//初始化发票表单\\nuseFun.controlInit(\'FormView\', \'formView_xgfp\', {\\n  formId: \'1834837596136083458\', //表单设计id\\n  formType