\r\\n    controlView_25095.value.show = true //显示ControlView\\r\\n    const controlData = controlView_25095.value.params //ControlView的配置\\r\\n    controlData.controlParams = {\\r\\n      type: \'clr\',\\r\\n      obj: formData.value\\r\\n    }\\r\\n\\r\\n  }\\r\\n}\",\"text\":false},{\"label\":\"发起人\",\"prop\":\"btn_fqr\",\"id\":\"btn_3444\",\"icon\":\"\",\"type\":\"primary\",\"display\":true,\"viewShow\":false,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    //控件调用\\r\\n    const { controlView_25095 } = Vue.toRefs(rendControlData.value)\\r\\n    const controlData = controlView_25095.value.params //ControlView的配置\\r\\n    controlData.controlParams = {\\r\\n      type: \'fqr\',\\r\\n      obj: formData.value\\r\\n    }\\r\\n    controlView_25095.value.show = true //显示ControlView\\r\\n  }\\r\\n}\"}],\"location\":\"center\"},\"display\":true,\"span\":24,\"disabled\":false,\"hideLabel\":true}},\"group\":[]}', NULL, 'N', 'N');
INSERT INTO `lowcode_desform` VALUES (1844943768151142401, '1', 1, '2024-10-12 11:30:46', 101, 1, '2024-11-12 15:18:00', 0, '工单管理-头部', '{\"jsEnhance\":\"//初始化收货人表单\\nuseFun.controlInit(\'FormView\', \'formView_xgshr\', {\\n  formId: \'1845725929011695618\', //表单设计id\\n  formType: \'add\', //表单类型 add | edit | view\\n  handleType: \'default\', //处理类型 default | returnData\\n  showType: \'dialog\', //弹窗类型 dialog | drawer\\n  defaultData: {\\n  }, //默认表单数据\\n  enhanceData: {\\n  }, //传递给表单js增强内部调用配置\\n  showButton: false,\\n  popOption: { //弹窗配置\\n    title: \'收货人信息\', //标题\\n    width: \'\', //弹窗宽度\\n    fullscreen: false, //是否全屏\\n    footerBtn: [ //底部按钮配置\\n      {\\n        params: {}, //el-button 其他参数\\n        name: \'取消\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          //点击事件\\n          if (loading) loading() //关闭loading\\n          formView_xgshr.value.show = false\\n        }\\n      },\\n      {\\n        params: {\\n          type: \'primary\',\\n        }, //el-button 其他参数\\n        name: \'保存\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          message.success(\'保存成功\')\\n          //点击事件\\n          setTimeout(() => {\\n            if (loading) loading() //关闭loading\\n            formView_xgshr.value.show = false\\n          }, 500)\\n        }\\n      }\\n    ],\\n    headerBtn: [], //顶部按钮配置（配置同上）\\n    dialogParams: {\\n    } //弹窗其他配置\\n  },\\n  beforeClose: (type, done, formData, loading) => {\\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\\n    if (type == \'submit\') {\\n      if (obj.loading) obj.loading() //关闭loading方法\\n    }\\n    done()\\n  }\\n})\\n\\n\\n\\nconst { formView_xgshr } = Vue.toRefs(rendControlData.value)\\n\\n\\n//打开按钮的表单\\nuseFun.openForm = (formView_value, obj, title, ID) => {\\n  if (formView_value) {\\n\\n    const controlData = formView_value.value.params //ControlView的配置\\n    formView_value.value.show = true //显示FormView\\n    controlData.defaultData = obj\\n    controlData.popOption.title = title\\n    if (ID) {\\n      controlData.formId = ID\\n    }\\n  }\\n}\\n\\nreturn {\\n  initData(formData) {\\n    return new Promise(resolve => {\\n      if (formData.lx == \'clr\') {\\n        useFun.setPropConfig(\'btn_group\', {\\n          display: true, //禁用age\\n        })\\n      } else {\\n        useFun.setPropConfig(\'btn_fqr\', {\\n          display: true, //禁用age\\n        })\\n      }\\n      const obj = {\\n        \'dcl\': [],\\n        \'ywj\': [0, 1, 2],\\n        \'yth\': [1, 4],\\n        \'ycx\': [1, 2],\\n        \'fqr\': [4]\\n      }\\n\\n      if (obj[formData.lx].length > 0) {\\n        obj[formData.lx].map(item => {\\n          useFun.getPropConfig(\'btn_fqr\').params.buttonList[item].display = false\\n        })\\n      }\\n      resolve(formData)\\n    })\\n  },\\n  initOption() { //表单显示前执行\\n  },\\n}\\n\\n\\n\\n\",\"scssEnhance\":\".low-form__1844943768151142401 {\\n  //样式请写在当前位置内\\n\\n  padding: 0 !important;\\n\\n  .btn_group_class {\\n    padding-right: 0 !important;\\n\\n    .el-form-item{\\n      margin-bottom: 0;\\n    }\\n  }\\n}\",\"labelPosition\":\"right\",\"labelSuffix\":\" \",\"labelWidth\":120,\"gutter\":20,\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":false,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"size\":\"default\",\"column\":{\"btn_group\":{\"type\":\"buttonList\",\"controlType\":\"\",\"label\":\"按钮组\",\"params\":{\"buttonList\":[{\"label\":\"完结工单\",\"prop\":\"wjgd_btn\",\"id\":\"btn_881\",\"icon\":\"ep:check\",\"type\":\"primary\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    //控件调用\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'完结工单\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'wjgd\'\\r\\n    }, title)\\r\\n\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"退回工单\",\"prop\":\"th_btn\",\"id\":\"btn_3844\",\"icon\":\"ep:close\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'退回工单\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'thgd\'\\r\\n    }, title)\\r\\n  }\\r\\n}\\r\\n\",\"plain\":false,\"text\":false,\"round\":false,\"circle\":false,\"link\":false},{\"label\":\"转他人处理\",\"prop\":\"ztrcl_btn\",\"id\":\"btn_7084\",\"icon\":\"ep:switch\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'转他人处理\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'ztrcl\'\\r\\n    }, title)\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"上传附件\",\"prop\":\"fj_btn\",\"id\":\"btn_5956\",\"icon\":\"ep:paperclip\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'上传附件\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'scfj\'\\r\\n    }, title)\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"打印工单\",\"prop\":\"dy_btn\",\"id\":\"btn_8480\",\"icon\":\"ep:printer\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    // const { formView_gbdd } = Vue.toRefs(rendControlData.value)\\r\\n    // useFun.openForm(formView_gbdd)\\r\\n  }\\r\\n}\\r\\n\"}],\"location\":\"right\"},\"display\":false,\"span\":24,\"disabled\":false,\"hideLabel\":true,\"offset\":0,\"className\":\"btn_group_class\"},\"btn_fqr\":{\"type\":\"buttonList\",\"controlType\":\"\",\"label\":\"按钮组\",\"params\":{\"buttonList\":[{\"label\":\"编辑工单\",\"prop\":\"wjgd_btn\",\"id\":\"btn_881\",\"icon\":\"ep:edit-pen\",\"type\":\"primary\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    //控件调用\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'新建工单\'\\r\\n    const id = \'1844632600228409345\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'bjgd\'\\r\\n    }, title, id)\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"撤销工单\",\"prop\":\"th_btn\",\"id\":\"btn_3844\",\"icon\":\"ep:refresh-left\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'撤销工单\'\\r\\n    const id = \'1845725929011695618\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'cxgd\'\\r\\n    }, title, id)\\r\\n  }\\r\\n}\\r\\n\",\"plain\":false,\"text\":false,\"round\":false,\"circle\":false,\"link\":false},{\"label\":\"上传附件\",\"prop\":\"fj_btn\",\"id\":\"btn_5956\",\"icon\":\"ep:paperclip\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    const { formView_xgshr } = Vue.toRefs(rendControlData.value)\\r\\n    const title = \'上传附件\'\\r\\n    const id = \'1845725929011695618\'\\r\\n    useFun.openForm(formView_xgshr, {\\r\\n      lx: \'scfj\'\\r\\n    }, title, id)\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"打印工单\",\"prop\":\"dy_btn\",\"id\":\"btn_8480\",\"icon\":\"ep:printer\",\"type\":\"\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n     message.confirm(\'开发测试中...\', \'操作确认\', { type: \'warning\' })\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"删除工单\",\"prop\":\"scgd_btn\",\"id\":\"btn_9582\",\"icon\":\"ep:delete\",\"type\":\"\",\"display\":true,\"viewShow\":false,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    message.confirm(\'是否确定删除数据？\', \'操作确认\', { type: \'warning\' })\\r\\n  }\\r\\n}\"}],\"location\":\"right\"},\"display\":false,\"span\":24,\"disabled\":false,\"hideLabel\":true,\"offset\":0,\"className\":\"btn_group_class\"}},\"group\":[]}', 1829756131023052802, 'N', 'N');
INSERT INTO `lowcode_desform` VALUES (1845002998170267649, '1', 1, '2024-10-12 15:26:08', 101, 1, '2024-12-27 11:28:09', 0, '工单管理-订单详情', '{\"jsEnhance\":\"return {\\n  initData(formData) {\\n    return new Promise(resolve => { //初始化默认值\\n\\n      let arr = [\'sphjje\', \'yf\', \'yhj\', \'jfzk\', \'hdyh\', \'zkje\', \'ddje\', \'yfkje\']\\n      arr.forEach(ele => {\\n        if (formData[ele]) {\\n          let je = formData[ele]\\n          if (isNaN(parseFloat(je))) return false\\n          let newJe = Math.round(je * 100) / 100\\n          let newJeString = newJe.toString()\\n          let newJeLength = newJeString.indexOf(\'.\')\\n          if (newJeLength < 0) {\\n            newJeLength = newJeString.length;\\n            newJeString += \'.\'\\n          }\\n          while (newJeString.length <= newJeLength + 2) {\\n            newJeString += \'0\'\\n          }\\n          formData[ele] = \'￥\' + newJeString\\n        } else {\\n          formData[ele] = \'￥0.00\'\\n        }\\n      })\\n\\n\\n      resolve(formData)\\n    })\\n  },\\n  beforeSubmit(submitData) { //提交前数据处理\\n    return new Promise((resolve, reject) => {\\n      console.log(submitData, \'biahihg\')\\n      resolve(submitData)\\n    })\\n  },\\n}\\n\",\"scssEnhance\":\".low-form__1845002998170267649 {\\n  padding: 0 10px 20px 10px !important;\\n\\n  //样式请写在当前位置内\\n  .el-form {\\n    .el-row {\\n      border: none;\\n      margin: 0 !important;\\n\\n      .red {\\n        .el-form-item__content {\\n          input {\\n            color: red;\\n          }\\n        }\\n      }\\n\\n      .input:nth-child(5) {\\n        .el-form-item {\\n          border-right: 1px solid #e9e9e9;\\n        }\\n      }\\n\\n      .input:nth-child(9) {\\n        .el-form-item {\\n          border-right: 1px solid #e9e9e9;\\n        }\\n      }\\n\\n      .input:nth-child(12) {\\n        .el-form-item {\\n          border-right: 1px solid #e9e9e9;\\n        }\\n      }\\n\\n      .input {\\n        .el-form-item {\\n          border-left: 1px solid #e9e9e9;\\n\\n          border-bottom: 1px solid #e9e9e9;\\n\\n          .el-form-item__label {\\n            background-color: #F5F5F5;\\n            padding: 0 20px !important;\\n          }\\n\\n          .el-form-item__content {\\n            // padding-left: 20px;\\n          }\\n        }\\n      }\\n\\n      .border-left-box {\\n        .el-form-item {\\n          .el-form-item__label {\\n            border-left: 1px solid #ebeef5;\\n          }\\n\\n          .el-form-item__content {\\n            // border-left: 1px solid #ebeef5;\\n          }\\n        }\\n      }\\n\\n      .el-form-item__label,\\n      .el-form-item__content,\\n      .el-form-item__content .el-select__selection,\\n      .el-form-item__content .user-input {\\n        height: 55px;\\n        line-height: 55px;\\n      }\\n\\n      .ddxq-title-class {\\n        border: none;\\n        border-bottom: 1px solid #ebeef5;\\n        font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\\n        font-weight: 700;\\n        margin-top: 15px !important;\\n\\n        .el-form-item {\\n          background: initial;\\n\\n          .el-form-item__content {\\n            height: 60px;\\n            line-height: 60px;\\n            border: none !important;\\n            padding: 0;\\n\\n            p {\\n              height: auto;\\n              line-height: normal;\\n              padding-left: 10px;\\n              margin: 15px 0;\\n              border-left: 7px solid #409EFF;\\n            }\\n          }\\n        }\\n      }\\n\\n      .mtop {\\n        margin-top: 0 !important;\\n        border-left: none !important;\\n\\n\\n      }\\n\\n      .bottom {\\n        margin-top: 25px !important;\\n\\n        .el-form-item__content {\\n          bottom: 5px;\\n        }\\n      }\\n\\n\\n      .el-form-item__label,\\n      .el-form-item__content .el-input,\\n      .el-form-item__content .el-select__selection {\\n        font-family: \'微软雅黑 Bold\', \