INSERT INTO `lowcode_desform` VALUES (1846114280447025153, '1', 1, '2024-10-15 17:01:58', 101, 1, '2024-11-12 16:50:11', 0, '职务管理-头部', '{\"jsEnhance\":\"//初始化收货人表单\\nuseFun.controlInit(\'FormView\', \'formView_xgshr\', {\\n  formId: \'1846092785716961282\', //表单设计id\\n  formType: \'add\', //表单类型 add | edit | view\\n  handleType: \'default\', //处理类型 default | returnData\\n  showType: \'dialog\', //弹窗类型 dialog | drawer\\n  defaultData: {\\n  }, //默认表单数据\\n  enhanceData: {\\n  }, //传递给表单js增强内部调用配置\\n  showButton: false,\\n  popOption: { //弹窗配置\\n    title: \'收货人信息\', //标题\\n    width: \'35%\', //弹窗宽度\\n    fullscreen: false, //是否全屏\\n    footerBtn: [ //底部按钮配置\\n      {\\n        params: {}, //el-button 其他参数\\n        name: \'取消\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          //点击事件\\n          if (loading) loading() //关闭loading\\n          formView_xgshr.value.show = false\\n        }\\n      },\\n      {\\n        params: {\\n          type: \'primary\',\\n        }, //el-button 其他参数\\n        name: \'保存\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          message.success(\'保存成功\')\\n          //点击事件\\n          setTimeout(() => {\\n            if (loading) loading() //关闭loading\\n            formView_xgshr.value.show = false\\n          }, 500)\\n        }\\n      }\\n    ],\\n    headerBtn: [], //顶部按钮配置（配置同上）\\n    dialogParams: {\\n    } //弹窗其他配置\\n  },\\n  beforeClose: (type, done, formData, loading) => {\\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\\n    if (type == \'submit\') {\\n      if (obj.loading) obj.loading() //关闭loading方法\\n    }\\n    done()\\n  }\\n})\\n\\n\\n\\nconst { formView_xgshr } = Vue.toRefs(rendControlData.value)\\n\\n\\n//打开按钮的表单\\nuseFun.openForm = (formView_value, obj, title, ID) => {\\n  formView_value.value.show = true //显示FormView\\n  const controlData = formView_value.value.params //ControlView的配置\\n  controlData.defaultData = obj\\n  controlData.popOption.title = title\\n  if (ID) {\\n    controlData.formId = ID\\n  }\\n}\\n\\nreturn {\\n  initData(formData) {\\n    return new Promise(resolve => {\\n      if (formData.lx == \'clr\') {\\n        useFun.setPropConfig(\'btn_group\', {\\n          display: true, //禁用age\\n        })\\n      } else {\\n        useFun.setPropConfig(\'btn_fqr\', {\\n          display: true, //禁用age\\n        })\\n      }\\n      const obj = {\\n        \'dcl\': [],\\n        \'ywj\': [0, 1, 2],\\n        \'yth\': [1, 4],\\n        \'ycx\': [1, 2],\\n        \'fqr\': [4]\\n      }\\n\\n      if (obj[formData.lx].length > 0) {\\n        obj[formData.lx].map(item => {\\n          useFun.getPropConfig(\'btn_fqr\').params.buttonList[item].display = false\\n        })\\n      }\\n      resolve(formData)\\n    })\\n  },\\n}\\n\\n\\n\\n\",\"scssEnhance\":\".low-form__1846114280447025153 {\\n  //样式请写在当前位置内\\n\\n  .zw_btn {\\n    .el-form-item {\\n      margin-bottom: 0;\\n\\n      .el-button {\\n        color: #999;\\n        font-family: 微软雅黑, sans-serif;\\n        width: 110px;\\n        height: 35px;\\n\\n        .el-icon {\\n          span {\\n            font-size: 16px;\\n          }\\n        }\\n\\n        &.el-button--primary {\\n          color: white;\\n        }\\n      }\\n    }\\n\\n  }\\n}\",\"labelPosition\":\"right\",\"labelSuffix\":\" \",\"labelWidth\":120,\"gutter\":20,\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":false,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"size\":\"default\",\"column\":{\"btn_group\":{\"type\":\"buttonList\",\"controlType\":\"\",\"label\":\"按钮组\",\"params\":{\"buttonList\":[{\"label\":\"完结工单\",\"prop\":\"wjgd_btn\",\"id\":\"btn_881\",\"icon\":\"ep:check\",\"type\":\"primary\",\"display\":true,\"viewShow\":true,\"btnLoading\":false,\"con