INSERT INTO `lowcode_desform` VALUES (1847209781133185025, '1', 1, '2024-10-18 17:35:06', 101, 1, '2024-11-20 16:16:31', 0, '项目管理-项目详情-头部', '{\"jsEnhance\":\"//初始化收货人表单\\nuseFun.controlInit(\'FormView\', \'formView_xgshr\', {\\n  formId: \'1846092785716961282\', //表单设计id\\n  formType: \'add\', //表单类型 add | edit | view\\n  handleType: \'default\', //处理类型 default | returnData\\n  showType: \'dialog\', //弹窗类型 dialog | drawer\\n  defaultData: {\\n  }, //默认表单数据\\n  enhanceData: {\\n  }, //传递给表单js增强内部调用配置\\n  showButton: false,\\n  popOption: { //弹窗配置\\n    title: \'收货人信息\', //标题\\n    width: \'\', //弹窗宽度\\n    fullscreen: false, //是否全屏\\n    footerBtn: [ //底部按钮配置\\n      {\\n        params: {}, //el-button 其他参数\\n        name: \'取消\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          //点击事件\\n          if (loading) loading() //关闭loading\\n          formView_xgshr.value.show = false\\n        }\\n      },\\n      {\\n        params: {\\n          type: \'primary\',\\n        }, //el-button 其他参数\\n        name: \'保存\', //按钮名称\\n        display: true, //是否显示\\n        loading: true, //点击时是否有loading\\n        icon: \'\', //图标\\n        clickFun: (loading) => {\\n          message.success(\'保存成功\')\\n          //点击事件\\n          setTimeout(() => {\\n            if (loading) loading() //关闭loading\\n            formView_xgshr.value.show = false\\n          }, 500)\\n        }\\n      }\\n    ],\\n    headerBtn: [], //顶部按钮配置（配置同上）\\n    dialogParams: {\\n    } //弹窗其他配置\\n  },\\n  beforeClose: (type, done, formData, loading) => {\\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\\n    if (type == \'submit\') {\\n      if (obj.loading) obj.loading() //关闭loading方法\\n    }\\n    done()\\n  }\\n})\\n\\n\\n\\nconst { formView_xgshr } = Vue.toRefs(rendControlData.value)\\n\\n\\n//打开按钮的表单\\nuseFun.openForm = (formView_value, obj, title, ID) => {\\n  formView_value.value.show = true //显示FormView\\n  const controlData = formView_value.value.params //ControlView的配置\\n  controlData.defaultData = obj\\n  controlData.popOption.title = title\\n  if (ID) {\\n    controlData.formId = ID\\n  }\\n}\\n\\nreturn {\\n  initData(formData) {\\n    return new Promise(resolve => { //初始化默认值\\n      formData.tb = \'http://oss.yckxt.com/chatgpt/upload/1/2024-10-18/1/tb_6.jpg\'\\n      formData.zt = formData.zt == 1 ? \'正常\' : \'异常\'\\n      formData.kxfw = formData.kxfw == 1 ? \'参与人员可见\' : \'所有人员可见\'\\n      if (!formData.fzr) {\\n        formData.fzr = \'赵小刚\'\\n      }\\n      let jd = useFun.getPropConfig(\'xmjd\')\\n      jd.params = {\\n        jdt: 50,\\n      }\\n\\n      resolve(formData)\\n    })\\n  },\\n}\\n\",\"scssEnhance\":\".low-form__1847209781133185025 {\\n\\n  //样式请写在当前位置内\\n  .img {\\n    .el-upload {\\n      border: none;\\n\\n      .avue-upload__avatar {\\n        margin: 0;\\n        padding: 0;\\n        width: 60px;\\n        height: 60px;\\n      }\\n    }\\n\\n  }\\n\\n  .xmjd {\\n    text-align: right !important;\\n  }\\n\\n  element.style {\\n    padding-left: 0 !important;\\n  }\\n\\n  .title {\\n    padding: 0 !important;\\n\\n    .avue-title p {\\n      margin: 0 !important;\\n      margin-top: -2px !important;\\n      margin-left: -10px;\\n      padding: 0 !important;\\n      font-family: \'微软雅黑 Bold\', \'微软雅黑\', sans-serif !important;\\n      font-weight: 700 !important;\\n      font-size: 18px;\\n      color: #666666;\\n    }\\n  }\\n\\n  .text {\\n    padding: 0 !important;\\n    position: absolute;\\n    top: 30px;\\n    left: 105px;\\n\\n    .avue-title p {\\n      margin: 0 !important;\\n      margin-top: -2px !important;\\n      margin-left: -10px;\\n      padding: 0 !important;\\n      font-family: \'微软雅黑 Bold\', \'微软雅黑\', sans-serif !important;\\n      font-weight: 400 !important;\\n      font-size: 14px;\\n      color: #999;\\n    }\\n  }\\n\\n  .input {\\n    .el-input_