Key\":[\"mobile\",\"sex\",\"deptName\"],\"display\":true,\"span\":18,\"disabled\":false,\"required\":false,\"hideLabel\":false,\"multiple\":true,\"avatar\":false,\"offset\":5},\"tdjs\":{\"type\":\"textarea\",\"controlType\":\"input\",\"label\":\"团队描述\",\"readonly\":false,\"minRows\":5,\"maxRows\":5,\"display\":true,\"span\":18,\"disabled\":false,\"required\":false,\"hideLabel\":false,\"showWordLimit\":true,\"maxlength\":100,\"placeholder\":\"输入内容\",\"className\":\"flex-start\",\"offset\":5}},\"tableDesignId\":\"1851205230887346177\",\"group\":[]}', NULL, 'N', 'N');
INSERT INTO `lowcode_desform` VALUES (1852223511034294274, '1', 1, '2024-11-01 13:37:52', 101, 1, '2024-11-15 15:55:11', 0, '相册详情-头部', '{\"jsEnhance\":\"\\n//初始化控件\\nuseFun.controlInit(\'FormView\', \'formView_xc\', {\\n  formId: \'\', //表单设计id\\n  formType: \'add\', //表单类型 add | edit | view\\n  handleType: \'\', //处理类型 default | returnData\\n  showType: \'dialog\', //弹窗类型 dialog | drawer\\n  showButton: true, //是否显示底部默认操作按钮\\n  dataOption: { //数据配置 \\n    tableId: \'\', //表单开发id\\n    dataId: \'\' //数据id\\n  },\\n  defaultData: {}, //默认表单数据\\n  enhanceData: {}, //传递给表单js增强内部调用配置\\n  popOption: { //弹窗配置\\n    title: \'测试表单\', //标题\\n    width: \'\', //弹窗宽度\\n    fullscreen: false, //是否全屏\\n    footerBtn: [ //底部按钮配置\\n      // {\\n      //   params: {}, //el-button 其他参数\\n      //   name: \'测试按钮\', //按钮名称\\n      //   display: true, //是否显示\\n      //   loading: true, //点击时是否有loading\\n      //   icon: \'\', //图标\\n      //   clickFun: (loading) => {\\n      //     //点击事件\\n      //     if (loading) loading() //关闭loading\\n      //   }\\n      // }\\n    ],\\n    headerBtn: [], //顶部按钮配置（配置同上）\\n    dialogParams: {} //弹窗其他配置\\n  },\\n  beforeClose: (type, done, formData, loading) => {\\n    // type:关闭类型  submit:提交后触发  close:直接关闭弹窗触发\\n    // done:关闭弹窗方法 formData:表单数据  loading:关闭loading方法\\n    if (type == \'submit\') {\\n      console.log(\'表单数据\', formData)\\n    }\\n    done()\\n  }\\n})\\n\\nconst { formView_xc } = Vue.toRefs(rendControlData.value)\\n\\n//打开按钮的表单\\nuseFun.openForm = (formView_value, obj, title, ID) => {\\n  formView_value.value.show = true //显示FormView\\n  const controlData = formView_value.value.params //ControlView的配置\\n  controlData.defaultData = obj\\n  controlData.popOption.title = title\\n  if (ID) {\\n    controlData.formId = ID\\n  }\\n}\\nreturn {\\n  initData(formData) {\\n    return new Promise(resolve => { //初始化默认值\\n      formData.zt_img = \'../../../../../public/img/xc.png\'\\n      formData.num = \'100\'\\n      formData.time = \'8小时前\'\\n      resolve(formData)\\n    })\\n  },\\n}\\n\",\"scssEnhance\":\".low-form__1852223511034294274 {\\n\\n  //样式请写在当前位置内\\n  .avue-upload__avatar {\\n    width: 120px;\\n    height: 120px;\\n  }\\n\\n  .title {\\n    font-family: \'微软雅黑 Bold\', \'微软雅黑 Regular\', \'微软雅黑\', sans-serif;\\n    font-weight: 700;\\n    font-size: 18px;\\n    color: #666666;\\n    margin-left: 25px;\\n    margin-top:-5px;\\n  }\\n\\n  .text {\\n    position: absolute;\\n    left: 25px;\\n    top: 25px;\\n    font-family: \'微软雅黑\', sans-serif;\\n    font-weight: 400;\\n    color: #999999;\\n\\n    .avue-title p {\\n      font-size: 14px;\\n    }\\n  }\\n\\n  .right-text {\\n    .avue-title p {\\n      font-family: \'微软雅黑\', sans-serif;\\n      font-weight: 400;\\n      color: #999999;\\n      font-size: 14px;\\n      margin-right: 0;\\n    }\\n\\n    .avue-title p::before {\\n      content: \'12\';\\n      width: 15px;\\n      height: 15px;\\n      background-image: url(\'../../../../../public/img/sl.jpg\');\\n      background-size: 100%;\\n      background-repeat: no-repeat;\\n      background-position: center center;\\n      color: rgba(0, 0, 0, 0);\\n    }\\n  }\\n\\n  .right-time {\\n    .avue-title p {\\n      font-family: \'微软雅黑\', sans-serif;\\n      font-weight: 400;\\n      color: #999999;\\n      font-size: 14px;\\n    }\\n\\n    .avue-title p::before {\\n      content: \'12\';\\n      width: 15px;\\n      height: 15px;\\n      background-image: url(\'../../../../../public/img/time.jpg\');\\n      background-size: 100%;\\n      background-repeat: no-repeat;\\n      background-position: center center;\\n      color: rgba(0, 0, 0, 0);\\n    }\\n  }\\n\\n  .btn {\\n    position: absolute;\\n    left: 35px;\\n    top: 86px;\\n  }\\n}\",\"labelPosition\":\"right\",\"labelSuffix\":\" \",\"labelWidth\":120,\"gutter\":20,\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":false,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"size\":\"default\",\"isSubmitTable\":t