"type\":\"buttonList\",\"controlType\":\"\",\"label\":\"按钮组\",\"params\":{\"buttonList\":[{\"label\":\"发布\",\"prop\":\"btn_5696\",\"id\":\"btn_5696\",\"icon\":\"\",\"type\":\"primary\",\"display\":true,\"viewShow\":false,\"btnLoading\":true,\"configStr\":\"return {\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    if (props.enhanceData.type) {\\r\\n      useFun.submitForm(true)\\r\\n      if (props.enhanceData.type == \'add\') {\\r\\n        props.enhanceData.updateDialog()\\r\\n      }\\r\\n\\r\\n    }\\r\\n    message.success(\'发布成功\')\\r\\n    if (obj.loading) obj.loading() //关闭loading方法\\r\\n  }\\r\\n}\\r\\n\"},{\"label\":\"重置\",\"prop\":\"btn_3946\",\"id\":\"btn_3946\",\"icon\":\"\",\"type\":\"primary\",\"display\":true,\"viewShow\":false,\"btnLoading\":true,\"configStr\":\"return {\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    handleClear()\\r\\n    if (obj.loading) obj.loading() //关闭loading方法\\r\\n  }\\r\\n}\\r\\n\",\"plain\":true}],\"location\":\"left\"},\"display\":true,\"span\":24,\"disabled\":false,\"hideLabel\":true,\"className\":\"btn-list\"}},\"tableDesignId\":\"1854716968965484545\",\"group\":[]}', NULL, 'N', 'N');
INSERT INTO `lowcode_desform` VALUES (1856521825921736705, '1', 1, '2024-11-13 10:17:50', NULL, 1, '2024-11-13 15:37:41', 0, '日历新增', '{\"jsEnhance\":\"return {\\n  beforeSubmit(submitData) { //提交前数据处理\\n    return new Promise((resolve, reject) => {\\n\\n      resolve(submitData)\\n    })\\n  },\\n}\\n\",\"scssEnhance\":\"\",\"labelPosition\":\"right\",\"labelSuffix\":\" \",\"labelWidth\":120,\"gutter\":20,\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":false,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"size\":\"default\",\"isSubmitTable\":false,\"column\":{\"kssj\":{\"type\":\"datetime\",\"controlType\":\"date\",\"label\":\"开始时间\",\"clearable\":true,\"format\":\"YYYY-MM-DD HH:mm:ss\",\"valueFormat\":\"YYYY-MM-DD HH:mm:ss\",\"display\":true,\"span\":12,\"disabled\":false,\"required\":true,\"hideLabel\":false,\"value\":[]},\"jssj\":{\"type\":\"datetime\",\"controlType\":\"date\",\"label\":\"结束时间\",\"clearable\":true,\"format\":\"YYYY-MM-DD HH:mm:ss\",\"valueFormat\":\"YYYY-MM-DD HH:mm:ss\",\"display\":true,\"span\":12,\"disabled\":false,\"required\":true,\"hideLabel\":false,\"value\":[]},\"example_sub_more_date\":{\"type\":\"layoutTable\",\"controlType\":\"layout\",\"label\":\"表格布局\",\"dataType\":\"array\",\"tableType\":\"cellEdit\",\"btnData\":{\"menu\":[],\"header\":[]},\"tableEnhanceStr\":\"\",\"params\":{\"headerAlign\":\"center\",\"align\":\"center\",\"addBtn\":true,\"delBtn\":true,\"editBtn\":true,\"selection\":true,\"border\":true,\"menuWidth\":120},\"column\":{\"title\":{\"type\":\"input\",\"controlType\":\"input\",\"label\":\"日程标题\",\"readonly\":false,\"clearable\":true,\"display\":true,\"span\":12,\"disabled\":false,\"required\":true,\"hideLabel\":false},\"ms\":{\"type\":\"textarea\",\"controlType\":\"input\",\"label\":\"描述\",\"readonly\":false,\"minRows\":3,\"maxRows\":5,\"display\":true,\"span\":24,\"disabled\":false,\"required\":false,\"hideLabel\":false}},\"display\":true,\"span\":24,\"hideLabel\":true},\"fields_8261657\":{\"type\":\"buttonList\",\"controlType\":\"\",\"label\":\"按钮组\",\"params\":{\"buttonList\":[{\"label\":\"取消\",\"prop\":\"btn_qx\",\"id\":\"btn_1913\",\"icon\":\"\",\"type\":\"\",\"display\":true,\"viewShow\":false,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    props.enhanceData.addFun()\\r\\n    handleClear()\\r\\n  }\\r\\n}\"},{\"label\":\"保存\",\"prop\":\"btn_bc\",\"id\":\"btn_5005\",\"icon\":\"\",\"type\":\"primary\",\"display\":true,\"viewShow\":false,\"btnLoading\":false,\"configStr\":\"return {\\r\\n  //其他配置请参考element-plus button配置\\r\\n  //当前按钮的点击事件\\r\\n  handleClick: (obj) => {\\r\\n    formData.value.example_sub_more_date.map(item => {\\r\\n      delete item.id\\r\\n      return item\\r\\n    })\\r\\n    useFun.requestApi(\'post\', \'jeelowcode/dbform-data/save/1850723645460291586\', {\\r\\n      data: formData.value\\r\\n    }).then(res => {\\r\\n      props.enhanceData.addFun()\\r\\n      handleClear()\\r\\n    })\\r\\n\\r\\n  }\\r\\n}\"}],\"location\":\"right\"},\"display\":true,\"span\":24,\"disabled\":false,\"hideLabel\":true}},\"tableDesignId\":\"1850723645460291586\",\"group\":[]}', NULL, 'N', 'N');
INSERT INTO `lowcode_desform` VALUES (1862065125842554881, '1', 1, '2024-11-28 17:24:56', 101, 1, '2024-11-28 17:54:20', 0, '学生请假申请表', '{\"jsEnhance\":\"return {\\n  initOption() { //表单显示前执行\\n    useFun.setPropConfig(\'qj_time\', {\\n      change: ({ value }) => {\\n        let num = \'\'\\n        if (value) {\\n          const times = value.split(\',\')\\n          num = useFun.betweenDay(times[0], times[1]) + 1\\n        }\\n        formData.value.qj_num = num\\n      },\\n    })\\n  },\\n  initData(formData) {\\n    const userStore = useFun.useUserStoreWithOut()\\n    return new Promise(resolve => { //初始化默认值\\n      if (props.formType == \'add\') {\\n        formData.qj_user = userStore.user.id\\n      }\\n      resolve(formData)\\n    })\\n  },\\n}\\n\",\"scssEnhance\":\".low-form__1862065125842554881 {\\n  //样式请写在当前位置内\\n}\",\"labelPosition\":\"right\",\"labelSuffix\":\" \",\"labelWidth\":120,\"gutter\":20,\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":false,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"size\":\"default\",\"isSubmitTable\":true,\"column\":{\"qj_user\":{\"type\":\"userSelect\",\"controlType\":\"select\",\"label\":\"请假人\",\"findType\":\"all\",\"columnKey\":[\"mobile\",\"sex\",\"deptName\"],\"display\":true,\"span\":12,\"disabled\":true,\"required\":false,\"hideLabel\":false},\"qj_time\":{\"type\":\"daterange\",\"controlType\":\"date\",\"label\":\"请假时间\",\"clearable\":true,\"format\":\"YYYY-MM-DD\",\"valueFormat\":\"YYYY-MM-DD\",\"display\":true,\"span\":12,\"disabled\":false,\"required\":true,\"hideLabel\":false,\"value\":[],\"moreOptionStr\":\"return {\\n\\n}\"},\"qj_num\":{\"type\":\"input\",\"controlType\":\"input\",\"label\":\"请假天数\",\"readonly\":false,\"clearable\":true,\"display\":true,\"span\":12,\"disabled\":true,\"required\":false,\"hideLabel\":false},\"qj_yy\":{\"type\":\"textarea\",\"controlType\":\"input\",\"label\":\"请假原因\",\"readonly\":false,\"minRows\":3,\"maxRows\":5,\"display\":true,\"span\":24,\"disabled\":false,\"required\":true,\"hideLabel\":false}},\"group\":[]}', NULL, 'N', 'N');
