  `table_style` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '单表样式',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ind_table_name`(`table_name`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '表单开发' ROW_FORMAT = Dynamic;

